  Activity_100432_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「แมลงสะกดจิต」เปิดให้เล่น ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งมีเคลเมนไทน์ เพื่อเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะเล่นด่านกิจกรรม จะไม่สามารถปรับเปลี่ยนร่างตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·เมื่อผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_100433_ActivityName = {
    Text = "บิชอปแห่งเมตตา"
  },
  Activity_100433_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「บิชอปแห่งเมตตา」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งรวมซัลวาดอร์ เพื่อทดลองเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะทดลองเล่นด่านกิจกรรม ไม่สามารถปรับเปลี่ยนผู้ตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·หลังจากผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
