  Activity_123150_ActivityName = {
    Text = "แม่มดล่าหัวกะโหลก"
  },
  Activity_123150_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「แม่มดล่าหัวกะโหลก」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งรวมดาฟเดล เพื่อทดลองเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะทดลองเล่นด่านกิจกรรม ไม่สามารถปรับเปลี่ยนผู้ตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·หลังจากผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_123151_ActivityName = {
    Text = "จ้าวแห่งซากศพ"
  },
  Activity_123151_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「จ้าวแห่งซากศพ」เปิดให้เล่น ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งมีดูเลเซน เพื่อเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะเล่นด่านกิจกรรม จะไม่สามารถปรับเปลี่ยนร่างตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·เมื่อผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
