  Activity_124051_ActivityName = {
    Text = "พิธีบูชายัญแห่งห้วงลึก·รีรัน"
  },
  Activity_124051_ActivityPlot = {
    Text = "บนเงาสะท้อนของทะเลลึก ความฝันของกษัตริย์ได้จางหายไป อาณาจักรของเทพก็ได้เน่าเปื่อยแล้ว \nเธอเดินออกมาจากภาพลวงในวันเก่า เข้าสู่ซากปรักหักพังของอนาคตที่พังทลาย \nเธอถามเหว เหวเงียบงัน \nเธอถวายสักการะให้เหว สิ่งที่ตอบกลับเธอมีเพียงตัวเธอเอง"
  },
  Activity_124051_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลงแล้ว，ขณะนี้สามารถเข้าร่วมได้เฉพาะ「การตอบสนองจากห้วงลึก」เท่านั้น"
  },
  Activity_124051_ActivityTips = {
    Text = "<Title:บทสรุปกิจกรรม>\n1,     ในช่วงกิจกรรม ผู้พิทักษ์สามารถรวบรวมสกุลเงินกิจกรรมผ่านการเล่นแบบจำกัดเวลา「การเกิดของประเทศเทพ」,     「พระบัญชาของพระราชา」และ「รางวัลความสำเร็จ」ได้ โดยสกุลเงินกิจกรรมสามารถใช้ใน「การตอบกลับของความลึกซึ้ง」เพื่อบูชารับรางวัลเป็นไอเทม รวมถึงวงล้อ SR จำกัดกิจกรรม「การเรียกของทะเลลึก」,     หินของนักปราชญ์,     แกนบริสุทธิ์,     แกนกลางของลูเมน เป็นต้น.\n2,     ในช่วงกิจกรรม「โลกแห่งความฝันประหลาด：การดูหมิ่น」จะเปิดให้ใช้งานฟรี และหากทำสำเร็จในกิจกรรมจะได้รับภาพโปรไฟล์จำกัดกิจกรรม「ในนามของกุญแจเงิน：มิเรียม」！.\n\n<Title:เวลาในการจัดกิจกรรม>\n1,     9 มีนาคม 9:00 - 23 มีนาคม 9:00(GMT+8) ทุกเนื้อหาของกิจกรรมสามารถเข้าร่วมได้.\n2,     23 มีนาคม 9:00 - 30 มีนาคม 9:00(GMT+8) จะเหลือเพียง「การตอบกลับของความลึกซึ้ง」และ「รางวัลความสำเร็จ」เท่านั้น เนื้อหาอื่นๆ จะสิ้นสุดและไม่สามารถเข้าร่วมได้.\n\n<Title: การเกิดของประเทศเทพ>\n1,     「การเกิดของประเทศเทพ」มี 5 ด่าน โดยจะเปิดอัตโนมัติทุก 2 วัน.\n2,     การท้าทายแต่ละครั้งจะใช้「เมโนฟิน」× 120 และหากท้าทายสำเร็จจะได้รับสกุลเงินกิจกรรม.\n3,     เมื่อผ่านด่าน สามารถปลดล็อกฟังก์ชัน「ทำซ้ำ」ของด่านนั้น โปรดทราบว่า: ในการใช้ฟังก์ชัน「ทำซ้ำ」จะไม่สามารถรับอัตราการประสานได้.\n4,     สามารถใช้การช่วยเหลือจากสมาคมศิษย์เก่าและ「การสะท้อน：พิธีบูชายัญแห่งห้วงทะเลลึก」เพื่อช่วยให้ผ่านด่านได้ง่ายขึ้น.\n\n<Title:โบนัสเครื่องสังเวย>\n1,     ผู้พิทักษ์ที่มีตัวปลุกตื่นหรือวงล้อเฉพาะ(ไม่จำเป็นต้องเข้าร่วม) จะทำให้「การเกิดของประเทศเทพ」มีรางวัลภารกิจที่「น้ำตาของผู้บูชา」,     「เลือดของผู้บูชา」และ「ไขกระดูกของผู้บูชา」ได้รับโบนัสการดรอปเพิ่มเติม(รวมถึงการทำซ้ำ) โดยมีรายละเอียดดังนี้：\n·ตัวปลุกตื่น「มิเรียม」: การตื่นพลัง 0/1/2/3 และมากกว่า เพิ่ม 20%/30%/40%/50%\n·วงล้อ SSR「พลังแห่งความศรัทธา」: ตำแหน่งซ้อน 0/1/2/3 และมากกว่า เพิ่ม 20%/30%/40%/50%\n·วงล้อ SR「การเรียกของทะเลลึก」: ตำแหน่งซ้อน 0/1/2/3 และมากกว่า เพิ่ม 20%/30%/40%/50%\n2,     โบนัสเครื่องสังเวยจากตัวปลุกตื่นหรือวงล้อที่แตกต่างกันจะถูกคำนวณในลักษณะรวม.\n3,     พิเศษ รางวัลการท้าทายครั้งแรกในระดับความยากบ้าคลั่งจะไม่ได้รับผลกระทบจาก「โบนัสเครื่องสังเวย」.\n\n<Title:การสะท้อน：พิธีบูชายัญแห่งห้วงทะเลลึก>\n1,     ผู้พิทักษ์สามารถรับ「หัวใจแห่งความศรัทธา」ได้โดยการทำสำเร็จในกิจกรรม.\n2,     ใช้「หัวใจแห่งความศรัทธา」เพื่อเปิดใช้งาน「การสะท้อน：พิธีบูชายัญแห่งห้วงทะเลลึก」จะได้รับโบนัสดังนี้：\n(1)ทำให้ผู้พิทักษ์ในกิจกรรม「การเกิดของประเทศเทพ」แข็งแกร่งขึ้น ทำให้การท้าทายง่ายขึ้น.\n(2)เพิ่มสกุลเงินกิจกรรมที่ได้รับหลังจากทำสำเร็จใน「การเกิดของประเทศเทพ」.\n(3)เปิดใช้งานกิจกรรม「พระบัญชาของพระราชา」.\n\n<Title:พระบัญชาของพระราชา>\n·เมื่อเปิดใช้งานการสะท้อน「การทดลองการเสียสละ」จะได้รับ「น้ำตาของผู้บูชา」60 ทุกชั่วโมง โดยสามารถเก็บได้สูงสุด 25 ชั่วโมง.\n\n<Title:การตอบกลับของความลึกซึ้ง>\n1,     「การตอบกลับของความลึกซึ้ง」มีสามแท่นบูชา เวลาที่เปิดใช้งานมีดังนี้：\n·「อัลเทอร์แห่งน้ำตาที่ระยิบระยับ」: 9 มีนาคม 9:00 ~ 30 มีนาคม 9:00.\n·「แท่นบูชาเลือดลิง」: 11 มีนาคม 9:00 ~ 30 มีนาคม 9:00.\n·「บัลลังก์วิญญาณ」: 13 มีนาคม 9:00 ~ 30 มีนาคม 9:00.\n2,     การบูชาครั้งแต่ละครั้งจะใช้「น้ำตาของผู้บูชา」/「เลือดของผู้บูชา」/「ไขกระดูกของผู้บูชา」× 750 และจะได้รับรางวัลเป็นไอเทม 5 ชิ้นจากแท่นบูชาแบบสุ่ม.\n3,     รางวัลไอเทมจากแต่ละแท่นบูชาจะแบ่งเป็น「วัสดุพิเศษ」และ「ของธรรมดา」 โดยเมื่อรีเซ็ตจะทำให้จำนวนของไอเทมที่กำหนดกลับไปที่จำนวนสูงสุด โดยมีกฎระเบียบดังนี้：\n(1)การรีเซ็ต 3 ครั้งแรก: เมื่อ「วัสดุพิเศษ」ไม่มีจำนวนเหลือ ผู้พิทักษ์สามารถเลือกรีเซ็ต โดยหลังจากรีเซ็ตจะทำให้จำนวนของ「วัสดุพิเศษ」และ「ของธรรมดา」กลับไปที่จำนวนสูงสุด; สามารถเลือกที่จะบูชาต่อได้ เมื่อ「ของธรรมดา」ไม่มีจำนวนเหลือ ต้องทำการรีเซ็ตเพื่อบูชาต่อได้.\n(2)การรีเซ็ตครั้งที่ 4 ขึ้นไป: เมื่อ「ของธรรมดา」ไม่มีจำนวนเหลือจึงจะสามารถทำการรีเซ็ตได้ การรีเซ็ตจะทำให้จำนวนของ「ของธรรมดา」กลับไปที่จำนวนสูงสุด แต่「วัสดุพิเศษ」จะไม่ถูกรีเซ็ตอีกต่อไป.\n\n<Title:โลกแห่งความฝันประหลาด>\n1,     ในช่วงกิจกรรม「โลกแห่งความฝันประหลาด：การดูหมิ่น」จะเปิดให้ใช้งานฟรี.\n2,     หลังจากสิ้นสุดกิจกรรม ความก้าวหน้าในการสำรวจ「โลกแห่งความฝันประหลาด：การดูหมิ่น」จะถูกเก็บรักษา หากในช่วงกิจกรรมยังไม่ได้ปลดล็อก「โลกแห่งความฝันประหลาด：การดูหมิ่น」 หลังจากสิ้นสุดกิจกรรมยังสามารถใช้「จุดเริ่มต้นของความเป็นจริง」×7 เพื่อปลดล็อกได้.\n3,     ไม่ว่าจะอยู่ในช่วงกิจกรรมหรือไม่ หลังจากผ่าน「โลกแห่งความฝันประหลาด：การดูหมิ่น」จะได้รับ「คำสั่งกุญแจ：ระเริงกระแสคลื่น」.\n\n<Title:การชดเชยการทำซ้ำ>\n1,     ผู้พิทักษ์ที่เคยปลดล็อก「โลกแห่งความฝันประหลาด：การดูหมิ่น」ในช่วงกิจกรรมซ้ำนี้จะได้รับ「น้ำตาของผู้บูชา」×700 เป็นการชดเชยเมื่อปลดล็อกอีกครั้งในช่วงกิจกรรมนี้.\n2,     ผู้พิทักษ์ที่เคยได้รับภาพโปรไฟล์จำกัดกิจกรรม「ในนามของกุญแจเงิน：มิเรียม」เมื่อได้รับอีกครั้งจะถูกแปลงอัตโนมัติเป็น「คำเชิญของวิญญาณไร้รูปร่าง」×1.\n3,     ผู้พิทักษ์ที่เคยได้รับวัสดุเปิดใช้งาน「หัวใจแห่งความศรัทธา」เมื่อได้รับ「หัวใจแห่งความศรัทธา」เกิน 1 ชิ้น จะถูกแปลงอัตโนมัติเป็น「คูปองกุหลาบทอง」×5000.\n"
  },
