  Activity_126492_ActivityTips = {
    Text = "<Title: โบราณประเทศซ่าจู่>\n·การเดินทางจำกัดเวลาครั้งนี้ประกอบด้วย 8 ชุดของขวัญ,     ซึ่งในนั้นชุดแรกสามารถรับได้ฟรีทันที,     ชุดที่ 2-8 จะต้องซื้อ「โบราณประเทศซ่าจู่」ก่อนจึงจะสามารถรับได้.\n·หลังจากซื้อ「โบราณประเทศซ่าจู่」สามารถรับรางวัลชุดที่ 2 ได้ทันที；ชุดของขวัญถัดไปจะต้องรอเวลาที่กำหนดจึงจะสามารถรับได้.\n·หากซื้อ「โบราณประเทศซ่าจู่」ก่อนเวลา 9:00 น. ของวันที่ 26 มกราคม จะได้รับรางวัลเพิ่มเติม：รูปโปรไฟล์พิเศษ「รูปแบบที่แท้จริงในพัด」และ「คำเชิญของวิญญาณไร้รูปร่าง」×10！หลังจากเวลา 9:00 น. ของวันที่ 26 มกราคม จะไม่มีการมอบรางวัลพิเศษจำกัดเวลาอีกต่อไป.\n·หลังจากซื้อแล้วระยะเวลาของการเดินทางจำกัดเวลานี้จะกลายเป็นถาวร,     เมื่อรับชุดของขวัญทั้งหมดแล้วกิจกรรมจะสิ้นสุดในวันถัดไป.\n·การซื้อ「โบราณประเทศซ่าจู่」มีเวลาจำกัด,     หากเกินกำหนดจะไม่สามารถซื้อได้อีก.กรุณาผู้พิทักษ์ควรพิจารณาซื้อก่อนเวลา 9:00 น. ของวันที่ 23 กุมภาพันธ์."
  },
  Activity_126492_BannerText = {
    Text = "กิจกรรมบันทึกการเดินทางพิเศษเปิดให้บริการจำกัดเวลา!"
  },
  Activity_127173_ActivityName = {
    Text = "จิตรกร"
  },
  Activity_127173_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「จิตรกร」เปิดให้เล่น ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งมีพิคแมน เพื่อเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะเล่นด่านกิจกรรม จะไม่สามารถปรับเปลี่ยนร่างตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·เมื่อผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_129488_ActivityName = {
    Text = "รถไฟความสุขที่วิ่งอย่างรวดเร็ว"
  },
  Activity_129488_ActivityPlot = {
    Text = "บนรถไฟ เสียงคำรามหงุดหงิดดังออกมาจากห้องพักหรูอย่างไม่ขาดสาย\n「ซัลวาดอร์ ตู้ที่สามต้องการกำลังเสริม!」\n「วันดา ส่งศัตรูที่เธอควบคุมไปท้ายขบวน พวกมันไล่ตามมาแล้ว!」\n「เลค! หยุดจีบเขาได้แล้ว! มาไล่พวกนอกหน้าต่างฉันเดี๋ยวนี้!」\nขณะที่คุณกำลังวุ่นวายอยู่ในห้องโดยสารหรู กลับไม่ทันสังเกตว่าร่างเล็กๆ ร่างหนึ่งได้แอบลอดเข้ามาในกระเป๋าของคุณแล้ว\n「ฮิฮิ แบบนี้สิถึงจะสนุก」\n「ถ่ายภาพได้ดีเลยนะ～ งั้นต่อไป——ถึงเวลาผู้ช่วยตัวน้อย」N「ออกโรงแล้ว～」"
  },
  Activity_129488_ActivityTips = {
    Text = "<Title:รายละเอียดกิจกรรม>\n1. ในช่วงกิจกรรม ผู้พิทักษ์ความลับสามารถรับรางวัลจำกัดเวลามากมายผ่าน「เส้นทางขบวนรถ」 หลังกิจกรรมสิ้นสุด จะไม่สามารถรับรางวัลใน「เส้นทางขบวนรถ」ได้อีก กรุณารับรางวัลจำกัดเวลาให้ทันเวลา\n2. ในช่วงกิจกรรม การเข้าร่วม「ขบวนรถออกเดินทาง」จะได้รับการชดเชยเลเวล โดยมีกฎเกณฑ์ดังนี้：\n · ร่างตื่นในทีมสำรวจที่มีเลเวลไม่ถึง 60 จะได้รับการชดเชยเป็นเลเวล 60 ในการท้าทายครั้งนี้\n · ร่างตื่นในทีมสำรวจที่มีเลเวลสกิลไม่ถึง 5 จะได้รับการชดเชยเป็นเลเวล 5 ในการท้าทายครั้งนี้\n · ร่างตื่นในทีมสำรวจที่มี「ลางแห่งความบ้าคลั่ง」ไม่ถึงเลเวล 6 จะได้รับการชดเชยเป็นเลเวล 6 ในการท้าทายครั้งนี้\n · ร่างตื่นในทีมสำรวจที่มี「ความเข้ากันของจิตวิญญาณ」ไม่ถึงเลเวล 5 จะได้รับการชดเชยเป็นเลเวล 5 ในการท้าทายครั้งนี้\n · หากเลเวลของผู้พิทักษ์ความลับไม่ถึง 60 จะได้รับการชดเชยเป็นเลเวล 60 ในการท้าทายครั้งนี้\n\n<Title:บันทึกหน่วยเฉพาะกิจ>\n1. ในช่วงกิจกรรม「บันทึกหน่วยเฉพาะกิจ：ขบวนรถสู่เทศกาลฉีซุ่ย」จะเปิดให้เล่นฟรี\n2. หลังกิจกรรมสิ้นสุด ความคืบหน้าการสำรวจของ「บันทึกหน่วยเฉพาะกิจ：ขบวนรถสู่เทศกาลฉีซุ่ย」จะถูกเก็บรักษาไว้ หากไม่ได้ปลดล็อก「บันทึกหน่วยเฉพาะกิจ：ขบวนรถสู่เทศกาลฉีซุ่ย」ในช่วงกิจกรรม หลังกิจกรรมสิ้นสุดยังสามารถใช้「จุดเริ่มต้นแห่งความจริง」×7 เพื่อปลดล็อกได้\n3. ไม่ว่าจะอยู่ในช่วงกิจกรรมหรือไม่ เมื่อผ่าน「บันทึกหน่วยเฉพาะกิจ：ขบวนรถสู่เทศกาลฉีซุ่ย」แล้วจะได้รับ「กุญแจคำสั่ง：ดอกไม้ไฟส่งท้ายปี」\n\n<Title:ขบวนรถแห่งความสุขเร่งฝีเท้า>\n1.「ขบวนรถแห่งความสุขเร่งฝีเท้า」เป็นโหมดท้าทายต่อเนื่องที่ใช้กฎ「บทแห่งดวงดาว」 ผู้พิทักษ์ความลับจะท้าทายบอสสุดท้ายที่เคยปรากฏในการสำรวจหลายตัวอย่างต่อเนื่องท่ามกลางเหตุการณ์สุ่มที่หลากหลาย！\n2. ในโหมดนี้ ขีดจำกัดสูงสุดของสิ่งสร้างที่ถือครองได้สามารถเพิ่มได้สูงสุดถึง 36 ชิ้น\n3. ในระหว่างการท้าทาย สามารถครอบครองและเสริมพลังเอฟเฟกต์「สั่นพ้อง」อันทรงพลังจากการสำรวจได้พร้อมกัน 3 ชนิด\n4. ทุกครั้งที่ใช้ร่างจิตวิญญาณฉุกเฉิน 1 ครั้ง จะลด「คะแนน VIP」ที่ได้รับจากการท้าทายครั้งนี้ลง 20%\n5. รองรับการออกกลางคันและเก็บความคืบหน้า แต่สถานะทีมจะไม่อัปเดตตามการพัฒนาภายนอก ความคืบหน้าจะเก็บรักษาได้สูงสุด 7 วันหลังจากการท้าทายครั้งล่าสุด หากไม่ท้าทายต่อในช่วงเก็บรักษา จะถือว่าสละสิทธิ์การท้าทายและความคืบหน้าจะไม่ถูกเก็บรักษาอีกต่อไป\n\n<Title:รายชื่อ VIP>\n1. ในช่วงกิจกรรม บันทึกใน「รายชื่อ VIP」จะถูกเก็บรักษาไว้ หลังกิจกรรมสิ้นสุดจะรีเซ็ตบันทึกตามรอบกิจกรรมของสถาบัน\n2.「รายชื่อ VIP」จะบันทึกผู้พิทักษ์ความลับที่มีผลงานการท้าทายยอดเยี่ยม ผู้พิทักษ์ความลับที่ท้าทาย 1 ครั้งในแต่ละรอบกิจกรรมสถาบันและได้รับ「คะแนน VIP」สำเร็จจะสามารถเข้าสู่「รายชื่อ VIP」ได้\n3. อันดับใน「รายชื่อ VIP」จะอิงจาก「คะแนน VIP」สูงสุดที่ได้รับจากการท้าทายครั้งเดียวและ「จำนวนเทิร์น」ที่ใช้น้อยที่สุดเป็นเกณฑ์ สามารถท้าทายซ้ำเพื่อเพิ่มอันดับได้\n\n<Title:ระยะเวลากิจกรรม>\n1. 9 กุมภาพันธ์ 9:00 – 9 มีนาคม 9:00(GMT+8) สามารถเข้าร่วมเนื้อหากิจกรรมทั้งหมดได้\n2. หลังจาก 9 มีนาคม 9:00(GMT+8) กิจกรรมจะถูกบันทึกไว้ใน「ระเบียงแห่งความทรงจำ」 รางวัลใน「เส้นทางขบวนรถ」จะไม่สามารถรับได้อีก"
  },
