  Activity_130175_ActivityPlot = {
    Text = "โลกนี้ช่างเงียบเหงานัก โลกนี้ช่างรกร้างว่างเปล่านัก จงรับฟังเถิด จงเป็นพยานเถิด\nเนื้อหนังที่คร่ำครวญรอคอยในความเงียบงันอันยาวนาน รอคอยดอกแดนดิไลออนบานกลางทะเลทราย\nแล้วมันจะถูกเติมเต็มด้วยความรักที่เปล่งประกาย และได้รับชีวิตใหม่อีกครั้ง"
