  Activity_131370_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n1,     หลังจากผู้พิทักษ์ทำภารกิจบันทึกการเดินทางที่กำหนดเสร็จแล้ว สามารถรับรางวัลได้ใน「ผู้โชคดี」\n2,     「ผู้โชคดี」จะสิ้นสุดในวันที่ 6 เมษายน เวลา 9:00\n3,     หลังจากปลดล็อก「บันทึกการเดินทางขั้นสูง」แล้ว จะสามารถรับรางวัลเพิ่มเติมหลังทำภารกิจเสร็จ\n4,     โปรดทราบ：「บันทึกการเดินทางขั้นสูง」ที่ปลดล็อกในกิจกรรมนี้มีผลเฉพาะในกิจกรรมนี้เท่านั้น กรุณาให้ผู้พิทักษ์พิจารณาใช้จ่ายอย่างมีเหตุผล"
  },
  Activity_131370_BannerText = {
    Text = "กิจกรรมบันทึกการเดินทางพิเศษเปิดให้บริการจำกัดเวลา!"
