  Activity_131849_ActivityName = {
    Text = "ความทรงจำนิรันดร์"
  },
  Activity_131849_ActivityTips = {
    Text = "<Title: ความทรงจำนิรันดร์>\n·บันทึกการเดินทางจำกัดเวลานี้ประกอบด้วย 8 แพ็กเกจ โดยแพ็กเกจแรกสามารถรับฟรีได้โดยตรง แพ็กเกจที่ 2–8 ต้องซื้อ「ความทรงจำนิรันดร์」ก่อนจึงจะรับได้\n·หลังซื้อ「ความทรงจำนิรันดร์」จะสามารถรับรางวัลแพ็กเกจที่ 2 ได้ทันที แพ็กเกจถัดไปต้องรอเวลาที่กำหนดก่อนจึงจะรับได้\n·หากซื้อ「ความทรงจำนิรันดร์」ก่อน 30 พฤษภาคม 9：00 จะได้รับรางวัลพิเศษเพิ่มเติม：อวาตาร์พิเศษ「การล่าอันแสนสนุก」และ「บัตรเชิญจากผู้ไร้รูป」×10！หากซื้อหลัง 30 พฤษภาคม 9：00 จะไม่ได้รับรางวัลพิเศษจำกัดเวลาอีกต่อไป\n·「ความทรงจำนิรันดร์」มีระยะเวลาจำกัดในการซื้อ หากเลยกำหนดจะไม่สามารถซื้อได้อีก กรุณาพิจารณาซื้อก่อน 29 มิถุนายน 9：00"
  },
  Activity_131849_BannerText = {
    Text = "กิจกรรมบันทึกการเดินทางพิเศษเปิดให้บริการจำกัดเวลา!"
