    Text = "ปลดล็อกด่านเนื้อเรื่องรองฟรี"
  },
  Activity_132333_ActivityName = {
    Text = "การฟื้นคืนชีพของพระราชาเทพ"
  },
  Activity_132333_ActivityPlot = {
    Text = "ในคำอธิษฐานที่เต็มไปด้วยความปรารถนามากมาย พระองค์ทรงตื่นขึ้นชั่วขณะจากการหลับลึกอันยาวนาน ทอดสายตาที่แท้จริงไปยังโลกที่ไร้ความหมาย\nในชีวิตนิรันดร์ สายตานั้นช่างสั้นมาก"
  },
  Activity_132333_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลงแล้ว ปัจจุบันสามารถเข้าร่วมได้เฉพาะ「ห้วงทะเลแห่งการรู้แจ้ง」เท่านั้น"
  },
  Activity_132333_ActivityTips = {
    Text = "<Title:ข้อมูลกิจกรรม>\n1 ในระยะเวลากิจกรรม ผู้พิทักษ์สามารถรวบรวมสกุลเงินกิจกรรม「ความคิดเหนื่อยล้า」,「ความคิดเศร้าหมอง」,「ความคิดที่เต็มไปด้วยความสุข」ผ่านการเล่นแบบจำกัดเวลา「มองของทะเลลึก」และ「รางวัลความสำเร็จ」.สกุลเงินกิจกรรมสามารถใช้ซื้อสินค้าที่「เหวแห่งทะเลแห่งการรับรู้」รวมถึงวงล้อชีวิต SR ที่มีจำกัดกิจกรรม「บัลลังก์หินสีฟ้า」,แกนกลางของลูเมน,แกนบริสุทธิ์,เศษหินปัญญา,คริสตัลเลียนแบบ ฯลฯ.\n2 ในระยะเวลากิจกรรม การทำความสำเร็จของกิจกรรมยังสามารถได้รับภาพโปรไฟล์ที่มีจำกัด「ชื่อของกุญแจเงิน：ธูลู」,วงล้อชีวิต SR ที่มีจำกัดกิจกรรม「บัลลังก์หินสีฟ้า」,เงินใจ และสกุลเงินกิจกรรมจำนวนมาก！\n\n<Title:ระยะเวลากิจกรรม>\n1 วันที่ 6 เมษายน 9:00 - วันที่ 4 พฤษภาคม 9:00 (GMT+8) สามารถเข้าร่วมกิจกรรมได้ทุกแบบ.\n2 วันที่ 4 พฤษภาคม 9:00 - วันที่ 11 พฤษภาคม 9:00 (GMT+8) สามารถเข้าร่วมได้เฉพาะ「เหวแห่งทะเลแห่งการรับรู้」และรางวัลความสำเร็จ.\n\n<Title:มองของทะเลลึก>\n1「มองของทะเลลึก」มี 5 ด่าน โดยจะเปิดอัตโนมัติทุก 2 วัน.\n2 การท้าทายแต่ละครั้งจะใช้「เมโนฟิน」× 120 หากท้าทายสำเร็จจะได้รับสกุลเงินกิจกรรม.\n3 หลังจากผ่านด่าน จะปลดล็อกฟังก์ชัน「ทำซ้ำ」ของด่านนั้น โปรดทราบว่าเมื่อใช้ฟังก์ชัน「ทำซ้ำ」จะไม่สามารถได้รับอัตราการประสาน.\n4 สามารถใช้การสนับสนุนจากสมาคมนักเรียนเพื่อช่วยให้ผ่านด่านได้ง่ายขึ้น.\n\n<Title:การเพิ่มพูนความคิด>\n1 ผู้พิทักษ์ที่มีตัวปลุกตื่นหรือวงล้อชีวิตเฉพาะ (ไม่ต้องการให้ลงสนาม) จะทำให้สกุลเงินกิจกรรมในรางวัลภารกิจของด่าน「มองของทะเลลึก」ได้รับการเพิ่มพูนตกหล่นเพิ่มเติม โดยมีการเพิ่มพูนดังนี้：\n· ตัวปลุกตื่น「ธูลู」：การตื่นพลัง 0/1/2/3 และสูงกว่า จะเพิ่ม 20%/30%/40%/50%.\n· วงล้อชีวิต SSR「เพลงสรรเสริญเทวราชา」：ตำแหน่งซ้อน 0/1/2/3 และสูงกว่า จะเพิ่ม 20%/30%/40%/50%.\n· วงล้อชีวิต SR「บัลลังก์หินสีฟ้า」：ตำแหน่งซ้อน 0/1/2/3 และสูงกว่า จะเพิ่ม 20%/30%/40%/50%.\n2 การ「เพิ่มพูนความคิด」จากตัวปลุกตื่นหรือวงล้อชีวิตที่แตกต่างกันจะถูกคำนวณในลักษณะรวมกัน.\n3 โดยเฉพาะอย่างยิ่ง รางวัลความสำเร็จจากความยากบ้าคลั่งจะไม่ได้รับผลกระทบจาก「เพิ่มพูนความคิด」\n\n<Title:เหวแห่งทะเลแห่งการรับรู้>\n1「เหวแห่งทะเลแห่งการรับรู้」จะเปิดเฉพาะในช่วงวันที่ 6 เมษายน 9:00 - วันที่ 11 พฤษภาคม 9:00 (GMT+8).\n2 หลังจากวันที่ 11 พฤษภาคม 9:00 (GMT+8) สกุลเงิน「ความคิดเหนื่อยล้า」,「ความคิดเศร้าหมอง」,「ความคิดที่เต็มไปด้วยความสุข」ที่ยังไม่ได้แลกจะถูกนำไปรีไซเคิลตามอัตราแลกเปลี่ยน「คูปองกุหลาบทอง」× 40 โปรดผู้พิทักษ์ตรวจสอบอีเมล.\n\n<Title:การล่องเรือในจิตสำนึก>\n1 ในระยะเวลากิจกรรม「การล่องเรือในจิตสำนึก：วันราชาภิเษก」สามารถปลดล็อกได้ฟรี.\n2 หลังจากสิ้นสุดกิจกรรม ความก้าวหน้าของการสำรวจ「การล่องเรือในจิตสำนึก：วันราชาภิเษก」จะถูกเก็บรักษาไว้ โดยสามารถได้รับรางวัลการสำรวจที่ตรงกับระยะเวลากิจกรรมได้ หากในระยะเวลากิจกรรมไม่ได้ปลดล็อก「การล่องเรือในจิตสำนึก：วันราชาภิเษก」 หลังจากกิจกรรมสิ้นสุดสามารถใช้「จุดเริ่มต้นของความเป็นจริง」×3 เพื่อปลดล็อกได้.\n3 ไม่ว่าจะในระยะเวลากิจกรรมหรือไม่ หลังจากผ่าน「การล่องเรือในจิตสำนึก：วันราชาภิเษก」สามารถได้รับ「คำสั่งกุญแจ：พรจากดวงดาว」.\n\n<Title:การชดเชยการทำซ้ำ>\n1 ผู้พิทักษ์ที่เคยปลดล็อก「การล่องเรือในจิตสำนึก：วันราชาภิเษก」จะได้รับการชดเชย「ความคิดเหนื่อยล้า」×300 ในระยะเวลาการทำซ้ำครั้งนี้.\n2 ผู้พิทักษ์ที่เคยได้รับภาพโปรไฟล์ที่มีจำกัด「ชื่อของกุญแจเงิน：ธูลู」เมื่อได้รับซ้ำจะถูกแปลงอัตโนมัติเป็น「คำเชิญของวิญญาณไร้รูปร่าง」×1."
  },
