  Activity_133272_ActivityPlot = {
    Text = "ยุคที่ยิ่งใหญ่อาจสูญสิ้นในที่สุด แต่เจตจำนงของนักรบผู้ยิ่งใหญ่เหล่านั้นจะไม่มีวันสูญสิ้น.\nหลุมศพไม่สามารถกลบพวกเขาไว้ โซ่ไม่สามารถทำให้พวกเขาเชื่องได้.\nเมื่อมีเส้นทางใหม่เกิดขึ้น อาหารย่างอร่อยที่เรียกร้องอยู่ที่ปลายทางนั้น นักรบได้เริ่มการเปิดตัว เก็บเกี่ยวของที่มีเกียรติในกระเป๋าของพวกเขา.\nให้เราขับร้องเพื่อความกล้าหาญที่ไม่สิ้นสุดนี้ เพื่ออาณาจักรอันศักดิ์สิทธิ์นี้! \nโรม! โรม!"
  },
  Activity_133272_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลงแล้ว ขณะนี้สามารถเข้าร่วม「ถวายเครื่องบรรณาการ」ได้เพียงอย่างเดียว"
  },
  Activity_133272_ActivityTips = {
    Text = "<Title:รายละเอียดกิจกรรม>\n1. ในช่วงกิจกรรม ผู้พิทักษ์สามารถสะสมสกุลเงินกิจกรรม「เนื้อย่างเลโอแสนอร่อย」ผ่านโหมดจำกัดเวลา「การล่าอันศักดิ์สิทธิ์」 โดย「เนื้อย่างเลโอแสนอร่อย」สามารถนำไปซื้อสินค้าใน「ถวายเครื่องบรรณาการ」ได้ รวมถึงแก่นลูเมน, แก่นไร้มลทิน เป็นต้น\n2. ในช่วงกิจกรรม「มิติฝันประหลาด：บันทึกพิชิตครัว」จะปลดล็อกให้เล่นฟรีแบบจำกัดเวลา\n\n<Title:ระยะเวลากิจกรรม>\n1. 4 พ.ค. 9:00 – 18 พ.ค. 9:00 (GMT+8) สามารถเข้าร่วมโหมดกิจกรรมทั้งหมดได้\n2. 18 พ.ค. 9:00 – 25 พ.ค. 9:00 (GMT+8) สามารถเข้าร่วมได้เฉพาะ「ถวายเครื่องบรรณาการ」และรางวัลความสำเร็จเท่านั้น\n\n<Title:การล่าอันศักดิ์สิทธิ์>\n1.「การล่าอันศักดิ์สิทธิ์」ประกอบด้วย 5 ด่าน โดยจะเปิดอัตโนมัติ 1 ด่านทุก 2 วัน\n2. การท้าทายแต่ละครั้งจะใช้「สปิริตเปปไทด์」× 120 เมื่อท้าทายสำเร็จจะได้รับสกุลเงินกิจกรรม\n3. หลังผ่านด่านแล้ว จะปลดล็อกฟังก์ชัน「เล่นซ้ำ」ของด่านนั้น โปรดทราบ：เมื่อใช้ฟังก์ชัน「เล่นซ้ำ」จะไม่ได้รับอัตราการประสาน\n4. สามารถใช้ตัวช่วยจากสมาคมศิษย์เก่าเพื่อช่วยให้ผ่านด่านได้ง่ายขึ้น\n\n<Title: ถวายเครื่องบรรณาการ>\nในร้านค้า「ถวายเครื่องบรรณาการ」สามารถใช้สกุลเงินกิจกรรม「เนื้อย่างเลโอแสนอร่อย」เลือกซื้อสินค้าได้โดยตรง\n\n<Title:มิติฝันประหลาด>\n1. ในช่วงกิจกรรม「มิติฝันประหลาด：บันทึกพิชิตครัว」สามารถปลดล็อกได้ฟรี\n2. หลังกิจกรรมสิ้นสุด ความคืบหน้าการสำรวจของ「มิติฝันประหลาด：บันทึกพิชิตครัว」จะถูกเก็บรักษาไว้ เมื่อทำภารกิจสำรวจที่ยังไม่เสร็จในช่วงกิจกรรมเสร็จสิ้นแล้ว ก็จะได้รับรางวัลสำรวจเหมือนกับในช่วงกิจกรรม หากไม่ได้ปลดล็อก「มิติฝันประหลาด：บันทึกพิชิตครัว」ในช่วงกิจกรรม หลังกิจกรรมสิ้นสุดยังคงสามารถใช้「จุดเริ่มต้นแห่งความจริง」×7 เพื่อปลดล็อกได้\n3. ไม่ว่าจะอยู่ในช่วงกิจกรรมหรือไม่ เมื่อผ่าน「มิติฝันประหลาด：บันทึกพิชิตครัว」แล้วจะได้รับ「คีย์ออร์เดอร์：ความมุ่งมั่นแห่งการล่า」"
  },
