  Activity_139117_ActivityTips = {
    Text = "<Title:แนะนำ>\n·ในช่วงกิจกรรม ผู้พิทักษ์สามารถรับรางวัลที่เกี่ยวข้องได้ใน「ของขวัญแห่งความฝันเสมือน」หลังจากทำภารกิจที่กำหนดสำเร็จ"
