  Activity_141308_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「ต้นกำเนิดแห่งเหวลึก」เปิดให้บริการ ผู้พิทักษ์สามารถใช้กองทัพที่ระบบกำหนดไว้ล่วงหน้าซึ่งมีพอนโทสอยู่ด้วย เพื่อสัมผัสประสบการณ์ด่านที่กำหนดได้ไม่จำกัดครั้ง\n·ขณะสัมผัสประสบการณ์ด่านกิจกรรม ไม่สามารถปรับเปลี่ยนร่างตื่นในกองทัพได้\n<Title:รางวัลกิจกรรม>\n·หลังจากทำการท้าทายด่านสำเร็จเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ในหน้าจอกิจกรรม"
  },
  Activity_141460_ActivityName = {
    Text = "บุตรศักดิ์สิทธิ์·ขนดำ"
  },
  Activity_141460_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「บุตรศักดิ์สิทธิ์·ขนดำ」เปิดให้เล่น ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งมีคาสเตอร์ เพื่อเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะเล่นด่านกิจกรรม จะไม่สามารถปรับเปลี่ยนร่างตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·เมื่อผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
