  Activity_141464_ActivityName = {
    Text = "เทพธิดาพันพัด"
  },
  Activity_141464_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「เทพธิดาพันพัด」เปิดให้เล่น ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งมีซวี่ เพื่อเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะเล่นด่านกิจกรรม จะไม่สามารถปรับเปลี่ยนร่างตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·เมื่อผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_141466_ActivityName = {
    Text = "ปลดล็อกด่านเนื้อเรื่องรองฟรี"
  },
  Activity_141467_ActivityName = {
    Text = "นักโทษกระจก·คลอน"
  },
  Activity_141467_ActivityPlot = {
    Text = "นกบินเอยนกบิน ทำไมถึงมีเครื่องจองจำที่ขาดบนเท้าของเธอ?\nนกบินเอยนกบิน ทำไมถึงส่งเสียงร้องอย่างโดดเดี่ยวอยู่บนฟ้าสูง?\nเมื่อรอดพ้นจากหนามหนา หลบพ้นจากหว่างขา เธอกางปีกบินผ่านทะเลทรายเหลืองยาวสุดลูกหูลูกตา แต่เสียงร้องเสียใจยังไม่เคยหยุด ใครกันแน่ จะเป็นคนที่เธอตามหาในการเดินทางอันซื่อสัตย์? ที่ไหนกัน ที่จะเป็นบ้านที่แท้จริงที่เธอตามหา?"
  },
  Activity_141467_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลง ขณะนี้สามารถเข้าร่วม「ความปรารถนาที่จะเรียนรู้」ได้เพียงอย่างเดียว"
  },
  Activity_141467_ActivityTips = {
    Text = "<Title:รายละเอียดกิจกรรม>\n1,     ในช่วงกิจกรรม ผู้พิทักษ์สามารถรวบรวมสกุลเงินกิจกรรม「หนังสือความรู้ทั่วไป」,     「หนังสือคณิตศาสตร์」,     「หนังสือวรรณกรรม」ผ่านกิจกรรมการเล่นเกมแบบจำกัดเวลา「飞跃青空」,     「การเดินทางในฝัน」และ「รางวัลความสำเร็จ」โดย「หนังสือความรู้ทั่วไป」,     「หนังสือคณิตศาสตร์」,     「หนังสือวรรณกรรม」สามารถนำไปซื้อสินค้าใน「ความปรารถนาในการแสวงหาความรู้」ได้ รวมถึงวงล้อมชีวิต SR จำกัดกิจกรรม「ขนนกที่โดดเดี่ยว」,      แกนกลางของลูเมน,      แกนบริสุทธิ์ และอื่น ๆ\n2,     ในช่วงกิจกรรม「โลกแห่งความฝันประหลาด：เหนือขอบฟ้า·บน」จะปลดล็อกฟรีแบบจำกัดเวลา และการทำความสำเร็จของกิจกรรมยังสามารถรับรูปโปรไฟล์จำกัดกิจกรรม「ชื่อของกุญแจเงิน：คาสเตอร์」ได้อีกด้วย!\n\n<Title:ช่วงเวลากิจกรรม>\n1,     5 ตุลาคม 9:00 - 2 พฤศจิกายน 9:00(GMT+8) สามารถเข้าร่วมกิจกรรมการเล่นเกมทั้งหมดได้\n2,     2 พฤศจิกายน 9:00 - 9 พฤศจิกายน 9:00(GMT+8) สามารถเข้าร่วมได้เฉพาะ「ความปรารถนาในการแสวงหาความรู้」และรางวัลความสำเร็จเท่านั้น\n\n<Title:飞跃青空>\n1,     「飞跃青空」มีทั้งหมด 7 ด่าน โดยจะเปิดให้เล่นอัตโนมัติวันละ 1 ด่าน\n2,     การท้าทายแต่ละครั้งจะใช้「เมโนฟิน」× 120 และเมื่อท้าทายสำเร็จจะได้รับสกุลเงินกิจกรรม\n3,     หลังจากผ่านด่านแล้ว จะปลดล็อกฟังก์ชัน「ลงด่วน」ของด่านนั้น โปรดทราบ: เมื่อใช้ฟังก์ชัน「ลงด่วน」จะไม่สามารถรับอัตราการประสานได้\n4,     สามารถใช้การสนับสนุนการต่อสู้จากสมาคมศิษย์เก่าเพื่อช่วยให้คุณผ่านด่านได้ง่ายขึ้น\n\n<Title: ความปรารถนาในการแสวงหาความรู้>\n「ความปรารถนาในการแสวงหาความรู้」มีร้านค้าทั้งหมดสามร้าน โดยมีเวลาเปิดดังนี้:\n·「วิชาเลือกทั่วไป」： เปิดเวลา 9 นาฬิกา วันที่ 5 ตุลาคม\n·「วิชาเลือกเรียนวิทยาศาสตร์」： เปิดเวลา 9 นาฬิกา วันที่ 6 ตุลาคม\n·「วิชาเลือกเรียนวรรณคดี」： เปิดเวลา 9 นาฬิกา วันที่ 7 ตุลาคม\nในร้านค้าสามารถเลือกสินค้าและซื้อได้โดยตรง\n\n<Title:โบนัสกิจกรรม>\n1,     หากผู้พิทักษ์มีร่างตื่นหรือวงล้อมชีวิตที่กำหนด(ไม่จำเป็นต้องนำออกสนาม) จะทำให้「หนังสือความรู้ทั่วไป」,     「หนังสือคณิตศาสตร์」,     「หนังสือวรรณกรรม」ในรางวัลภารกิจด่านของ「飞跃青空」ได้รับโบนัสการดรอปเพิ่มเติม โดยมีรายละเอียดโบนัสดังนี้:\n·ร่างตื่น「คาสเตอร์」：การตื่นพลัง 0/1/2/3 ขึ้นไป,      โบนัส 20%/30%/40%/50%\n·วงล้อมชีวิต SSR「อิสรภาพอันหนักอึ้ง」：ตำแหน่งซ้อน 0/1/2/3 ขึ้นไป,      โบนัส 20%/30%/40%/50%\n·วงล้อมชีวิต SR「ขนนกที่โดดเดี่ยว」：ตำแหน่งซ้อน 0/1/2/3 ขึ้นไป,      โบนัส 20%/30%/40%/50%\n2,     「โบนัสกิจกรรม」ของร่างตื่นหรือวงล้อมชีวิตที่แตกต่างกันจะคำนวณแบบสะสมรวมกัน\n3,     โดยเฉพาะอย่างยิ่ง รางวัลการท้าทายผ่านครั้งแรกในระดับความยากบ้าคลั่งจะไม่ได้รับผลจาก「โบนัสกิจกรรม」\n\n<Title: การเดินทางในฝัน>\n1,     รับ「หนังสือความรู้ทั่วไป」60 เล่มโดยอัตโนมัติทุกชั่วโมง สามารถสะสมได้สูงสุด 25 ชั่วโมง\n\n<Title:โลกแห่งความฝันประหลาด>\n1,     ในช่วงกิจกรรม「โลกแห่งความฝันประหลาด：เหนือขอบฟ้า·บน」สามารถปลดล็อกได้ฟรี\n2,     หลังจากกิจกรรมสิ้นสุด ความคืบหน้าการสืบสวนของ「โลกแห่งความฝันประหลาด：เหนือขอบฟ้า·บน」จะถูกเก็บรักษาไว้ และยังสามารถรับรางวัลการสืบสวนเช่นเดียวกับในช่วงกิจกรรมได้หลังจากทำการสืบสวนเหตุการณ์ที่ยังไม่เสร็จสิ้นในช่วงกิจกรรม หากไม่ได้ปลดล็อก「โลกแห่งความฝันประหลาด：เหนือขอบฟ้า·บน」ในช่วงกิจกรรม หลังจากกิจกรรมสิ้นสุดก็ยังสามารถใช้「จุดเริ่มต้นของความเป็นจริง」×7 เพื่อปลดล็อกได้\n3,     ไม่ว่าจะอยู่ในช่วงกิจกรรมหรือไม่ก็ตาม หลังจากผ่านด่าน「โลกแห่งความฝันประหลาด：เหนือขอบฟ้า·บน」จะสามารถรับ「คำสั่งกุญแจ：การเบี่ยงเบนของชะตากรรม」ได้"
  },
