  Activity_141535_ActivityTips = {
    Text = "<Title:บทนำกิจกรรม>\n1,     ในช่วงกิจกรรม「โลกแห่งความฝันประหลาด：ลาก่อน เนเวอร์แลนด์」ปลดล็อกฟรีชั่วคราว!\n2,     ในช่วงกิจกรรม เข้าสู่ระบบสะสม 7 วัน สามารถรับ「แกนกลางของลูเมน」×10 ใน「เทศกาลเชอเช่」และในวันที่ 7 สามารถรับอวตารต่อสู้จำกัด「วอลเลย์บอล『ไดโช』」เพิ่มเติม\n\n<Title:ช่วงเวลากิจกรรม>\n1,     6 ก.ค. 9:00 - 20 ก.ค. 9:00(GMT+8)สามารถเข้าร่วมกิจกรรมทั้งหมดได้\n\n<Title:โลกแห่งความฝันประหลาด>\n1,     ในช่วงกิจกรรม「โลกแห่งความฝันประหลาด：ลาก่อน เนเวอร์แลนด์」สามารถปลดล็อกได้ฟรี\n2,     หลังจากกิจกรรมสิ้นสุด ความคืบหน้าการสืบสวนของ「โลกแห่งความฝันประหลาด：ลาก่อน เนเวอร์แลนด์」จะถูกเก็บรักษาไว้ และสามารถรับรางวัลการสืบสวนเหมือนช่วงกิจกรรมได้หลังจากเสร็จสิ้นการสืบสวนเหตุการณ์ที่ยังไม่เสร็จในช่วงกิจกรรม หากยังไม่ได้ปลดล็อก「โลกแห่งความฝันประหลาด：ลาก่อน เนเวอร์แลนด์」ในช่วงกิจกรรม หลังจากกิจกรรมสิ้นสุดยังสามารถใช้「จุดเริ่มต้นของความเป็นจริง」×7 เพื่อปลดล็อกได้\n3,     ไม่ว่าจะอยู่ในช่วงกิจกรรมหรือไม่ก็ตาม หลังจากผ่านด่าน「โลกแห่งความฝันประหลาด：ลาก่อน เนเวอร์แลนด์」จะได้รับ「คำสั่งกุญแจ：ความทรงจำกลางฤดูร้อนที่ถ่ายทอดไว้」"
  },
  Activity_141535_BannerText = {
    Text = "กิจกรรมการเล่นเปิดให้เข้าร่วมแบบจำกัดเวลา!"
