  Activity_148889_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในระหว่างที่กิจกรรม「ต้นกำเนิดโอกิล」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งมีต้นกำเนิดโอกิลรวมอยู่ เพื่อทดลองเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะทดลองเล่นด่านกิจกรรม จะไม่สามารถปรับเปลี่ยนผู้ตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·เมื่อผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_15788_ActivityName = {
    Text = "สุนทรียะแห่งการเล่นแร่แปรธาตุ"
  },
  Activity_15788_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     ระหว่างกิจกรรม「สุนทรียะแห่งการเล่นแร่แปรธาตุ」เมื่อผู้พิทักษ์ผ่าน「ค้นหาคูปองทอง」รางวัลวัสดุบางส่วนจะได้รับเป็นสองเท่า สามารถใช้ได้ 3 ครั้งต่อวัน\n2,     จำนวนครั้งรางวัลสองเท่าที่ไม่ได้ใช้ในวันนั้นจะถูกรีเซ็ตในเวลา 9 โมงเช้าของวันถัดไป(GMT+8) อย่าลืมใช้ให้ทันนะ～"
  },
  Activity_15791_ActivityName = {
    Text = "ปัญญาระเบิด"
  },
  Activity_15791_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     ระหว่างกิจกรรม「ปัญญาระเบิด」เมื่อผู้พิทักษ์ผ่าน「การหลอมเวชภัณฑ์」รางวัลวัสดุบางส่วนจะได้รับเป็นสองเท่า สามารถใช้ได้ 3 ครั้งต่อวัน\n2,     จำนวนครั้งรางวัลสองเท่าที่ไม่ได้ใช้ในวันนั้นจะถูกรีเซ็ตในเวลา 9 โมงเช้าของวันถัดไป(GMT+8) อย่าลืมใช้ให้ทันนะ～"
  },
  Activity_15793_ActivityName = {
    Text = "เงาของเมืองฝน"
  },
  Activity_15793_ActivityPlot = {
    Text = "ทุกค่ำคืนที่ฝนตก ล้วนมาพร้อมกับความผิดหวังและเดียวดาย\nบางคนสูญเสียความรัก บางคนสูญเสียศักดิ์ศรี\nและบางคนสูญเสียศีรษะของตนเอง"
  },
  Activity_15793_ActivityTips = {
    Text = "<Title:เงื่อนไขการเข้าร่วม>\n·เข้าร่วมได้หลังจากผ่าน「ปฏิบัติการสืบสวน」2–9·โหมดปกติ\n<Title:เหตุการณ์สืบสวน>\n·ในช่วงกิจกรรม ทุกวันจะเปิดเหตุการณ์สืบสวนใหม่ 1 รายการใน「เงาลึกลับแห่งเมืองฝน」ผู้พิทักษ์ไม่ต้องใช้ทรัพยากรในการปลดล็อกเพื่อทำการสืบสวน หลังจากเสร็จสิ้นเหตุการณ์สืบสวนจะได้รับรางวัลสืบสวน เช่น แกนบริสุทธิ์ ตราสืบสวน และค่าประสบการณ์ผู้พิทักษ์\n·หลังจากกิจกรรมสิ้นสุด ความคืบหน้าการสืบสวนของ「เงาลึกลับแห่งเมืองฝน」จะถูกเก็บรักษาไว้ ผู้พิทักษ์สามารถใช้ลูกแก้วกัดกร่อนในบันทึกภารกิจพิเศษเพื่อปลดล็อกการสืบสวนที่ยังไม่ได้ปลดล็อก หลังจากเสร็จสิ้นเหตุการณ์สืบสวนที่ยังไม่เสร็จในช่วงกิจกรรมก็จะได้รับรางวัลสืบสวนเหมือนกับช่วงกิจกรรม<Title:รางวัลจำกัดเวลา>\n·ในช่วงกิจกรรมจะมีรางวัลจำกัดเวลา หลังจากผู้พิทักษ์ผ่าน「เงาลึกลับแห่งเมืองฝน」โหมดปกติและเสร็จสิ้นเหตุการณ์สืบสวนของ「เงาลึกลับแห่งเมืองฝน」จะได้รับรางวัลแกนบริสุทธิ์ ศิลาปราชญ์ และแกนเงิน! รางวัลจำกัดเวลาเปิดให้เฉพาะในช่วงกิจกรรมเท่านั้น หลังจากกิจกรรมสิ้นสุดจะไม่สามารถทำและรับรางวัลได้"
  },
  Activity_15793_UnlockConditionExplanation = {
    Text = "ปลดล็อคหลังเสร็จสิ้น 「การสอบสวน」2-9·ธรรมดา"
