  Activity_15797_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「จ้าวแห่งนิทรา」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งรวมทูรู เพื่อทดลองเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะทดลองเล่นด่านกิจกรรม ไม่สามารถปรับเปลี่ยนผู้ตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·หลังจากผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_15805_ActivityName = {
    Text = "การเดินทางในเมืองหมอก"
  },
  Activity_15805_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     หลังจากผู้พิทักษ์ความลับทำภารกิจบันทึกการเดินทางที่กำหนดสำเร็จ สามารถรับรางวัลได้ที่「บันทึกเมืองหมอก」\n2,     「บันทึกเมืองหมอก」เปิดถาวร\n3,     หลังปลดล็อก「บันทึกขั้นสูง」 จะสามารถรับรางวัลเพิ่มเติมหลังทำภารกิจสำเร็จ\n4,     โปรดทราบ：「บันทึกขั้นสูง」ที่ปลดล็อกในกิจกรรมนี้มีผลเฉพาะในกิจกรรมนี้เท่านั้น กรุณาใช้จ่ายอย่างมีสติ"
  },
