  Activity_21502_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「อัครทูตแห่งทะเล」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ล่วงหน้าซึ่งมีมิเรียมเพื่อสัมผัสด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะสัมผัสด่านกิจกรรม ไม่สามารถปรับเปลี่ยนร่างตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·เมื่อผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_21781_ActivityName = {
    Text = "เลือกศึกษาด้วยตนเอง"
  },
  Activity_21781_ActivityPlot = {
    Text = "ทำภารกิจให้สำเร็จ เพื่อเลือกร่างปลุกเฉพาะจาก「การศึกษาอาณาจักร」หรือวงล้อชะตาเฉพาะจาก「รูปลักษณ์แห่งวงล้อ」ได้ตามต้องการ!"
  },
  Activity_21781_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     ปลุกสะสม 50 ครั้ง,     เข้าสู่ระบบสะสม 3 วัน,     เข้าสู่ระบบสะสม 7 วัน จะได้รับรางวัล「สวนสนุกปฐมธาตุ」 「สวนสนุกปฐมธาตุ」สามารถใช้ได้ที่「ทรัพยากร：วัสดุสิ้นเปลือง」 หลังใช้แล้วสามารถเลือกร่างปลุกเฉพาะ 1 ตัวจาก「การศึกษาอาณาจักร」เพื่อปลุก\n2,     ปลุกสะสม 300 ครั้ง,     ปลุกสะสม 1000 ครั้ง,     เข้าสู่ระบบสะสม 30 วัน จะได้รับรางวัล「คัมภีร์หมุนเวียน」 「คัมภีร์หมุนเวียน」สามารถใช้ได้ที่「ทรัพยากร：วัสดุสิ้นเปลือง」 หลังใช้แล้วสามารถเลือกวงล้อชะตาเฉพาะ 1 ชิ้นจาก「รูปลักษณ์แห่งวงล้อ」เพื่อรับ"
  },
  Activity_22367_ActivityName = {
    Text = "ปัญญาระเบิด"
  },
  Activity_22367_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     ในช่วงกิจกรรม「ญาณปัญญาระเบิด」 เมื่อผู้พิทักษ์สำรวจหรือจำลองซ้ำใน「หลอมสกัดเภสัช」 จะได้รับรางวัลเพิ่มอีก 50％(ยกเว้นค่าประสบการณ์ผู้พิทักษ์) ไม่จำกัดจำนวนครั้งต่อวัน"
  },
  Activity_23671_ActivityName = {
    Text = "ดำดิ่งประลองปัญญา"
  },
  Activity_23671_ActivityPlot = {
    Text = "ในช่วงกิจกรรม ค่าประสบการณ์ผู้พิทักษ์ที่ได้รับจาก「ดำดิ่งห้วงฝัน」และ「ประลองเฟส」จะเพิ่มเป็นสองเท่า โดยมีขีดจำกัดรายวันเพิ่มเป็น 480 แต้ม"
  },
  Activity_23671_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     ในช่วงกิจกรรม「ดำดิ่งประลองปัญญา」 ค่าประสบการณ์ผู้พิทักษ์ที่ได้รับจาก「ดำดิ่งห้วงฝัน」และ「ประลองเฟส」จะเพิ่มเป็นสองเท่า โดยมีขีดจำกัดรายวันเพิ่มเป็น 480 แต้ม หากปลดล็อกหัวข้อหลักพร้อมกัน ค่าประสบการณ์ผู้พิทักษ์ที่ได้จากช่องทางนี้จะเพิ่มเป็นสองเท่าซ้อนสองเท่า โดยขีดจำกัดรายวันคงที่ที่ 480 แต้ม\n2,     ค่าประสบการณ์สองเท่าที่ยังไม่ได้ใช้ในวันนั้นจะถูกล้างในเวลา 9:00 ของวันถัดไป(GMT+8) ผู้พิทักษ์อย่าลืมใช้ให้หมดนะ～"
  },
  Activity_23693_ActivityName = {
    Text = "ทายาทขาวซีด"
  },
  Activity_23693_ActivityPlot = {
    Text = "เล่ากันว่าใต้ดินของลอนดิเนียม มีประตูเพียงบานเดียว\nมันนำไปสู่ที่ประทับของจ้าวแห่งความซีดเซียว..."
  },
  Activity_23693_ActivityTips = {
    Text = "<Title:เงื่อนไขการเข้าร่วม>\n·เข้าร่วมได้หลังจากผ่านการดำดิ่งจิตสำนึก「ความปรารถนาของอัศวิน」โหมดปกติ \n<Title:เหตุการณ์สืบสวน>\n·ในช่วงกิจกรรม ทุกวันจะเปิดเหตุการณ์สืบสวนใหม่ 1 รายการใน「ทายาทสีซีด」ผู้พิทักษ์ไม่ต้องใช้ทรัพยากรในการปลดล็อกเพื่อทำการสืบสวน หลังจากเสร็จสิ้นเหตุการณ์สืบสวนจะได้รับรางวัลสืบสวน เช่น แกนบริสุทธิ์ ตราสืบสวน และค่าประสบการณ์ผู้พิทักษ์\n·หลังจากกิจกรรมสิ้นสุด ความคืบหน้าการสืบสวนของ「ทายาทสีซีด」จะถูกเก็บรักษาไว้ ผู้พิทักษ์สามารถใช้ลูกแก้วกัดกร่อนในการดำดิ่งจิตสำนึกเพื่อปลดล็อกการสืบสวนที่ยังไม่ได้ปลดล็อก หลังจากเสร็จสิ้นเหตุการณ์สืบสวนที่ยังไม่เสร็จในช่วงกิจกรรมก็จะได้รับรางวัลสืบสวนเหมือนกับช่วงกิจกรรม<Title:รางวัลจำกัดเวลา>\n·ในช่วงกิจกรรมจะมีรางวัลจำกัดเวลา หลังจากผู้พิทักษ์ผ่าน「ทายาทสีซีด」โหมดปกติและเสร็จสิ้นเหตุการณ์สืบสวนของ「ทายาทสีซีด」จะได้รับรางวัลกุญแจดำและแกนเงิน! รางวัลจำกัดเวลาเปิดให้เฉพาะในช่วงกิจกรรมเท่านั้น หลังจากกิจกรรมสิ้นสุดจะไม่สามารถทำและรับรางวัลได้"
  },
  Activity_23693_UnlockConditionExplanation = {
    Text = "ปลดล็อกหลังจากผ่านการดำดิ่งจิตสำนึก「ความปรารถนาของอัศวิน」"
  },
  Activity_23723_ActivityName = {
    Text = "พายุกำลังจะมา"
  },
  Activity_23723_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     ระหว่างกิจกรรม ปฏิบัติการสืบสวนบทที่ 5 จะปิดชั่วคราว กุญแจคำสั่ง「สัจจะนิรันดร์」จะได้รับจากการผ่านปฏิบัติการสืบสวนบทที่ 4 แทน\n2,     หลังกิจกรรมสิ้นสุด ปฏิบัติการสืบสวนบทที่ 5 จะเปิดให้เล่นอีกครั้ง กุญแจคำสั่ง「สัจจะนิรันดร์」จะต้องผ่านปฏิบัติการสืบสวนบทที่ 5 ตามเดิม\n3,     นอกจากนี้ รางวัลความสำเร็จบทที่ 5 รางวัลความสำเร็จด่าน รางวัลสำรวจ และรางวัลผ่านด่านที่ได้รับไปแล้วก่อนหน้านี้จะยังคงอยู่ เมื่อเปิดให้เล่นอีกครั้ง(แผนปัจจุบันคือวันที่ 27 ธันวาคม) ความคืบหน้าที่ทำเสร็จแล้วจะถูกโอนย้ายและเก็บรักษาไว้ให้มากที่สุด ไม่จำเป็นต้องทำซ้ำ"
  },
  Activity_23870_ActivityName = {
    Text = "การคำนวณเฟส"
  },
  Activity_23870_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     ในช่วงกิจกรรม ทำภารกิจกิจกรรมให้สำเร็จเพื่อรับรางวัล\n2,     หลังกิจกรรมสิ้นสุด รางวัลที่ยังไม่ได้รับจะไม่สามารถรับได้อีก โปรดอย่าลืมรับรางวัลให้ทันเวลานะ～"
