  Activity_25011_ActivityPlot = {
    Text = "เธอก้าวไปข้างหน้าหนึ่งก้าว ข้ามเข้าสู่กาลอวกาศอีกแห่งหนึ่ง"
  },
  Activity_25011_ActivityTips = {
    Text = "<Title:เงื่อนไขการเข้าร่วม>\n·เข้าร่วมได้หลังจากผ่านการดำดิ่งจิตสำนึก「ความปรารถนาของอัศวิน」โหมดปกติ \n<Title:เหตุการณ์สืบสวน>\n·ในช่วงกิจกรรม ทุกวันจะเปิดเหตุการณ์สืบสวนใหม่ 1 รายการใน「อีกก้าวเดียว」ผู้พิทักษ์ไม่ต้องใช้ทรัพยากรในการปลดล็อกเพื่อทำการสืบสวน หลังจากเสร็จสิ้นเหตุการณ์สืบสวนจะได้รับรางวัลสืบสวน เช่น แกนบริสุทธิ์ ตราสืบสวน และค่าประสบการณ์ผู้พิทักษ์\n·หลังจากกิจกรรมสิ้นสุด ความคืบหน้าการสืบสวนของ「อีกก้าวเดียว」จะถูกเก็บรักษาไว้ ผู้พิทักษ์สามารถใช้ลูกแก้วกัดกร่อนในการดำดิ่งจิตสำนึกเพื่อปลดล็อกการสืบสวนที่ยังไม่ได้ปลดล็อก หลังจากเสร็จสิ้นเหตุการณ์สืบสวนที่ยังไม่เสร็จในช่วงกิจกรรมก็จะได้รับรางวัลสืบสวนเหมือนกับช่วงกิจกรรม<Title:รางวัลจำกัดเวลา>\n·ในช่วงกิจกรรมจะมีรางวัลจำกัดเวลา หลังจากผู้พิทักษ์ผ่าน「อีกก้าวเดียว」โหมดปกติและเสร็จสิ้นเหตุการณ์สืบสวนของ「อีกก้าวเดียว」จะได้รับรางวัลลูกอมนำโชคและแกนเงิน! รางวัลจำกัดเวลาเปิดให้เฉพาะในช่วงกิจกรรมเท่านั้น หลังจากกิจกรรมสิ้นสุดจะไม่สามารถทำและรับรางวัลได้"
  },
  Activity_25011_UnlockConditionExplanation = {
    Text = "ปลดล็อกหลังจากผ่านการดำดิ่งจิตสำนึก「ความปรารถนาของอัศวิน」"
  },
  Activity_25012_ActivityName = {
    Text = "การสดุดีกุหลาบ"
  },
  Activity_25012_ActivityPlot = {
    Text = "สุภาพสตรีและสุภาพบุรุษทั้งหลาย \nราตรีอันเงียบสงบได้เริ่มต้นขึ้นแล้ว เตรียมเครื่องดื่มชั้นเลิศไว้ข้างกายเถอะ \nนี่คือเรื่องราวที่ยาวนาน โปรดฟังเราเล่าอย่างช้าๆ..."
  },
  Activity_25012_ActivityTips = {
    Text = "<Title:เงื่อนไขการเข้าร่วม>\n·หลังจากเสร็จสิ้น「การสอบสวนดำเนินการ」2-9 ระดับปกติแล้วสามารถเข้าร่วมได้.\n<Title:เหตุการณ์การสอบสวน>\n·ในช่วงกิจกรรมทุกวันจะมีเหตุการณ์ใหม่ใน「คำสรรเสริญกุหลาบ」ให้ผู้พิทักษ์สามารถปลดล็อกและทำการสอบสวนได้โดยไม่ต้องใช้สิ่งของ เมื่อเสร็จสิ้นเหตุการณ์การสอบสวนแล้วจะได้รับรางวัลเช่น แกนบริสุทธิ์ เข็มกลัดสอบสวน และประสบการณ์ของผู้พิทักษ์ความลับ เป็นต้น\n·หลังจากจบกิจกรรม ความคืบหน้าในการสอบสวนของ「คำสรรเสริญกุหลาบ」จะยังคงอยู่ ผู้พิทักษ์สามารถใช้ไข่มุกหลอมละลายในบันทึกภารกิจพิเศษเพื่อปลดล็อกการสอบสวนที่ยังไม่ได้ปลดล็อก และหลังจากเสร็จสิ้นเหตุการณ์การสอบสวนที่ยังไม่ได้ทำในช่วงกิจกรรม ก็ยังสามารถรับรางวัลการสอบสวนที่เหมือนกับช่วงกิจกรรมได้<Title:รางวัลจำกัดเวลา>\n·ในช่วงกิจกรรมจะมีรางวัลจำกัดเวลาเปิดให้ ผู้พิทักษ์ที่ผ่านด่าน「คำสรรเสริญกุหลาบ」ระดับปกติและเสร็จสิ้นเหตุการณ์การสอบสวนของ「คำสรรเสริญกุหลาบ」จะได้รับรางวัลเช่น แกนบริสุทธิ์ หินของนักปราชญ์ และเงินใจ! รางวัลจำกัดเวลานี้จะเปิดให้เฉพาะช่วงกิจกรรมเท่านั้น หลังจากจบกิจกรรมจะไม่สามารถทำหรือรับได้"
  },
  Activity_25012_UnlockConditionExplanation = {
    Text = "ปลดล็อคหลังเสร็จสิ้น 「การสอบสวน」2-9·ธรรมดา"
  },
  Activity_34754_ActivityName = {
    Text = "เวทมนตร์แห่งเรื่องราว"
  },
  Activity_34754_ActivityTips = {
    Text = "<Title:เงื่อนไขการเข้าร่วม>\n·สามารถเข้าร่วมได้หลังจากเสร็จสิ้น「การสอบสวนดำเนินการ」2-9 ระดับปกติแล้วเท่านั้น \n<Title:เหตุการณ์การสอบสวน>\n·ในช่วงเวลาของกิจกรรม จะมีการเปิดเผย「เรื่องราวแห่งเวทมนตร์」ใหม่ของการสอบสวนทุกวัน ผู้พิทักษ์ไม่จำเป็นต้องใช้สิ่งของในการปลดล็อกเพื่อทำการสอบสวน เมื่อเสร็จสิ้นเหตุการณ์การสอบสวนแล้วจะได้รับรางวัล เช่น แกนบริสุทธิ์ เข็มกลัดสอบสวน และประสบการณ์ของผู้พิทักษ์ความลับ เป็นต้น \n·เมื่อกิจกรรมสิ้นสุดลง ความคืบหน้าของการสอบสวนใน「เรื่องราวแห่งเวทมนตร์」จะยังคงอยู่ ผู้พิทักษ์สามารถใช้ไข่มุกหลอมละลายในบันทึกภารกิจพิเศษเพื่อปลดล็อกการสอบสวนที่ยังไม่ได้ปลดล็อก และหลังจากเสร็จสิ้นเหตุการณ์การสอบสวนที่ยังไม่เสร็จสิ้นในช่วงกิจกรรม ก็จะได้รับรางวัลการสอบสวนที่เหมือนกับในช่วงกิจกรรม <Title:รางวัลจำกัดเวลา>\n·ในช่วงเวลาของกิจกรรมจะมีการเปิดตัวรางวัลจำกัดเวลา ผู้พิทักษ์ที่ผ่านด่าน「เรื่องราวแห่งเวทมนตร์」โหมดปกติและเสร็จสิ้นเหตุการณ์การสอบสวนของ「เรื่องราวแห่งเวทมนตร์」จะได้รับรางวัล เช่น แกนบริสุทธิ์ หินของนักปราชญ์ และเงินใจ! รางวัลจำกัดเวลาจะเปิดให้เฉพาะช่วงเวลาของกิจกรรมเท่านั้น เมื่อกิจกรรมสิ้นสุดลงจะไม่สามารถทำหรือรับได้อีก"
  },
  Activity_34755_ActivityName = {
    Text = "เวทมนตร์แห่งเรื่องราว"
  },
  Activity_34755_ActivityTips = {
    Text = "<Title:บทนำกิจกรรม>\n·ในช่วงเวลากิจกรรม วิธีการเล่น「ความลับของบทละคร」จะเปิดให้เข้าร่วมแบบจำกัดเวลา และ「บันทึกพิเศษ：เวทมนตร์แห่งเรื่องราว」จะปลดล็อกฟรี!\n\n<Title:ความลับของบทละคร>\n·「ความลับของบทละคร」ประกอบด้วยด่านที่มีระดับความยาก 9 ด่าน แนะนำระดับความสามารถอยู่ในช่วง 30~70 หลังจากผ่านด่านที่มีระดับความยากต่ำกว่าจะปลดล็อกด่านที่มีระดับความยากสูงขึ้น.\n·ทุกครั้งที่ท้าทายจะต้องใช้เมโนฟิน×60 และหลังจากผ่านด่านทุกครั้งจะได้รับสกุลเงินกิจกรรม「แรงบันดาลใจที่เร่ร่อน」 ด่านที่มีระดับความยากสูงจะได้รับ「แรงบันดาลใจที่เร่ร่อน」มากขึ้น!\n·「แรงบันดาลใจที่เร่ร่อน」สามารถนำไปแลกเปลี่ยนเป็นวัสดุในการพัฒนาผู้ปลุกตื่นจำนวนมากใน「ร้านค้าสคริปต์เวทมนตร์」 และยังสามารถแลกเป็นวงล้อมชีวิต SR ที่จำกัดในกิจกรรม「มนต์ของม้วนฟิล์ม 35 มม.」 วงล้อมนี้อาจจะกลับมาอีกในอนาคตหรือเข้าร่วมในการปลุกตื่นถาวร.\n·ในแต่ละครั้งที่ท้าทาย นอกจากผู้นำแล้ว ศัตรู เหตุการณ์ และแผนที่จะมีการเปลี่ยนแปลงได้ และอาจมีสิ่งประดิษฐ์มากขึ้นในด่าน!\n·ใน「ความลับของบทละคร」สามารถใช้การสนับสนุนจากสมาคมศิษย์เก่าได้.\n\n<Title:การสะท้อนและความสำเร็จ>\n·การใช้「ใจของการแสดง」เพื่อเปิดใช้งาน「การสะท้อน：รหัสผู้กำกับ」 จะทำให้ผู้พิทักษ์ใน「ความลับของบทละคร」แข็งแกร่งขึ้น ทำให้การท้าทายง่ายขึ้น.\n·ผู้พิทักษ์สามารถได้รับ「ใจของการแสดง」จากการบรรลุความสำเร็จในกิจกรรม นอกจากนี้ยังสามารถได้รับอวาตาร์ที่จำกัดในกิจกรรม「ชื่อของกุญแจเงิน：ลิลลี่」!\n\n<Title:บันทึกพิเศษ>\n·ในช่วงเวลากิจกรรม จะมีการเปิดตัวเหตุการณ์การสอบสวนใหม่ใน「เวทมนตร์แห่งเรื่องราว」ทุกวัน ผู้พิทักษ์ไม่ต้องใช้ทรัพยากรในการปลดล็อกเพื่อทำการสอบสวน หลังจากเสร็จสิ้นเหตุการณ์การสอบสวนจะได้รับแกนบริสุทธิ์ เข็มกลัดสอบสวน และประสบการณ์ของผู้พิทักษ์เป็นรางวัลการสอบสวน.\n·หลังจากสิ้นสุดกิจกรรม ความก้าวหน้าของการสอบสวนใน「เวทมนตร์แห่งเรื่องราว」จะถูกเก็บรักษาไว้ ผู้พิทักษ์สามารถใช้ไข่มุกหลอมละลายเพื่อปลดล็อกการสอบสวนที่ยังไม่ได้ปลดล็อก และหลังจากเสร็จสิ้นเหตุการณ์การสอบสวนที่ยังไม่เสร็จในช่วงเวลากิจกรรมจะได้รับรางวัลการสอบสวนที่เหมือนกันกับช่วงเวลากิจกรรม.\n·ในช่วงเวลากิจกรรมจะมีการมอบรางวัลความสำเร็จแบบจำกัดเวลา ผู้พิทักษ์ที่ผ่าน「เวทมนตร์แห่งเรื่องราว」ในโหมดปกติและทำเหตุการณ์การสอบสวน「เวทมนตร์แห่งเรื่องราว」เสร็จแล้ว สามารถรับรางวัลเงินใจในความสำเร็จของกิจกรรมได้! รางวัลความสำเร็จจะเปิดให้ในช่วงเวลากิจกรรมเท่านั้น หลังจากสิ้นสุดกิจกรรมจะไม่สามารถทำและรับได้.\n"
  },
