  Activity_35844_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「สุภาพสตรีแห่งทะเลลึก」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งรวมเมอร์ฟี เพื่อทดลองเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะทดลองเล่นด่านกิจกรรม ไม่สามารถปรับเปลี่ยนผู้ตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·หลังจากผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_35983_ActivityName = {
    Text = "ของขวัญจากสถาบัน"
  },
  Activity_35983_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     ผู้พิทักษ์ความลับสามารถรับรางวัลเข้าสู่ระบบประจำวันได้ที่「ของขวัญจากสถาบัน」หลังเข้าสู่ระบบในแต่ละวัน\n2,     รางวัลจะปลดล็อกตามลำดับตามจำนวนวันเข้าสู่ระบบสะสมของผู้พิทักษ์ความลับ รางวัลเข้าสู่ระบบประจำวันจะรีเซ็ตเวลา 9:00 น.(GMT+8)"
  },
  Activity_36841_ActivityName = {
    Text = "ทุกอย่างเป็นปกติ"
  },
  Activity_36841_ActivityPlot = {
    Text = "นี่คือวันที่เรียบง่ายและมีความสุขของโอเรตตา นี่คือทุก ๆ วันของเธอ"
  },
  Activity_36841_ActivityTips = {
    Text = "<Title:เงื่อนไขการเข้าร่วม>\n·เข้าร่วมได้หลังจากผ่านการดำดิ่งจิตสำนึก「ความปรารถนาของอัศวิน」โหมดปกติ \n<Title:เหตุการณ์สืบสวน>\n·ในช่วงกิจกรรม ผู้พิทักษ์ไม่ต้องใช้ทรัพยากรในการปลดล็อกเพื่อทำการสืบสวน หลังจากเสร็จสิ้นเหตุการณ์สืบสวนจะได้รับรางวัลสืบสวน เช่น แกนบริสุทธิ์ ตราสืบสวน และค่าประสบการณ์ผู้พิทักษ์\n·หลังจากกิจกรรมสิ้นสุด ความคืบหน้าการสืบสวนของ「ทุกอย่างเป็นปกติ」จะถูกเก็บรักษาไว้ ผู้พิทักษ์สามารถใช้ลูกแก้วกัดกร่อนในการดำดิ่งจิตสำนึกเพื่อปลดล็อกการสืบสวนที่ยังไม่ได้ปลดล็อก หลังจากเสร็จสิ้นเหตุการณ์สืบสวนที่ยังไม่เสร็จในช่วงกิจกรรมก็จะได้รับรางวัลสืบสวนเหมือนกับช่วงกิจกรรม<Title:รางวัลจำกัดเวลา>\n·ในช่วงกิจกรรมจะมีรางวัลจำกัดเวลา หลังจากผู้พิทักษ์ผ่าน「ทุกอย่างเป็นปกติ」โหมดปกติและเสร็จสิ้นเหตุการณ์สืบสวนของ「ทุกอย่างเป็นปกติ」จะได้รับรางวัลกุญแจดำและแกนเงิน! รางวัลจำกัดเวลาเปิดให้เฉพาะในช่วงกิจกรรมเท่านั้น หลังจากกิจกรรมสิ้นสุดจะไม่สามารถทำและรับรางวัลได้"
  },
  Activity_36841_UnlockConditionExplanation = {
    Text = "ปลดล็อกหลังจากผ่านการดำดิ่งจิตสำนึก「ความปรารถนาของอัศวิน」"
  },
  Activity_36885_ActivityName = {
    Text = "งานฉลองไฟลุกไหม้"
  },
  Activity_36886_ActivityName = {
    Text = "ราชินีแห่งหนาม"
  },
  Activity_36886_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「ราชินีแห่งหนาม」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งรวมวันดา เพื่อทดลองเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะทดลองเล่นด่านกิจกรรม ไม่สามารถปรับเปลี่ยนผู้ตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·หลังจากผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_38716_ActivityName = {
    Text = "การสอบสวนเริ่มใหม่"
  },
  Activity_38716_ActivityTips = {
    Text = "<Title:รายละเอียดกิจกรรม>\n·ผู้พิทักษ์สามารถรับรางวัล「เสบียงเริ่มต้นใหม่」ได้ทันทีจาก「รางวัลคืนสู่โรงเรียน」.\n·เมื่อทำภารกิจฝึกฝนที่กำหนดเสร็จสิ้น รับรางวัลในกิจกรรม「การสอบสวนเริ่มต้นใหม่」.\n·เมื่อทำภารกิจฝึกฝนทั้งหมดเสร็จสิ้น จะยังได้รับรางวัลเพิ่มเติม."
  },
  Activity_38717_ActivityName = {
    Text = "กลับไปรายงานตัวที่โรงเรียน"
  },
  Activity_38717_ActivityTips = {
    Text = "<Title:รายละเอียดกิจกรรม>\n·ผู้พิทักษ์สามารถรับรางวัลเช็คอินประจำวันได้ที่「รายงานตัวประจำวัน」หลังจากเข้าสู่ระบบทุกวัน\n·รางวัลจะปลดล็อกตามจำนวนวันที่ผู้พิทักษ์เข้าสู่ระบบสะสม รางวัลเช็คอินประจำวันจะรีเฟรชเวลา 9 โมงเช้า (GMT+8)"
  },
  Activity_38805_ActivityName = {
    Text = "งานฉลองไฟลุกไหม้"
  },
  Activity_38805_ActivityPlot = {
    Text = "อิซาราว์ เมืองในทะเลสาบ ซึ่งกล่าวกันว่าเป็นบ้านเกิดของวานด้า。\nครั้งนี้คุณจะเดินผ่านประตูแห่งความฝันไปยังกลุ่มหอคอยโบราณที่เต็มไปด้วยเสียงระฆัง..."
  },
  Activity_38805_ActivityTips = {
    Text = "<Title:บทนำกิจกรรม>\n·ในช่วงกิจกรรม「งานฉลองไฟลุกไหม้」จะเปิดให้เล่นแบบจำกัดเวลา และสามารถปลดล็อก「การล่องเรือในจิตสำนึก：งานฉลองไฟลุกไหม้」ได้ฟรีเป็นเวลาจำกัด！\n\n<Title:เมืองในทะเลสาบ>\n·「เมืองในทะเลสาบ」มี 7 ด่าน เปิดให้เล่นทุก 2 วัน 1 ด่าน！ศัตรูและเหตุการณ์ในแต่ละด่านอาจเกิดการเปลี่ยนแปลงแบบสุ่ม\n·โปรดทราบว่า ประเภทของวัสดุ รางวัล และอัตราส่วนการผสมที่ได้รับจากแต่ละด่านอาจมีการเปลี่ยนแปลง ด่านที่เปิดเร็วจะมีประเภทวัสดุที่เรียบง่ายกว่า ขณะที่ด่านที่เปิดช้าจะมีประเภทวัสดุที่หลากหลายมากขึ้นแต่มีจำนวนมากกว่า กรุณาเลือกวิธีการคู่มือการเล่นตามความต้องการของคุณ！\n·แต่ละด่านประกอบด้วย 7 ระดับความยาก โดยมีระดับที่แนะนำอยู่ระหว่าง 15~65 และระดับความยากทั้งหมดจะถูกปลดล็อกโดยอัตโนมัติ\n·การท้าทายแต่ละครั้งจะต้องใช้เมโนฟิน×120 ยิ่งระดับความยากสูง รางวัลที่ได้รับก็จะยิ่งมากขึ้น กรุณาเลือกระดับความยากที่เหมาะสมกับตนเองในการท้าทาย\n·วัสดุรางวัลจากด่านสามารถแลกเป็นวัสดุการฝึก「ผู้ปลุกตื่น」ในร้าน「กล่องสมบัติล้ำค่าของวันดา」ได้มากมาย รวมถึงอวาตาร์เฉพาะกิจกรรม「ชื่อของกุญแจเงิน：วันดา」\n·สามารถใช้การช่วยเหลือจากสมาคมศิษย์เก่าและ「การสะท้อน：คำสั่งลับแทนหน้าที่」เพื่อช่วยให้คุณผ่านด่านได้ง่ายขึ้น\n\n<Title:การสะท้อนและความสำเร็จ>\n·ใช้「ใจที่ชอบความสุข」เพื่อเปิดใช้งาน「การสะท้อน：คำสั่งลับแทนหน้าที่」จะทำให้ผู้พิทักษ์ใน「เมืองในทะเลสาบ」แข็งแกร่งขึ้น ทำให้การท้าทายง่ายขึ้น；ยังสามารถทำให้ผู้พิทักษ์ได้รับสกุลเงินกิจกรรมเพิ่มเติมเมื่อผ่านด่าน\n·ผู้พิทักษ์สามารถรับ「ใจที่ชอบความสุข」จากการทำความสำเร็จในกิจกรรม หรือแลกในร้าน「กล่องสมบัติล้ำค่าของวันดา」\n\n<Title:การล่องเรือในจิตสำนึก>\n·ในช่วงกิจกรรม「งานฉลองไฟลุกไหม้」สามารถปลดล็อกได้ฟรี ทุกวันจะมีเหตุการณ์การสอบสวนใหม่ใน「งานฉลองไฟลุกไหม้」 เมื่อสำเร็จเหตุการณ์การสอบสวนจะได้รับรางวัลการสอบสวน เช่นแกนบริสุทธิ์,เข็มกลัดสอบสวน และประสบการณ์ของผู้พิทักษ์ความลับ\n·หลังจากกิจกรรมสิ้นสุดลง ความก้าวหน้าในการสอบสวนของ「งานฉลองไฟลุกไหม้」จะถูกเก็บรักษาไว้ หากทำเหตุการณ์การสอบสวนที่ยังไม่เสร็จในช่วงกิจกรรมจะได้รับรางวัลการสอบสวนที่เหมือนกันกับช่วงกิจกรรม หากในช่วงกิจกรรมยังไม่ได้ปลดล็อก「งานฉลองไฟลุกไหม้」 หลังจากกิจกรรมสิ้นสุดลงยังสามารถใช้「จุดเริ่มต้นของความเป็นจริง」×3 เพื่อปลดล็อกได้\n·ในช่วงกิจกรรมจะมีรางวัลความสำเร็จที่จำกัดเวลา ผู้พิทักษ์สามารถรับรางวัลเงินใจเมื่อทำเหตุการณ์การสอบสวน「งานฉลองไฟลุกไหม้」ในกิจกรรม！รางวัลความสำเร็จจะเปิดให้ในช่วงกิจกรรมเท่านั้น หลังจากกิจกรรมสิ้นสุดจะไม่สามารถทำและรับรางวัลได้\n"
  },
