  },
  Activity_43570_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     หลังจากผู้พิทักษ์ความลับทำภารกิจบันทึกการเดินทางที่กำหนดสำเร็จ สามารถรับรางวัลได้ที่「บันทึกเมืองหิมะ」\n2,     「บันทึกเมืองหิมะ」เปิดถาวร\n3,     หลังปลดล็อก「บันทึกขั้นสูง」 จะสามารถรับรางวัลเพิ่มเติมหลังทำภารกิจสำเร็จ\n4,     โปรดทราบ：「บันทึกขั้นสูง」ที่ปลดล็อกในกิจกรรมนี้มีผลเฉพาะในกิจกรรมนี้เท่านั้น กรุณาใช้จ่ายอย่างมีสติ"
  },
  Activity_43572_ActivityName = {
    Text = "สุนทรียะแห่งการเล่นแร่แปรธาตุ"
