  Activity_43572_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     ในช่วงกิจกรรม「ศิลปะแห่งการเล่นแร่แปรธาตุ」 ผู้พิทักษ์ความลับที่สืบสวนหรือรีเพลย์ใน「ค้นหาบัตรทอง」จะได้รับรางวัลเพิ่มเติม 100％(ยกเว้น EXP ผู้พิทักษ์ความลับ) จำกัด 6 ครั้งต่อวัน"
