  Activity_48825_ActivityPlot = {
    Text = "ผู้พิทักษ์ความลับสามารถเลือกปลุกร่างตื่นรู้จำกัดได้ 1 ตัวจากรายการด้านล่าง!"
  },
  Activity_48825_ActivityTips = {
    Text = "<Title:บทนำ>\nหากไม่มีการเฝ้ารอด้วยความกระตือรือร้นของทุกท่าน, มิซากะอาจจะจมหายไปในคืนอันยาวนานตลอดกาล. บัดนี้, เราได้ปฏิบัติตามสัญญา, ฝ่าฟันอุปสรรคมาตลอดทาง, และมาถึงช่วงเวลาครบรอบครึ่งปี. ด้วยเหตุนี้, แมวโรงเรียนจะมอบของขวัญพิเศษให้แก่คุณ, เพื่อขอบคุณทุกท่านที่ร่วมเดินทางมาตลอด.\n\n<Title:กฎกิจกรรม>\n·ในช่วงกิจกรรม, ผู้พิทักษ์แต่ละท่านสามารถเลือกปลุกตื่นร่างตื่น SSR จำกัด 1 ใน 8 ตัว ได้แก่ ธูลู, ดาฟโฟดิล, โซเรล, ลิลลี่, เมอร์ฟี่, วานด้า, ซัลวาดอร์, 「24」.\n·เมื่อผู้พิทักษ์เลือกร่างตื่นที่ปลุกตื่นไปแล้ว, จะแปลงเป็นเศษเสี้ยวของร่างตื่นนั้น×1 และรากเหง้าที่ตกตะกอน×50; หากระดับปลดระดับวิญญาณของร่างตื่นนั้นเต็มแล้ว, จะแปลงเป็น「ชิ้นส่วนแกนวิญญาณ」× 1 และ「รากเหง้าที่ตกตะกอน」× 150."
  },
  Activity_48825_BannerText = {
    Text = "รับร่างตื่นรู้จำกัดฟรี"
  },
  Activity_48826_ActivityName = {
    Text = "รัตติกาลและอรุณรุ่ง"
  },
  Activity_48826_ActivityPlot = {
    Text = "เข้าสู่ระบบทุกวันเพื่อรับวงล้อโชคชะตา SSR จำกัดที่ระลึก「ราตรีนิรันดร์และรุ่งอรุณ」รับได้ทั้งหมด 16 ชิ้น!"
  },
  Activity_48826_ActivityTips = {
    Text = "<Title:แนะนำ>\nนี่คือบทกวีที่มอบให้แก่ผู้เล่น เกี่ยวกับอุดมคติ เกี่ยวกับศรัทธา เกี่ยวกับช่วงเวลาที่ก้าวเดินไปด้วยกัน ขอให้หัวใจที่จริงใจไม่มีวันหยุดเต้น ขอให้กุญแจเงินนำทางไปข้างหน้า\n\n<Title:กฎกิจกรรม>\n·ในช่วงกิจกรรม หลังจากผู้พิทักษ์ความลับเข้าสู่ระบบในแต่ละวัน สามารถรับวงล้อโชคชะตา SSR จำกัดที่ระลึก「ราตรีนิรันดร์และรุ่งอรุณ」ใน「ราตรีนิรันดร์และรุ่งอรุณ」ได้ รับได้ทั้งหมด 16 ครั้ง\n·รางวัลจะถูกปลดล็อกตามลำดับจากจำนวนวันเข้าสู่ระบบสะสมของผู้พิทักษ์ความลับ รางวัลเข้าสู่ระบบประจำวันจะรีเซ็ตเวลา 9 โมง (GMT+8)"
  },
  Activity_48826_BannerText = {
    Text = "รับวงล้อชะตา SSR จำกัดฟรี"
  },
  Activity_48827_ActivityName = {
    Text = "ซิลเวอร์คอร์ในหมวก"
  },
  Activity_48827_ActivityPlot = {
    Text = "จากสถิติที่ไม่สมบูรณ์ ในช่วงครึ่งปีที่ผ่านมา หมวกของแมวประจำโรงเรียนถูกนักเรียนตบไปหลายพันครั้ง ซิลเวอร์คอร์เล็กๆ น้อยๆ จำนวนมากร่วงหล่นลงพื้นแต่ไม่มีใครสนใจ ภารโรงที่รับผิดชอบทำความสะอาดรู้สึกลำบากใจมาก ขณะนี้โรงเรียนได้รวบรวมซิลเวอร์คอร์เหล่านี้และล้างทำความสะอาดเรียบร้อยแล้ว เก็บไว้ที่จุดรับของหาย กรุณามารับคืนด้วยตนเองโดยเร็ว"
  },
  Activity_48827_ActivityTips = {
    Text = "<Title:แนะนำ>\nจากสถิติที่ไม่สมบูรณ์ ในช่วงครึ่งปีที่ผ่านมา หมวกของแมวประจำโรงเรียนถูกนักเรียนตบไปหลายพันครั้ง ซิลเวอร์คอร์เล็กๆ น้อยๆ จำนวนมากร่วงหล่นลงพื้นแต่ไม่มีใครสนใจ ภารโรงที่รับผิดชอบทำความสะอาดรู้สึกลำบากใจมาก ขณะนี้โรงเรียนได้รวบรวมซิลเวอร์คอร์เหล่านี้และล้างทำความสะอาดเรียบร้อยแล้ว เก็บไว้ที่จุดรับของหาย กรุณามารับคืนด้วยตนเอง\n\n<Title:กฎกิจกรรม>\n·ในช่วงกิจกรรม หลังจากผู้พิทักษ์ความลับเข้าสู่ระบบในแต่ละวัน สามารถรับ「ซิลเวอร์คอร์」×1000 ใน「ซิลเวอร์คอร์ในหมวก」ได้ รับได้สูงสุด 5 ครั้ง\n·รางวัลจะถูกปลดล็อกตามลำดับจากจำนวนวันเข้าสู่ระบบสะสมของผู้พิทักษ์ความลับ รางวัลเข้าสู่ระบบประจำวันจะรีเซ็ตเวลา 9 โมง (GMT+8)"
