  },
  Activity_51611_ActivityTips = {
    Text = "<Title:เงื่อนไขการเข้าร่วม>\n·สามารถเข้าร่วมได้หลังจากเสร็จสิ้น「การสอบสวนดำเนินการ」2-9 ระดับปกติแล้วเท่านั้น \n<Title:เหตุการณ์การสอบสวน>\n·ในช่วงเวลาของกิจกรรม จะมีการเปิดเผย「เรื่องราวแห่งเวทมนตร์」ใหม่ของการสอบสวนทุกวัน ผู้พิทักษ์ไม่จำเป็นต้องใช้สิ่งของในการปลดล็อกเพื่อทำการสอบสวน เมื่อเสร็จสิ้นเหตุการณ์การสอบสวนแล้วจะได้รับรางวัล เช่น แกนบริสุทธิ์ เข็มกลัดสอบสวน และประสบการณ์ของผู้พิทักษ์ความลับ เป็นต้น \n·เมื่อกิจกรรมสิ้นสุดลง ความคืบหน้าของการสอบสวนใน「เรื่องราวแห่งเวทมนตร์」จะยังคงอยู่ ผู้พิทักษ์สามารถใช้ไข่มุกหลอมละลายในบันทึกภารกิจพิเศษเพื่อปลดล็อกการสอบสวนที่ยังไม่ได้ปลดล็อก และหลังจากเสร็จสิ้นเหตุการณ์การสอบสวนที่ยังไม่เสร็จสิ้นในช่วงกิจกรรม ก็จะได้รับรางวัลการสอบสวนที่เหมือนกับในช่วงกิจกรรม <Title:รางวัลจำกัดเวลา>\n·ในช่วงเวลาของกิจกรรมจะมีการเปิดตัวรางวัลจำกัดเวลา ผู้พิทักษ์ที่ผ่านด่าน「เรื่องราวแห่งเวทมนตร์」โหมดปกติและเสร็จสิ้นเหตุการณ์การสอบสวนของ「เรื่องราวแห่งเวทมนตร์」จะได้รับรางวัล เช่น แกนบริสุทธิ์ หินของนักปราชญ์ และเงินใจ! รางวัลจำกัดเวลาจะเปิดให้เฉพาะช่วงเวลาของกิจกรรมเท่านั้น เมื่อกิจกรรมสิ้นสุดลงจะไม่สามารถทำหรือรับได้อีก"
  },
  Activity_51888_ActivityName = {
    Text = "การดูหมิ่น"
  },
  Activity_51905_ActivityName = {
    Text = "ของขวัญจากสถาบัน"
  },
  Activity_51905_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     ผู้พิทักษ์ความลับสามารถรับรางวัลเข้าสู่ระบบประจำวันได้ที่「ของขวัญจากสถาบัน」หลังเข้าสู่ระบบในแต่ละวัน\n2,     รางวัลจะปลดล็อกตามลำดับตามจำนวนวันเข้าสู่ระบบสะสมของผู้พิทักษ์ความลับ รางวัลเข้าสู่ระบบประจำวันจะรีเซ็ตเวลา 9:00 น.(GMT+8)"
  },
  Activity_52040_ActivityName = {
    Text = "พิธีบูชายัญแห่งห้วงลึก"
  },
  Activity_52040_ActivityPlot = {
    Text = "บนเงาสะท้อนของทะเลลึก ความฝันของกษัตริย์ได้จางหายไป อาณาจักรของเทพก็ได้เน่าเปื่อยแล้ว \nเธอเดินออกมาจากภาพลวงในวันเก่า เข้าสู่ซากปรักหักพังของอนาคตที่พังทลาย \nเธอถามเหว เหวเงียบงัน \nเธอถวายสักการะให้เหว สิ่งที่ตอบกลับเธอมีเพียงตัวเธอเอง"
  },
  Activity_52040_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลงแล้ว，ขณะนี้สามารถเข้าร่วมได้เฉพาะ「การตอบสนองจากห้วงลึก」เท่านั้น"
  },
  Activity_52040_ActivityTips = {
    Text = "<Title:กิจกรรมแนะนำ>\n1,     ในช่วงเวลากิจกรรม ผู้พิทักษ์สามารถเก็บสะสมสกุลเงินกิจกรรมได้ผ่านการเล่นเกมแบบจำกัดเวลา 「สวรรค์ปรากฏ」,     「พระบัญชาของพระราชา」 และ 「รางวัลความสำเร็จ」 โดยสกุลเงินกิจกรรมสามารถนำไปใช้ใน 「การตอบกลับของความลึกซึ้ง」 เพื่อทำการบูชายัญและรับรางวัลไอเทม รวมถึงวงล้อมชีวิต SR ที่จำกัดกิจกรรม 「การเรียกของทะเลลึก」,     หินของนักปราชญ์,     แกนบริสุทธิ์,     แกนกลางของลูเมน เป็นต้น.\n2,     ในช่วงกิจกรรม 「โลกแห่งความฝันประหลาด：การดูหมิ่น」 จะเปิดฟรี.\n\n<Title:ระยะเวลากิจกรรม>\n1,     วันที่ 17 มิถุนายน เวลา 9:00 - วันที่ 1 กรกฎาคม เวลา 9:00(GMT+8),     สามารถเข้าร่วมกิจกรรมทั้งหมด.\n2,     วันที่ 1 กรกฎาคม เวลา 9:00 - วันที่ 8 กรกฎาคม เวลา 9:00(GMT+8),     จะเหลือเพียง 「การตอบกลับของความลึกซึ้ง」 และ 「รางวัลความสำเร็จ」 เท่านั้น ส่วนเนื้อหาอื่น ๆ ได้สิ้นสุดลงไม่นานแล้ว.\n\n<Title: สวรรค์ปรากฏ>\n1,     「สวรรค์ปรากฏ」ประกอบด้วยทั้งหมด 5 ด่าน ซึ่งจะเปิดโดยอัตโนมัติทุก ๆ 2 วัน.\n2,     แต่ละครั้งที่ท้าทายจะมีค่าใช้จ่าย 「เมโนฟิน」×120,     ถ้าท้าทายสำเร็จจะได้รับสกุลเงินกิจกรรม 「น้ำตาของผู้บูชา」,     「เลือดของผู้บูชา」 และ 「ไขกระดูกของผู้บูชา」.ถ้าท้าทายแบบสองเท่า จะต้องใช้เมโนฟินจำนวน 240 โดยจะได้รางวัลภารกิจด่านเป็นสองเท่า ส่วนรางวัลอัตราการประสานจะไม่มีการเปลี่ยนแปลง.\n3,     เมื่อความสมบูรณ์ของ 「รางวัลความสำเร็จ」 ถึง 100% จะปลดล็อกฟีเจอร์ 「ทำซ้ำ」 ของด่านที่ผ่านด่านไปแล้ว แต่ละครั้งที่ทำซ้ำจะมีค่าใช้จ่าย 「เมโนฟิน」×120.โปรดทราบว่า：เมื่อใช้งานฟีเจอร์ 「ทำซ้ำ」 จะไม่ได้รับอัตราการประสาน.\n4,     สามารถใช้ความช่วยเหลือจากเพื่อนในสโมสรและ 「การสะท้อน：พิธีกรรมทะเลลึก」 เพื่อช่วยให้ผ่านด่านได้ง่ายขึ้น.\n\n<Title: โบนัสเครื่องสังเวย>\n1,     ผู้พิทักษ์ที่มีผู้ปลุกตื่นหรือวงล้อมชีวิตที่ระบุ(ไม่จำเป็นต้องนำลงสนาม)สามารถทำให้รางวัลภารกิจด่านของ 「สวรรค์ปรากฏ」 คือ 「น้ำตาของผู้บูชา」,     「เลือดของผู้บูชา」 และ 「ไขกระดูกของผู้บูชา」 ได้รับการเพิ่มอัตราหล่นรางวัล รวมถึงทำซ้ำด้วย ต่อไปนี้：\n·ผู้ปลุกตื่น 「มิเรียม」：การตื่นพลังระดับ 0/1/2/3 ขึ้นไป เพิ่มอัตรา 20%/30%/40%/50%\n·วงล้อมชีวิต SSR 「พลังแห่งความศรัทธา」：ตำแหน่งซ้อนระดับ 0/1/2/3 ขึ้นไป เพิ่มอัตรา 20%/30%/40%/50%\n·วงล้อมชีวิต SR 「การเรียกของทะเลลึก」：ตำแหน่งซ้อนระดับ 0/1/2/3 ขึ้นไป เพิ่มอัตรา 20%/30%/40%/50%\n2,     โบนัสเครื่องสังเวยจากผู้ปลุกตื่นหรือวงล้อมชีวิตที่ต่างกันจะถูกคำนวณเป็นการเพิ่มอัตราแบบซ้อนกัน.\n\n<Title:การสะท้อน：พิธีกรรมทะเลลึก>\n1,     ผู้พิทักษ์สามารถรับ 「หัวใจแห่งความศรัทธา」 จากการทำสำเร็จในกิจกรรม.\n2,     ใช้ 「หัวใจแห่งความศรัทธา」 เพื่อเปิดใช้งาน 「การสะท้อน：พิธีกรรมทะเลลึก」 ซึ่งจะได้รับการเพิ่มดังนี้：\n(1)ทำให้ผู้พิทักษ์แข็งแกร่งขึ้นในกิจกรรมการเล่นเกม 「สวรรค์ปรากฏ」 และท้าทายได้ง่ายขึ้น.\n(2)เพิ่มสกุลเงินกิจกรรมที่ได้รับหลังสำเร็จจากการท้าทายใน 「สวรรค์ปรากฏ」.\n(3)เปิดใช้งานกิจกรรมการเล่นเกม 「พระบัญชาของพระราชา」.\n\n<Title:พระบัญชาของพระราชา>\n·เมื่อเปิดใช้งานการสะท้อน 「การทดลองการเสียสละ」 แล้ว สามารถได้รับ 60 「น้ำตาของผู้บูชา」 ต่อชั่วโมง โดยสามารถสะสมได้สูงสุด 25 ชั่วโมง.\n\n<Title:การตอบกลับของความลึกซึ้ง>\n1,     「การตอบกลับของความลึกซึ้ง」 มี 3 แท่นบูชา โดยเวลาเริ่มต้นเปิดดังนี้：\n·「อัลเทอร์แห่งน้ำตาที่ระยิบระยับ」：วันที่ 17 มิถุนายน เวลา 9:00.\n·「แท่นบูชาเลือดลิง」：วันที่ 19 มิถุนายน เวลา 9:00.\n·「บัลลังก์วิญญาณ」：วันที่ 21 มิถุนายน เวลา 9:00.\n2,     ทุกครั้งที่ทำการบูชายัญจะมีค่าใช้จ่าย 500「น้ำตาของผู้บูชา」/「เลือดของผู้บูชา」/「ไขกระดูกของผู้บูชา」 และจะได้รับรางวัลทั่วไปจากแท่นบูชาแบบสุ่ม 5 รายการ.\n3,     รางวัลทั่วไปจากแท่นบูชามีสองประเภท คือ 「ของขวัญจากประเทศเทพ」 และ 「รางวัลพื้นฐาน」 โดยสามารถรีเซ็ตเพื่อเพิ่มจำนวนสูงสุดของรางวัลทั่วไปที่เหลืออยู่ตามกฎดังนี้：\n(1)การรีเซ็ตสองครั้งแรก：เมื่อ 「ของขวัญจากประเทศเทพ」 ไม่มีเหลืออยู่ ผู้พิทักษ์สามารถเลือกรีเซ็ตได้ โดยหลังรีเซ็ต 「ของขวัญจากประเทศเทพ」 และ 「รางวัลพื้นฐาน」 จะถูกตั้งค่าจำนวนเหลือถึงขีดสุด หรือเลือกที่จะทำการบูชายัญต่อไป เมื่อ 「รางวัลพื้นฐาน」 ไม่มีเหลือจำนวนอยู่ ต้องทำการรีเซ็ตเพื่อดำเนินการต่อ.\n(2)การรีเซ็ตตั้งแต่ครั้งที่สาม：เมื่อ 「รางวัลพื้นฐาน」 ไม่มีเหลือจำนวนอยู่สามารถทำการรีเซ็ตได้ ในกรณีนี้ 「รางวัลพื้นฐาน」 จะถูกตั้งค่าจำนวนสูงสุดถึงขีดสุด แต่ 「ของขวัญจากประเทศเทพ」 จะไม่ถูกตั้งค่า.\n\n<Title:โลกแห่งความฝันประหลาด>\n1,     「โลกแห่งความฝันประหลาด」 เป็นรูปแบบใหม่ของการสืบสวน โดยเปรียบเทียบการแสดงเนื้อเรื่องแบบทั่วไป 「โลกแห่งความฝันประหลาด」 ต้องการการแสดงออกข้อความเพิ่มเติม.\n2,     ใน 「โลกแห่งความฝันประหลาด：การดูหมิ่น」 คุณจะสามารถเชื่อมโยงกับจิตใจของ มิเรียม เพื่ออ่านบันทึกความทรงจำของเธอโดยตรงและเป็นพยาน：การเผชิญความยากลำบากในลีมูเรียตั้งแต่ยังเป็นเด็ก ความหลงในศรัทธา และการต่อสู้ที่เต็มไปด้วยการเดินทางสู่เส้นทางแห่งความฝันที่นำไปสู่การเป็นผู้ช่วยเหลือและผู้ล่มสลาย...\n3,     ในช่วงกิจกรรม 「โลกแห่งความฝันประหลาด：การดูหมิ่น」 จะเปิดฟรี.ทุกสองวันจะมีการปล่อยเหตุการณ์ใหม่ หลังผ่านด่านใน「โลกแห่งความฝันประหลาด：การดูหมิ่น」สามารถรับรางวัล เช่น เงินใจ,     วงล้อมชีวิต SR ที่จำกัดกิจกรรม 「การเรียกของทะเลลึก」 ในรางวัลความสำเร็จ รางวัลความสำเร็จจะเปิดเฉพาะช่วงกิจกรรม เมื่อสิ้นสุดกิจกรรมจะไม่สามารถทำสำเร็จและรับรางวัลได้.\n4,     หลังสิ้นสุดกิจกรรม ความคืบหน้าในการสืบสวน「โลกแห่งความฝันประหลาด：การดูหมิ่น」จะถูกเก็บรักษาไว้ หากไม่มีการปลดล็อก「โลกแห่งความฝันประหลาด：การดูหมิ่น」ในช่วงกิจกรรม ยังคงสามารถใช้ 7 「จุดเริ่มต้นของความเป็นจริง」เพื่อปลดล็อกหลังสิ้นสุดกิจกรรม.\n5,     ไม่ว่าจะเป็นช่วงกิจกรรมหรือไม่ หากผ่านด่าน「โลกแห่งความฝันประหลาด：การดูหมิ่น」จะได้รับ 「คำสั่งกุญแจ：ระเริงกระแสคลื่น」.\n\n\n\n"
  },
  Activity_52040_BannerText = {
    Text = "กิจกรรมการเล่นเปิดให้เข้าร่วมแบบจำกัดเวลา!"
  },
  Activity_53727_ActivityName = {
    Text = "วันเปิดเทอม"
  },
  Activity_53727_ActivityTips = {
    Text = "<Title:รายละเอียดกิจกรรม>\n·「วันคืนสู่เหย้า」ภารกิจแบ่งเป็น 4 ชุด ปลดล็อกในวันที่ 1, 2, 3, 4 หลังจากกิจกรรมเริ่มต้น\n·ผู้พิทักษ์สามารถรับ「คำเชิญคืนสู่เหย้า」โดยการทำภารกิจ「วันคืนสู่เหย้า」ให้สำเร็จ\n·ใช้「คำเชิญคืนสู่เหย้า」เพื่อแลกรับรางวัลมากมายใน「ร้านค้าคืนสู่เหย้า」"
  },
  Activity_53728_ActivityName = {
    Text = "สนับสนุนการเริ่มต้นใหม่"
  },
  Activity_53728_ActivityTips = {
    Text = "<Title:รายละเอียดกิจกรรม>\n·ในช่วงกิจกรรม「สนับสนุนการเดินทางใหม่」ผู้พิทักษ์สามารถผ่านด่าน「การเตรียมและการขัดเกลือ」「ภาพหลงเหลือที่ขุ่น」「รูปภาพที่เหลือของทะเลลึก」「ภาพหลงเหลือของสารอินทรีย์」「ร่องรอยมิติ」「คลัสเตอร์ความวุ่นวาย」「ซากปรักหักพังของปอนาเป」「บ้านหนอน」「ลำคอชวาร์ซชิลด์」ได้แล้วจะได้รับ「คูปองกุหลาบทอง」และรางวัลวัสดุเป็นสองเท่า โดยสามารถใช้ได้ทั้งหมด 6 ครั้งต่อวัน.\n·จำนวนครั้งรางวัลสองเท่าที่ไม่ได้ใช้ในวันนั้นจะถูกรีเซ็ตในเวลา 9:00 น. (GMT+8) ของวันถัดไป กรุณาจำไว้ว่าให้ใช้ให้ทันเวลานะ~"
  },
  Activity_53729_ActivityName = {
    Text = "กลับไปรายงานตัวที่โรงเรียน"
  },
  Activity_53729_ActivityTips = {
    Text = "<Title:รายละเอียดกิจกรรม>\n·ผู้พิทักษ์สามารถรับรางวัลเช็คอินประจำวันได้ที่「รายงานตัวประจำวัน」หลังจากเข้าสู่ระบบทุกวัน\n·รางวัลจะปลดล็อกตามจำนวนวันที่ผู้พิทักษ์เข้าสู่ระบบสะสม รางวัลเช็คอินประจำวันจะรีเฟรชเวลา 9 โมงเช้า (GMT+8)"
  },
  Activity_53829_ActivityName = {
    Text = "กับหนังสือกุหลาบ"
  },
  Activity_53829_ActivityPlot = {
    Text = "เพชรพลอยสีทองที่หรูหรา ประกายมุกที่เจิดจรัส...\nการตกแต่งที่ฟุ่มเฟือยมากมายทำให้เธอหลงในภาพลวงของความเป็นราชินี\nบัดนี้ เธอตั้งใจจะรักษาภาพลวงนั้นไว้ตลอดกาล"
  },
  Activity_53829_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลงแล้ว ปัจจุบันสามารถเข้าร่วมได้เฉพาะ「งานเฉลิมฉลองสีทองและแดง」เท่านั้น"
  },
  Activity_53829_ActivityTips = {
    Text = "<Title:บทนำกิจกรรม>\n1,     ในช่วงเวลากิจกรรม ผู้พิทักษ์สามารถสะสมเงินตรากิจกรรม「พัดขนนกทรงจิต」ผ่านการเล่นแบบจำกัดเวลา 「ความทรงจำของกุหลาบ」 และ 「รางวัลความสำเร็จ」 โดยเงินตรากิจกรรม 「พัดขนนกทรงจิต」 สามารถนำไปแลกของรางวัลมากมายได้ใน 「การเฉลิมฉลองสีทองแดง」 รวมถึงวงล้อมชีวิต SR แบบจำกัด 「ล้านสายตาแห่งรัก」,      「แกนบริสุทธิ์」,      「แกนกลางของลูเมน」,      「เศษหินปัญญา」,      「คริสตัลเลียนแบบ」 ฯลฯ.\n2,     ในช่วงเวลากิจกรรม การทำภารกิจใน 「รางวัลความสำเร็จ」 สำเร็จสามารถรับภาพ Avatar แบบจำกัดกิจกรรม 「ชื่อของกุญแจเงิน：โซเรล」,      วงล้อมชีวิต SR แบบจำกัดกิจกรรม 「ล้านสายตาแห่งรัก」,      เงินใจ และเงินตรากิจกรรม 「พัดขนนกทรงจิต」 จำนวนมาก.\n3,     ในช่วงเวลากิจกรรม 「บันทึกพิเศษ：การสดุดีกุหลาบ」 จะเปิดให้ใช้งานฟรี.\n\n<Title:ช่วงเวลากิจกรรม>\n1,     วันที่ 1 กรกฎาคม เวลา 9:00 - วันที่ 15 กรกฎาคม เวลา 9:00(GMT+8),     เนื้อหาทั้งหมดของกิจกรรมสามารถเข้าร่วมได้.\n2,     วันที่ 15 กรกฎาคม เวลา 9:00 - วันที่ 22 กรกฎาคม เวลา 9:00(GMT+8),     จะเก็บรักษาเพียง 「การเฉลิมฉลองสีทองแดง」 และ 「รางวัลความสำเร็จ」,     ส่วนเนื้อหาอื่นๆ ที่เหลือจะสิ้นสุดแล้วไม่สามารถเข้าร่วมได้.\n\n<Title: ความทรงจำของกุหลาบ>\n1,     「ความทรงจำของกุหลาบ」ประกอบไปด้วย 9 ด่าน โดยจะปลดล็อกอัตโนมัติวันละ 1 ด่าน.\n2,     แต่ละความท้าทายจะใช้ 「เมโนฟิน」× 120,     การท้าทายด่านที่ต่างกันนอกจากจะได้รับวัสดุที่แตกต่างแล้ว ยังสามารถได้รับเงินตรากิจกรรม 「พัดขนนกทรงจิต」.\n3,     กิจกรรมในด่านนี้เป็นด่านวัสดุที่มีการต่อสู้โดยตรง หลังจากผ่านด่านแล้วสามารถทำซ้ำได้！การใช้ฟังก์ชัน「ทำซ้ำ」จะใช้ 「เมโนฟิน」× 120 ในแต่ละครั้ง.\n4,     โปรดทราบ：เมื่อใช้ฟังก์ชัน「ทำซ้ำ」,      จะไม่สามารถได้รับอัตราการประสาน.\n\n<Title:พัดขนนกทรงจิตเพิ่มเติม>\n1,     ผู้พิทักษ์ที่มีผู้ปลุกตื่นหรือวงล้อมชีวิตเฉพาะ(ไม่จำเป็นต้องนำไปต่อสู้) สามารถทำให้รางวัลในภารกิจด่าน「ความทรงจำของกุหลาบ」มีเงินตรากิจกรรมเพิ่มเติม(รวมถึงการทำซ้ำ) โดยสัดส่วนดังนี้：\n·ผู้ปลุกตื่น「โซเรล」：การตื่นพลัง 0/1/2/3 และสูงกว่า เพิ่ม 20%/30%/40%/50%\n·วงล้อมชีวิต SSR「ในนามของกุหลาบ」：ตำแหน่งซ้อน 0/1/2/3 และสูงกว่า เพิ่ม 20%/30%/40%/50%\n·วงล้อมชีวิต SR「ล้านสายตาแห่งรัก」：ตำแหน่งซ้อน 0/1/2/3 และสูงกว่า เพิ่ม 20%/30%/40%/50%\n2,     「พัดขนนกทรงจิตเพิ่มเติม」จากผู้ปลุกตื่นหรือวงล้อมชีวิตต่างๆ จะคำนวณโดยการซ้อนรวม.\n\n<Title:บันทึกพิเศษ>\n1,     ในช่วงเวลากิจกรรม สำหรับผู้พิทักษ์ที่ได้ปลดล็อก「บันทึกพิเศษ：การสดุดีกุหลาบ」ไปแล้วก่อนหน้า จะได้รับการชดเชย 「พัดขนนกทรงจิต」×600.\n2,     ใน「บันทึกพิเศษ：การสดุดีกุหลาบ」,      ผู้พิทักษ์จะต้องใช้กองทัพพิเศษที่มีการกำหนดเนื้อเรื่องล่วงหน้าของตัวละคร「โซเรล」เพื่อท้าทายภารกิจ."
  },
  Activity_53829_BannerText = {
    Text = "กิจกรรมการเล่นเปิดให้เข้าร่วมแบบจำกัดเวลา!"
  },
  Activity_54375_ActivityName = {
    Text = "การสดุดีกุหลาบ"
  },
  Activity_54375_ActivityPlot = {
    Text = "สุภาพสตรีและสุภาพบุรุษทั้งหลาย \nราตรีอันเงียบสงบได้เริ่มต้นขึ้นแล้ว เตรียมเครื่องดื่มชั้นเลิศไว้ข้างกายเถอะ \nนี่คือเรื่องราวที่ยาวนาน โปรดฟังเราเล่าอย่างช้าๆ..."
  },
  Activity_54375_ActivityTips = {
    Text = "<Title:เงื่อนไขการเข้าร่วม>\n·หลังจากเสร็จสิ้น「การสอบสวนดำเนินการ」2-9 ระดับปกติแล้วสามารถเข้าร่วมได้.\n<Title:เหตุการณ์การสอบสวน>\n·ในช่วงกิจกรรมทุกวันจะมีเหตุการณ์ใหม่ใน「คำสรรเสริญกุหลาบ」ให้ผู้พิทักษ์สามารถปลดล็อกและทำการสอบสวนได้โดยไม่ต้องใช้สิ่งของ เมื่อเสร็จสิ้นเหตุการณ์การสอบสวนแล้วจะได้รับรางวัลเช่น แกนบริสุทธิ์ เข็มกลัดสอบสวน และประสบการณ์ของผู้พิทักษ์ความลับ เป็นต้น\n·หลังจากจบกิจกรรม ความคืบหน้าในการสอบสวนของ「คำสรรเสริญกุหลาบ」จะยังคงอยู่ ผู้พิทักษ์สามารถใช้ไข่มุกหลอมละลายในบันทึกภารกิจพิเศษเพื่อปลดล็อกการสอบสวนที่ยังไม่ได้ปลดล็อก และหลังจากเสร็จสิ้นเหตุการณ์การสอบสวนที่ยังไม่ได้ทำในช่วงกิจกรรม ก็ยังสามารถรับรางวัลการสอบสวนที่เหมือนกับช่วงกิจกรรมได้<Title:รางวัลจำกัดเวลา>\n·ในช่วงกิจกรรมจะมีรางวัลจำกัดเวลาเปิดให้ ผู้พิทักษ์ที่ผ่านด่าน「คำสรรเสริญกุหลาบ」ระดับปกติและเสร็จสิ้นเหตุการณ์การสอบสวนของ「คำสรรเสริญกุหลาบ」จะได้รับรางวัลเช่น แกนบริสุทธิ์ หินของนักปราชญ์ และเงินใจ! รางวัลจำกัดเวลานี้จะเปิดให้เฉพาะช่วงกิจกรรมเท่านั้น หลังจากจบกิจกรรมจะไม่สามารถทำหรือรับได้"
  },
  Activity_54402_ActivityName = {
    Text = "ผู้ป่วยแตกแยก·โกลาหล"
  },
  Activity_54402_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「ผู้ป่วยโรคจิตเภท·ความวุ่นวาย」เปิดให้บริการ, ผู้พิทักษ์สามารถใช้ทีมที่ระบบกำหนดไว้ซึ่งมี「24」เพื่อสัมผัสประสบการณ์ด่านที่กำหนดได้ไม่จำกัดครั้ง.\n·ในระหว่างการสัมผัสประสบการณ์ด่านกิจกรรม, ไม่สามารถปรับเปลี่ยนร่างตื่นในกองทัพได้.\n<Title:รางวัลกิจกรรม>\n·หลังจากผ่านด่านเป็นครั้งแรก, สามารถรับรางวัลทดลองเล่นได้ที่หน้าจอกิจกรรม."
  },
  Activity_54403_ActivityName = {
    Text = "กุญแจแห่งประตู"
  },
  Activity_54403_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「กุญแจแห่งประตู」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ล่วงหน้าซึ่งมีทาวีเพื่อสัมผัสด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะสัมผัสด่านกิจกรรม ไม่สามารถปรับเปลี่ยนร่างตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·เมื่อผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_54404_ActivityName = {
    Text = "บิชอปแห่งเมตตา"
  },
  Activity_54404_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「บิชอปแห่งเมตตา」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ซึ่งรวมซัลวาดอร์ เพื่อทดลองเล่นด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะทดลองเล่นด่านกิจกรรม ไม่สามารถปรับเปลี่ยนผู้ตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·หลังจากผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_54405_ActivityName = {
    Text = "ผู้ป่วยแตกแยก·เหนือมิติ"
  },
  Activity_54405_ActivityTips = {
    Text = "<Title:กฎของกิจกรรม>\n·ในช่วงที่กิจกรรม「ผู้ป่วยโรคจิตเภท·อัลตร้า」เปิดให้เล่น ผู้พิทักษ์สามารถใช้ทีมที่ระบบกำหนดไว้ซึ่งมี「24」เพื่อสัมผัสประสบการณ์ด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ในระหว่างการสัมผัสประสบการณ์ด่านกิจกรรม ไม่สามารถปรับเปลี่ยนผู้ปลุกตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·หลังจากผ่านด่านกิจกรรมเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้าจอกิจกรรม"
  },
  Activity_54406_ActivityName = {
    Text = "อัครทูตแห่งทะเล"
  },
  Activity_54406_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「อัครทูตแห่งทะเล」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ล่วงหน้าซึ่งมีมิเรียมเพื่อสัมผัสด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะสัมผัสด่านกิจกรรม ไม่สามารถปรับเปลี่ยนร่างตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·เมื่อผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
