  Activity_54596_ActivityName = {
    Text = "ของขวัญแห่งปัญญา"
  },
  Activity_54596_ActivityTips = {
    Text = "<Title:รายละเอียดกิจกรรม>\n1,     เมื่อผู้พิทักษ์ความลับทำภารกิจที่กำหนดในกิจกรรมสำเร็จ จะสามารถรับรางวัลมากมาย ได้แก่「สวนสนุกต้นกำเนิด」「หนังสือแห่งวัฏจักร」「ต้นแบบทัศนียภาพ」「แม่แบบวงจร」「แกนย้อนรอยวิญญาณ」「แกนย้อนรอยโชคชะตา」 รวมถึงร่างตื่นและวงล้อชะตาจำกัดจาก「บทแห่งการลืมเลือน」 ร่างตื่นและวงล้อชะตาจำกัดจาก「บทแห่งดวงดาว」 และยังมีกรอบรูปโปรไฟล์จำกัดจากกิจกรรม「เกณฑ์เงินขาว」 รวมถึงการเร่งค่าประสบการณ์ผู้พิทักษ์ความลับ และรางวัลพิเศษอื่นๆ อีกด้วย！\n2,     กิจกรรมนี้เปิดถาวร เมื่อทำภารกิจทั้งหมดในกิจกรรมสำเร็จและรับรางวัลครบแล้ว กิจกรรมจะสิ้นสุดและไม่แสดงอีกต่อไปหลังเวลา 9:00(GMT+8)ของวันถัดไป\n\n<Title:คำสรรเสริญสูงสุด>\n1,     การทำภารกิจที่กำหนดในกิจกรรมสำเร็จจะได้รับเอฟเฟกต์「คำสรรเสริญสูงสุด」 ซึ่งจะเร่งการได้รับค่าประสบการณ์ผู้พิทักษ์ความลับ สูงสุดถึง 100% เมื่อมีเอฟเฟกต์「คำสรรเสริญสูงสุด」หลายรายการพร้อมกัน จะใช้อัตราเร่งที่สูงที่สุด\n2,     เมื่อปลดล็อกหรือได้รับเอฟเฟกต์「คำสรรเสริญสูงสุด」ระดับสูงขึ้น จะได้รับค่าประสบการณ์ผู้พิทักษ์ความลับเพิ่มเติมทันทีตามอัตราเร่งและจำนวนค่าประสบการณ์ผู้พิทักษ์ความลับที่สามารถเร่งได้ในปัจจุบัน\n3,     หลังปลดล็อก「คำสรรเสริญสูงสุด」 ทุกครั้งที่ผู้พิทักษ์ความลับได้รับค่าประสบการณ์ จะได้รับค่าประสบการณ์เพิ่มเติมตามอัตราเร่งที่สอดคล้องกัน\n4,     โปรดทราบว่า ค่าประสบการณ์ผู้พิทักษ์ความลับเพิ่มเติมจาก「คำสรรเสริญสูงสุด」จะไม่ถูกนับรวมในจำนวนค่าประสบการณ์ผู้พิทักษ์ความลับที่สามารถเร่งได้\n5,     จำนวนค่าประสบการณ์ผู้พิทักษ์ความลับที่สามารถเร่งได้ในปัจจุบัน：{s1}\n6,     การเร่งได้สะสมค่าประสบการณ์ผู้พิทักษ์ความลับเพิ่มเติมแล้ว：{s2}({s3}%)"
  },
  Activity_55110_ActivityName = {
    Text = "ก่อนที่ฤดูใบไม้ผลิจะเหี่ยวเฉา"
  },
  Activity_55110_ActivityPlot = {
    Text = "เสียงหัวเราะของสาวๆ ดังขึ้น สะท้อนไปทั่วสวนที่เพลิงยังไม่ได้ลุกโชน \nจงหยุดพักเพื่อชื่นชมความงดงามของอดีตอันแสนหวานนี้เถิด เพื่อนของฉัน \nฟังเสียงของฤดูใบไม้ผลิที่ยังไม่จางหาย เล่าเรื่องราวในอดีตอย่างแผ่วเบาและไพเราะ"
  },
  Activity_55110_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลงแล้ว ปัจจุบันสามารถเข้าร่วมได้เฉพาะ「เรือนกระจกดอกไม้ของโคเล็ต」เท่านั้น"
  },
  Activity_55110_ActivityTips = {
    Text = "<Title:กิจกรรมแนะนำ>\n1,     ในช่วงระยะเวลากิจกรรม ผู้พิทักษ์สามารถรวบรวม「บทกวี」ทั้งสามประเภทได้ผ่านกิจกรรมที่มีจำกัดเวลาอย่าง「สวนความทรงจำ」,     「จูบของมิวส์」 และ 「รางวัลความสำเร็จ」 โดยสามารถนำ「บทกวี」เหล่านี้ไปแลกเปลี่ยนใน 「ห้องดอกไม้ของโคเล็ต」 เพื่อรับรางวัลของ เช่น วงล้อมชีวิต SR ที่จำกัดเฉพาะในกิจกรรม 「ดอกไม้และบทกวีของอดีต」,      「แกนบริสุทธิ์」,      「แกนกลางของลูเมน」,      「เศษหินปัญญา」,      「คริสตัลเลียนแบบ」 เป็นต้น.\n2,     ในช่วงเวลากิจกรรม,     「บันทึกพิเศษ：ที่อยู่อาศัยของกุหลาบ」 จะสามารถเข้าร่วมฟรี.\n\n<Title:ระยะเวลากิจกรรม>\n1,     15 กรกฎาคม 9:00 - 29 กรกฎาคม 9:00(GMT+8)สามารถเข้าร่วมเนื้อหากิจกรรมทั้งหมด.\n2,     29 กรกฎาคม 9:00 - 5 สิงหาคม 9:00(GMT+8)จะคงไว้เพียง 「ห้องดอกไม้ของโคเล็ต」 และ 「รางวัลความสำเร็จ」 เท่านั้น เนื้อหาอื่นๆ สุดสิ้นแล้วและไม่สามารถเข้าร่วมได้.\n\n<Title:สวนความทรงจำ>\n1,     「สวนความทรงจำ」 รวมทั้งหมด 5 ด่าน จะสามารถเปิดใช้ได้อัตโนมัติทุกๆ 2 วัน.\n2,     แต่ละครั้งที่ท้าทาย จะเสีย 「เมโนฟิน」×120 เมื่อท้าทายสำเร็จจะได้รับสกุลเงินกิจกรรม 「บทกวีที่เศร้าสร้อย」,     「บทกวีแห่งความเสียใจ」 และ 「บทกวีที่เต็มไปด้วยความสุข」.\n3,     เมื่อผ่านด่าน จะสามารถปลดล็อกฟังก์ชัน 「ทำซ้ำ」 ของด่านนั้นได้ โปรดทราบว่า: เมื่อใช้ฟังก์ชัน 「ทำซ้ำ」 จะไม่ได้รับอัตราการประสาน.\n4,     ผู้เล่นสามารถใช้ตัวช่วยของชมรมศิษย์เก่า และ 「การสะท้อน：บทเพลงรำลึกของสวน」 เพื่อช่วยให้ผ่านด่านได้ง่ายขึ้น.\n5,     หลังจากด่านปลดล็อกครบ 2 วัน จะสามารถปลดล็อก ระดับความยากบ้าคลั่ง ของด่านนั้นได้ การผ่านในครั้งแรกของระดับความยากบ้าคลั่ง จะได้รับรางวัลจากสกุลเงินกิจกรรมมากมาย.\n6,     โปรดทราบว่า: การท้าทายระดับความยากบ้าคลั่งในครั้งแรกไม่ต้องการเมโนฟินและไม่สามารถทำซ้ำได้ และการท้าทายซ้ำหลังผ่านในครั้งแรกจะไม่ได้รับรางวัลสกุลเงินกิจกรรมอีก.\n\n<Title:การเพิ่มบทกวี>\n1,     ผู้พิทักษ์ที่มีผู้ปลุกตื่นหรือวงล้อมชีวิตบางอย่าง(ไม่ต้องใช้ในสนาม)สามารถเพิ่มโอกาสการได้รับ「บทกวีที่เศร้าสร้อย」,     「บทกวีแห่งความเสียใจ」 และ 「บทกวีที่เต็มไปด้วยความสุข」จากรางวัลในด่านของ「สวนความทรงจำ」ได้(รวมถึงการทำซ้ำ) การเพิ่มมีดังนี้：\n·ผู้ปลุกตื่น 「ฮอร์ลา」： การตื่นพลัง 0 / 1 / 2 / 3 และสูงกว่า,      เพิ่ม 20%/30%/40%/50%\n·วงล้อมชีวิต SSR 「บทส่งท้าย」： ตำแหน่งซ้อน 0 / 1 / 2 / 3 และสูงกว่า,      เพิ่ม 20%/30%/40%/50%\n·วงล้อมชีวิต SR 「ดอกไม้และบทกวีของอดีต」： ตำแหน่งซ้อน 0 / 1 / 2 / 3 และสูงกว่า,      เพิ่ม 20%/30%/40%/50%\n2,     ผู้ปลุกตื่นหรือวงล้อมชีวิตที่แตกต่างกันจะมีการนับรวม 「การเพิ่มบทกวี」 ในรูปแบบการสะสม\n3,     ที่สำคัญ การให้รางวัลในการผ่านระดับความยากบ้าคลั่งในครั้งแรกจะไม่ได้รับการเพิ่มบทกวี.\n\n<Title:การสะท้อน：บทเพลงรำลึกของสวน>\n1,     ผู้พิทักษ์สามารถรับ 「หัวใจเถ้าถ่าน」 ผ่านการทำภารกิจความสำเร็จในกิจกรรม.\n2,     เมื่อใช้ 「หัวใจเถ้าถ่าน」 เพื่อเปิดใช้งาน 「การสะท้อน：บทเพลงรำลึกของสวน」 จะได้รับผลดังต่อไปนี้：\n(1)ทำให้ผู้พิทักษ์ในกิจกรรมการเล่นเกม「สวนความทรงจำ」แข็งแกร่งขึ้น และเผชิญความท้าทายได้อย่างง่ายดายขึ้น.\n(2)เพิ่มจำนวนสกุลเงินกิจกรรมที่ได้รับหลังสำเร็จการท้าทายใน 「สวนความทรงจำ」.\n(3)เปิดใช้งานกิจกรรมการเล่นเกม 「จูบของมิวส์」.\n\n<Title:จูบของมิวส์>\n·เมื่อเปิดใช้การสะท้อน 「ทุกสิ่งทุกอย่างเติบโต」 จะได้รับ 「บทกวีที่เศร้าสร้อย」 อัตโนมัติ 60ต่อชั่วโมง และสามารถเก็บสะสมได้สูงสุด 25 ชั่วโมง.\n·เมื่อเปิดใช้การสะท้อน 「แลกเปลี่ยนบทกวีด้วยดอกไม้」 จะสามารถเพิ่มการได้รับ 「บทกวีแห่งความเสียใจ」 อีก 60 หน่วยต่อชั่วโมง ใน「จูบของมิวส์」.\n\n<Title:ห้องดอกไม้ของโคเล็ต>\n1,     「ห้องดอกไม้ของโคเล็ต」 มีฟลอเรสชั้น 3 แห่ง เริ่มต้นเวลา：\n·「ฟลอเรสไอริส」： เปิดวันที่ 15 กรกฎาคม เวลา 9 โมงเช้า.\n·「ฟลอเรสระฆัง」： เปิดวันที่ 17 กรกฎาคม เวลา 9 โมงเช้า.\n·「ฟลอเรสดอกกุหลาบ」： เปิดวันที่ 19 กรกฎาคม เวลา 9 โมงเช้า.\n2,     การแลกเปลี่ยนในแต่ละครั้งจะใช้ทรัพยากร 1000 「บทกวีที่เศร้าสร้อย」/「บทกวีแห่งความเสียใจ」/「บทกวีที่เต็มไปด้วยความสุข」เพื่อสุ่มรับรางวัลจากฟลอเรส 5 รายการ.\n3,     รางวัลในแต่ละฟลอเรสจะถูกแบ่งออกเป็น 2 ประเภท: 「วัสดุพิเศษ」 และ 「ของธรรมดา」,     เมื่อทำการรีเซ็ตจะรีเซ็ตจำนวนวัสดุพิเศษที่เหลือให้เต็มอีกครั้ง,     รายละเอียดกติกาดังนี้：\n(1)การรีเซ็ต2ครั้งแรก: เมื่อ「วัสดุพิเศษ」ไม่มีจำนวนที่เหลืออยู่แล้ว ผู้พิทักษ์สามารถเลือกที่จะรีเซ็ต ซึ่งจะฟื้นจำนวน「วัสดุพิเศษ」หรือ「ของธรรมดา」ที่เหลือกลับมาเต็มอีกครั้ง； หรือเลือกที่จะแลกเปลี่ยนต่อ เมื่อ「ของธรรมดา」ก็ไม่มีจำนวนที่เหลือจะต้องทำรีเซ็ตเพื่อที่จะแลกเปลี่ยนต่อ.\n(2)การรีเซ็ตเริ่มจากครั้งที่ 3： จะสามารถรีเซ็ตได้เฉพาะเมื่อ 「ของธรรมดา」 ไม่มีจำนวนที่เหลืออยู่แล้ว การรีเซ็ตนี้จะฟื้นจำนวน「ของธรรมดา」ที่เหลือกลับมาเต็มอีกครั้ง ส่วน「วัสดุพิเศษ」จะไม่ถูกฟื้น.\n4,     วันที่ 5 สิงหาคม เวลา 9 โมงเช้า(GMT+8)「บทกวี」ที่เหลือไม่ได้นำไปแลกเปลี่ยนจะถูกเก็บคืนในอัตรา 200หน่วยแลกเปลี่ยนได้ 「คูปองกุหลาบทอง×5000」 ขอให้ผู้พิทักษ์ตรวจสอบในอีเมล.\n\n<Title:บันทึกพิเศษ>\n1,     ในระหว่างกิจกรรม 「บันทึกพิเศษ：ที่อยู่อาศัยของกุหลาบ」จะสามารถเข้าร่วมได้ฟรี มีการเปิดเหตุการณ์ใหม่ทุก 2 วัน เมื่อผ่าน 「บันทึกพิเศษ：ที่อยู่อาศัยของกุหลาบ」จะได้รับเงินใจและวงล้อมชีวิต SR 「ดอกไม้และบทกวีของอดีต」 ในรางวัลความสำเร็จ โดยรางวัลความสำเร็จสามารถรับได้เฉพาะในช่วงกิจกรรม หลังสิ้นสุดกิจกรรม จะไม่สามารถทำภารกิจและรับรางวัลได้.\n2,     หลังสิ้นสุดกิจกรรม ความคืบหน้าในการสำรวจใน 「บันทึกพิเศษ：ที่อยู่อาศัยของกุหลาบ」 จะถูกเก็บรักษา หากไม่ได้ปลดล็อก「บันทึกพิเศษ：ที่อยู่อาศัยของกุหลาบ」ในช่วงกิจกรรม หลังสิ้นสุดกิจกรรมยังสามารถใช้「จุดเริ่มต้นของความเป็นจริง」×7 ในการปลดล็อก.\n3,     ไม่ว่าจะในช่วงกิจกรรมหรือไม่ การผ่าน 「บันทึกพิเศษ：ที่อยู่อาศัยของกุหลาบ」 จะได้รับ 「คำสั่งกุญแจ：บทกวีในฤดูใบไม้ผลิ」."
  },
