  Activity_56429_ActivityTips = {
    Text = "<Title:บทนำกิจกรรม>\nในช่วงเวลากิจกรรม ผู้พิทักษ์สามารถเก็บรวบรวมสกุลเงินกิจกรรม \"ชิ้นส่วนตุ๊กตา\"ผ่านการเล่นที่จำกัดเวลาใน \"ประตูแห่งความว่างเปล่า\"และ \"รางวัลความสำเร็จ\"\"ชิ้นส่วนตุ๊กตา\"สามารถแลกของรางวัลใน \"คำสอนของครู\"ได้ รวมถึง SRวงล้อมชีวิตจำกัดกิจกรรม \"ไม้เท้าของคนเลี้ยงแกะ\"แกนกลางของลูเมน แกนบริสุทธิ์ เศษหินปัญญา คริสตัลเลียนแบบ ฯลฯ \n\n<Title:ประตูแห่งความว่างเปล่า>\n1. \"ประตูแห่งความว่างเปล่า\"รวมถึงด่านวัตถุดิบ 9 ด่านที่ไม่จำเป็นต้องสำรวจก่อนและเจอการต่อสู้ ซึ่งจะเปิดใหม่ 1 ด่านทุกวัน \n2. การท้าทายแต่ละครั้งจะใช้ \"เมโนฟิน\" × 120 และหากท้าทายสำเร็จ จะได้รับวัตถุดิบสำหรับการพัฒนาและสกุลเงินกิจกรรม \n3. หลังผ่านด่าน ระบบ \"ทำซ้ำ\"ของด่านนั้นๆ จะปลดล็อค โปรดทราบว่า: การใช้ฟังก์ชัน \"ทำซ้ำ\"ไม่สามารถได้รับอัตราการประสาน \n4. คุณสามารถใช้การสนับสนุนจากสมาคมศิษย์เพื่อช่วยให้ผ่านด่านได้ง่ายขึ้น \n\n<Title:ชิ้นส่วนตุ๊กตาเพิ่มค่าผลตอบแทน>\n1. ผู้พิทักษ์ที่มีผู้ปลุกตื่นหรือวงล้อมชีวิตที่กำหนด(ไม่จำเป็นต้องใช้งาน) สามารถเพิ่มค่าผลตอบแทนชิ้นส่วนตุ๊กตาในภารกิจด่าน \"ประตูแห่งความว่างเปล่า\"(รวมถึงการทำซ้ำ) รายละเอียดการเพิ่มมีดังต่อไปนี้: \n·ผู้ปลุกตื่น \"การหลอมละลาย · ดอร์\": การตื่นพลัง 0/1/2/3 ขึ้นไป เพิ่ม 20%/30%/40%/50% \n·SSRวงล้อมชีวิต \"หุ่นจำลองกลวงเปล่า\": ตำแหน่งซ้อน 0/1/2/3 ขึ้นไป เพิ่ม 20%/30%/40%/50% \n·SRวงล้อมชีวิต \"ไม้เท้าของคนเลี้ยงแกะ\": ตำแหน่งซ้อน 0/1/2/3 ขึ้นไป เพิ่ม 20%/30%/40%/50% \n2. ค่าผลตอบแทนชิ้นส่วนตุ๊กตาของผู้ปลุกตื่นหรือวงล้อมชีวิตแบบต่าง ๆ จะถูกคำนวณผ่านการซ้อน \n3.โดยพิเศษ รางวัลการท้าทายแบบผ่านครั้งแรกในระดับความยากบ้าคลั่งจะไม่ได้รับผลกระทบจากการเพิ่มค่าผลตอบแทนตามนี้ \n\n<Title:คำสอนของครู>\n1. การ \"แลกชิ้นส่วน\"แต่ละครั้งจะใช้ \"ชิ้นส่วนตุ๊กตา\" 750 ชิ้น และสุ่มได้รับของรางวัล 5 รายการใน \"คำสอนของครู\"\n2. รางวัลใน \"คำสอนของครู\"แบ่งเป็น \"วัสดุพิเศษ\"และ \"ของธรรมดา\"และเมื่อถึงเวลารีเซ็ต รางวัลของวัสดุพิเศษที่ยังเหลืออยู่จะรีเซ็ตไปยังขีดสูงสุด กฎเฉพาะคือ: \n(1)รีเซ็ต 5 ครั้งแรก: หาก \"วัสดุพิเศษ\"ไม่มีเหลือในสต็อก ผู้พิทักษ์สามารถเลือกรีเซ็ต และหลังการรีเซ็ต จะมีการปรับยอดวัสดุพิเศษและของธรรมดาไปจนถึงขีดสูงสุดได้ หรือสามารถเลือกแลกต่อไปได้ เมื่อ \"ของธรรมดา\"ไม่มีในสต็อก ผู้พิทักษ์จะต้องรีเซ็ตเพื่อสามารถไปแลกต่อได้\n(2)ตั้งแต่การรีเซ็ตครั้งที่ 6 เป็นต้นไป: คุณสามารถรีเซ็ตเฉพาะเมื่อไม่มี \"ของธรรมดา\"เหลืออยู่ และการรีเซ็ตจะปรับยอดคงเหลือของ \"ของธรรมดา\"ไปยังขีดสูงสุด แต่จะไม่มีการรีเซ็ตในส่วนของ \"วัสดุพิเศษ\"อีกต่อไป\n\n<Title:เวลาโอกาสกิจกรรม>\n1.วันที่ 17 ก.พ. เวลา 9:00 - วันที่ 3 มี.ค. เวลา 9:00(GMT+8) ทุกเนื้อหาในบทนำกิจกรรมสามารถเข้าร่วมได้ \n2.ในวันที่ 3 มี.ค. เวลา 9:00 - วันที่ 10 มี.ค. เวลา 9:00(GMT+8) จะคงเหลือไว้เฉพาะ \"คำสอนของครู\"และ \"รางวัลความสำเร็จ\"เนื้อหาอื่นใดจะสิ้นสุดและไม่สามารถเข้าร่วมได้\n3.หลังวันที่ 10 มี.ค. เวลา 9:00(GMT+8) \"ชิ้นส่วนตุ๊กตา\"ที่ยังเหลืออยู่และไม่ได้แลกของรางวัล จะถูกเก็บคืนในอัตราส่วน \"คูปองกุหลาบทอง\" × 40 ต่อชิ้น กรุณาตรวจสอบจดหมายของคุณให้ดี."
  },
  Activity_56429_BannerText = {
    Text = "กิจกรรมการเล่นเปิดให้เข้าร่วมแบบจำกัดเวลา!"
  },
  Activity_56430_ActivityName = {
    Text = "ซิมโฟนีที่มองไม่เห็น"
  },
  Activity_56430_ActivityPlot = {
    Text = "ซิมโฟนีคือศิลปะแห่งการประสานเสียง แนวเสียงของเครื่องดนตรีต่างๆ สานต่อกันเป็นแผนภาพที่งดงาม\nในโครงสร้างของเขา ทุกตัวโน้ตจะปฏิบัติหน้าที่ของตนเอง\nจงฟังเถิด ซิมโฟนีอันล้ำเลิศกำลังจะเริ่มขึ้น"
  },
  Activity_56430_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลงแล้ว ปัจจุบันสามารถเข้าร่วมได้เฉพาะ「วังอันเมี่ยน」เท่านั้น"
  },
  Activity_56430_ActivityTips = {
    Text = "<Title:บทนำกิจกรรม>\n1,     ในช่วงกิจกรรม ผู้พิทักษ์สามารถเก็บรวบรวมสกุลเงินกิจกรรม 「บทเพลงฮีโร่」 ผ่านการเล่นแบบจำกัดเวลา 「เสียงดังกึกก้อง」 และ 「รางวัลความสำเร็จ」 โดย 「บทเพลงฮีโร่」 สามารถนำไปแลกรับรางวัลมากมายใน 「วังแห่งการหลับใหล」 รวมถึงวงล้อ SR ที่จำกัดในกิจกรรม 「การเล่นที่ไม่เคยหยุดนิ่ง」,     「แกนบริสุทธิ์」,     「แกนกลางของลูเมน」,     「เศษหินปัญญา」,     「คริสตัลเลียนแบบ」 เป็นต้น.\n2,     ในช่วงกิจกรรม การทำภารกิจ 「รางวัลความสำเร็จ」 จะได้รับภาพโปรไฟล์จำกัดในกิจกรรม 「ชื่อของกุญแจเงิน：ฮาเมลน์」,     วงล้อ SR ที่จำกัดในกิจกรรม 「การเล่นที่ไม่เคยหยุดนิ่ง」,     เงินใจ และสกุลเงินกิจกรรมจำนวนมาก 「บทเพลงฮีโร่」.\n\n<Title:เวลาของกิจกรรม>\n1,     9 กันยายน 9:00 - 23 กันยายน 9:00(GMT+8) สามารถเข้าร่วมเนื้อหาทั้งหมดของกิจกรรม.\n2,     23 กันยายน 9:00 - 30 กันยายน 9:00(GMT+8) จะเหลือเพียง 「วังแห่งการหลับใหล」 และ 「รางวัลความสำเร็จ」 เท่านั้น เนื้อหาอื่นๆ จะสิ้นสุดและไม่สามารถเข้าร่วมได้.\n\n<Title:เสียงดังกึกก้อง>\n1,     「เสียงดังกึกก้อง」 ประกอบด้วย 9 ด่าน ซึ่งจะเปิดอัตโนมัติวันละ 1 ด่าน.\n2,     การท้าทายแต่ละครั้งจะใช้ 「เมโนฟิน」 × 120 สำหรับการท้าทายด่านต่างๆ นอกจากจะได้รับวัสดุที่แตกต่างกันแล้ว ยังจะได้รับสกุลเงินกิจกรรม 「บทเพลงฮีโร่」.\n3,     ด่านกิจกรรมครั้งนี้เป็นด่านวัสดุที่ต่อสู้โดยตรง เมื่อผ่านแล้วสามารถทำซ้ำได้! ทุกครั้งที่ 「ทำซ้ำ」 จะใช้ 「เมโนฟิน」 × 120.\n4,     โปรดทราบว่า：เมื่อใช้ฟังก์ชัน 「ทำซ้ำ」 จะไม่ได้รับอัตราการประสาน.\n\n<Title:การเพิ่มพูนบทเพลง>\n1,     ผู้พิทักษ์ที่มีร่างกายปลุกตื่นหรือวงล้อเฉพาะ(ไม่ต้องการให้ใช้งาน) จะทำให้รางวัลในภารกิจ 「เสียงดังกึกก้อง」 ที่มี 「บทเพลงฮีโร่」 ได้รับการเพิ่มพูนการตกของวัสดุ(รวมถึงการทำซ้ำ) โดยการเพิ่มพูนมีรายละเอียดดังนี้:\n·ร่างกายปลุกตื่น 「ฮาเมลน์」：การตื่นพลัง 0/1/2/3 ขึ้นไป เพิ่มพูน 20%/30%/40%/50%\n·วงล้อ SSR 「บทสวดส่งวิญญาณนิรันด์」：ตำแหน่งซ้อน 0/1/2/3 ขึ้นไป เพิ่มพูน 20%/30%/40%/50%\n·วงล้อ SR 「การเล่นที่ไม่เคยหยุดนิ่ง」：ตำแหน่งซ้อน 0/1/2/3 ขึ้นไป เพิ่มพูน 20%/30%/40%/50%\n2,     การ 「เพิ่มพูนบทเพลง」 ของร่างกายปลุกตื่นหรือวงล้อที่แตกต่างกันจะถูกคำนวณแบบสะสม.\n3,     พิเศษคือ รางวัลการท้าทายครั้งแรกในระดับความยากบ้าคลั่งจะไม่ได้รับผลกระทบจากการ 「เพิ่มพูนบทเพลง」.\n\n<Title:วังแห่งการหลับใหล>\n1,     「วังแห่งการหลับใหล」 จะเปิดให้บริการเฉพาะในช่วงเวลา 9 กันยายน 9:00 - 30 กันยายน 9:00(GMT+8).\n2,     หลังจาก 30 กันยายน 9:00(GMT+8) สกุลเงิน 「บทเพลงฮีโร่」 ที่ยังไม่ได้แลกจะถูกเก็บตามอัตราแลกเปลี่ยน 「คูปองกุหลาบทอง」 × 40 โปรดให้ผู้พิทักษ์ตรวจสอบอีเมล.."
  },
