  Activity_56432_ActivityName = {
    Text = "เมื่อภูเขาหิมะละลาย"
  },
  Activity_56432_ActivityPlot = {
    Text = "เอลวอสปกคลุมไปด้วยหิมะและน้ำแข็งตลอดทั้งปี ราวกับความแค้นในใจเธอ \n เมื่ออนาคตและอดีตมาบรรจบกัน นักรบจะชูดาบขึ้น และพุ่งเข้าหาโชคชะตาด้วยความอาฆาต \n เมื่อเธอเผชิญหน้ากับคลื่นสีดำ คุณคือสัญลักษณ์นำทางของเธอ"
