  Activity_61156_ActivityName = {
    Text = "การเดินทางสุดท้าย"
  },
  Activity_61156_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     หลังจากผู้พิทักษ์ความลับทำภารกิจบันทึกการเดินทางที่กำหนดสำเร็จ สามารถรับรางวัลได้ที่「บันทึกจุดจบ」\n2,     「บันทึกจุดจบ」เปิดถาวร\n3,     หลังปลดล็อก「บันทึกขั้นสูง」 จะสามารถรับรางวัลเพิ่มเติมหลังทำภารกิจสำเร็จ\n4,     โปรดทราบ：「บันทึกขั้นสูง」ที่ปลดล็อกในกิจกรรมนี้มีผลเฉพาะในกิจกรรมนี้เท่านั้น กรุณาใช้จ่ายอย่างมีสติ"
  },
  Activity_61369_ActivityName = {
    Text = "จังหวะแห่งท่วงทำนอง"
  },
  Activity_61369_ActivityPlot = {
    Text = "ผู้พิทักษ์ความลับสามารถเลือกปลุกวงล้อโชคชะตาจำกัดได้ 1 วงจากรายการด้านล่าง!"
  },
  Activity_61369_ActivityTips = {
    Text = "<Title:รายละเอียด>\nบ่อมืดเต็มไปด้วยคลื่นลมอันคาดเดาไม่ได้ วงล้อชะตาหมุนเวียนไม่สิ้นสุด ภายใต้การนำทางของเสียงเพลงแห่งฮาเมลิน ทำนองอันไร้ขอบเขตบรรเลงพร้อมกัน รวมเป็นวงล้อชะตาแห่งเส้นทางที่เธอได้เดินทางผ่านมา ขอให้พลังของพวกมันร่วมเคียงข้างเธอจนถึงตัวหยุดของบทเพลงสุดท้าย\n\n<Title:กฎกิจกรรม>\n·ในช่วงกิจกรรม เพียงเข้าสู่ระบบ 1 วัน ก็สามารถเลือกปลุกตื่นวงล้อชะตาจำกัด 1 ชิ้นจาก 12 ชิ้นต่อไปนี้ ได้แก่：「บทเพลงสรรเสริญราชาแห่งทวยเทพ」,     「สะสมอันล้ำค่าที่สุด」,     「ในนามแห่งกุหลาบ」,     「ก้าวข้ามความเจ็บปวด」,     「การถือกำเนิดอันลึกลับ」,     「บัญญัติแห่งราชินี」,     「แผ่นจารึกพระวจนะ」,     「ร่างวิปริตกลืนกิน」,     「มหิทธานุภาพแห่งศรัทธา」,     「ปลายประโยคแห่งบทกวี」,     「การเลี้ยงดูด้วยความเมตตา」,     「ช่วงเวลาแห่งโชคดี」"
  },
  Activity_61369_BannerText = {
    Text = "รับวงล้อโชคชะตาจำกัดฟรี"
  },
  Activity_61370_ActivityName = {
    Text = "ปณิธานเดิมของเงินบริสุทธิ์"
  },
  Activity_61370_ActivityPlot = {
    Text = "เข้าสู่ระบบทุกวันรับวงล้อชะตาจำกัดที่ระลึก SSR「หัวใจเงินบริสุทธิ์」รวมทั้งหมด 16 ชิ้น！"
  },
  Activity_61370_ActivityTips = {
    Text = "<Title:รายละเอียด>\nไม่ว่าโลกจะพลิกผันเพียงใด ตราบใดที่ทุกคนยังคงปกป้องหัวใจเงินบริสุทธิ์ดั้งเดิม เรื่องราวจะหมุนเวียนกลับมา และชีวิตใหม่จะถือกำเนิดขึ้นอีกครั้งบนผืนดินที่รกร้าง\n\n<Title:กฎกิจกรรม>\n·ในช่วงกิจกรรม ผู้พิทักษ์ความลับสามารถรับวงล้อชะตาจำกัดที่ระลึก SSR「หัวใจเงินบริสุทธิ์ดั้งเดิม」ได้ทุกวันหลังเข้าสู่ระบบใน「หัวใจเงินบริสุทธิ์ดั้งเดิม」 รวมทั้งหมด 16 ครั้ง\n·รางวัลจะปลดล็อกตามลำดับจำนวนวันเข้าสู่ระบบสะสม รางวัลเข้าสู่ระบบประจำวันจะรีเซ็ตเวลา 9:00 น. (GMT+8)"
  },
  Activity_61370_BannerText = {
    Text = "รับวงล้อชะตา SSR จำกัดฟรี"
  },
  Activity_61371_ActivityName = {
    Text = "ความปรารถนาแห่งปีกทั้งหกที่บานสะพรั่ง"
  },
  Activity_61371_ActivityPlot = {
    Text = "ท่ามกลางความปั่นป่วนของบ่อมืด แกนเงินจากมิติอันไร้ขอบเขตได้หลุดร่วงผ่านรอยแยกมิติมาสู่ริมบ่อมืด ทาวีรวบรวมมันอย่างพิถีพิถัน แล้ววางไว้ที่มุมหนึ่งของบ่อมืด แม้แกนเงินเหล่านี้จะไม่อาจหยุดยั้งการกัดกร่อนที่แผ่ขยาย แต่ความคิดถึงและหัวใจที่ซ่อนอยู่ภายในจะเปล่งประกายอย่างงดงามตลอดไป"
  },
  Activity_61371_ActivityTips = {
    Text = "<Title:รายละเอียด>\nท่ามกลางความปั่นป่วนของบ่อมืด แกนเงินจากมิติอันไร้ขอบเขตได้หลุดร่วงผ่านรอยแยกมิติมาสู่ริมบ่อมืด ทาวีรวบรวมมันอย่างพิถีพิถัน แล้ววางไว้ที่มุมหนึ่งของบ่อมืด แม้แกนเงินเหล่านี้จะไม่อาจหยุดยั้งการกัดกร่อนที่แผ่ขยาย แต่ความคิดถึงและหัวใจที่ซ่อนอยู่ภายในจะเปล่งประกายอย่างงดงามตลอดไป\n\n<Title:กฎกิจกรรม>\n·ในช่วงกิจกรรม ผู้พิทักษ์ความลับสามารถรับ「แกนเงิน」× 1000 ได้ทุกวันหลังเข้าสู่ระบบ สูงสุด 6 ครั้ง\n·ในช่วงกิจกรรม หากผู้พิทักษ์ความลับเข้าสู่ระบบสะสมครบวันที่ 7 จะได้รับร่างปลุกตื่นจำกัดเวลา「ทาวี」โดยตรง！\n·รางวัลจะปลดล็อกตามลำดับจำนวนวันเข้าสู่ระบบสะสม รางวัลเข้าสู่ระบบประจำวันจะรีเซ็ตเวลา 9:00 น. (GMT+8)"
  },
