  Activity_65387_ActivityName = {
    Text = "คำขอโทษจากแมวโรงเรียน"
  },
  Activity_65387_ActivityPlot = {
    Text = "เมื่อเร็ว ๆ นี้ เนื่องจากช่องโหว่ในมาตรการป้องกันของโรงเรียน ทำให้การกัดกร่อนจาก<Del:「ข้อความชั่วคราว、จุดแดง」>รุกรานวิทยาเขตมากขึ้นเรื่อย ๆ สร้างความไม่สะดวกมากมายแก่นักเรียน ดังนั้นฝ่ายกิจการโรงเรียนจึงจัดตั้งจุดเสบียงหลายแห่ง เพื่อแจกจ่ายสิ่งของเป็นการชดเชยให้แก่นักเรียน (เนื่องจากความรับผิดชอบต่อความผิดพลาดในการจัดการสิ่งอำนวยความสะดวก การขนส่งเสบียงครั้งนี้จึงเป็นหน้าที่ของแมวโรงเรียนทั้งหมด)"
  },
  Activity_65387_ActivityTips = {
    Text = "<Title:รายละเอียด>\nเมื่อเร็ว ๆ นี้ เนื่องจากช่องโหว่ในมาตรการป้องกันของโรงเรียน ทำให้การกัดกร่อนจาก<Del:「ข้อความชั่วคราว、จุดแดง」>รุกรานวิทยาเขตมากขึ้นเรื่อย ๆ สร้างความไม่สะดวกมากมายแก่นักเรียน ดังนั้นฝ่ายกิจการโรงเรียนจึงจัดตั้งจุดเสบียงหลายแห่ง เพื่อแจกจ่ายสิ่งของเป็นการชดเชยให้แก่นักเรียน (เนื่องจากความรับผิดชอบต่อความผิดพลาดในการจัดการสิ่งอำนวยความสะดวก การขนส่งเสบียงครั้งนี้จึงเป็นหน้าที่ของแมวโรงเรียนทั้งหมด)\n\n<Title:กฎกิจกรรม>\n·ในช่วงกิจกรรม ผู้พิทักษ์ความลับสามารถรับ「แกนเงิน」× 500 ได้ทุกวันหลังเข้าสู่ระบบใน「คำขอโทษจากแมวโรงเรียน」สูงสุด 5 ครั้ง\n·รางวัลจะปลดล็อกตามลำดับจำนวนวันเข้าสู่ระบบสะสม รางวัลเข้าสู่ระบบประจำวันจะรีเซ็ตเวลา 9:00 น. (GMT+8)"
  },
  Activity_65387_BannerText = {
    Text = "เช็กอินรับแกนเงิน"
  },
  Activity_65502_ActivityName = {
    Text = "ทำนองก้าวหน้า·บทบรรเลงคู่"
  },
  Activity_65502_ActivityPlot = {
    Text = "ผู้พิทักษ์ความลับสามารถเลือกปลุกวงล้อโชคชะตาจำกัดได้ 1 วงจากรายการด้านล่าง!"
  },
  Activity_65502_ActivityTips = {
    Text = "<Title:รายละเอียด>\nบ่อมืดเต็มไปด้วยคลื่นลมอันคาดเดาไม่ได้ วงล้อชะตาหมุนเวียนไม่สิ้นสุด ภายใต้การนำทางของเสียงเพลงแห่งฮาเมลิน ทำนองอันไร้ขอบเขตบรรเลงพร้อมกัน รวมเป็นวงล้อชะตาแห่งเส้นทางที่เธอได้เดินทางผ่านมา ขอให้พลังของพวกมันร่วมเคียงข้างเธอจนถึงตัวหยุดของบทเพลงสุดท้าย\n\n<Title:กฎกิจกรรม>\n·ในช่วงกิจกรรม เพียงเข้าสู่ระบบ 1 วัน ก็สามารถเลือกปลุกตื่นวงล้อชะตาจำกัด 1 ชิ้นจาก 12 ชิ้นต่อไปนี้ ได้แก่：「บทเพลงสรรเสริญราชาแห่งทวยเทพ」,     「สะสมอันล้ำค่าที่สุด」,     「ในนามแห่งกุหลาบ」,     「ก้าวข้ามความเจ็บปวด」,     「การถือกำเนิดอันลึกลับ」,     「บัญญัติแห่งราชินี」,     「แผ่นจารึกพระวจนะ」,     「ร่างวิปริตกลืนกิน」,     「มหิทธานุภาพแห่งศรัทธา」,     「ปลายประโยคแห่งบทกวี」,     「การเลี้ยงดูด้วยความเมตตา」,     「ช่วงเวลาแห่งโชคดี」"
  },
