  Activity_66375_ActivityName = {
    Text = "การต่อสู้สุดท้าย: เงาแห่งต้นกำเนิด"
  },
  Activity_66375_ActivityPlot = {
    Text = "พระเนตรของพระองค์กวาดผ่านมิติจำนวนนับไม่ถ้วน ตรงข้ามกับพระองค์คือเงาร่างสีเงินนับหมื่น \nพวกเขาเล็กและเปราะบาง พวกเขาต่อสู้เพื่อจดจำ จนกว่าชีวิตจะหาไม่"
  },
  Activity_66375_ActivityStageEndContent = {
    Text = "กิจกรรมได้บรรลุแล้ว,     สามารถไปสอบสวนต่อได้."
  },
  Activity_66375_ActivityTips = {
    Text = "<Title: ร่วมต่อสู้กับจุดเริ่มต้น>\n·「ร่วมต่อสู้กับจุดเริ่มต้น」ประกอบด้วย 7 ด่านที่ไม่สามารถเล่นซ้ำได้และจะเข้าสู่การท้าทายโดยตรงกับ「วิสัยทัศน์แห่งจุดเริ่มต้น」ในวันแรกของกิจกรรมจะเปิด 3 ด่านแรก จากนั้นทุกๆ 3 วัน จะเปิดอีก 1 ด่าน.\n·เมื่อท้าทายและเอาชนะ「วิสัยทัศน์แห่งจุดเริ่มต้น」ที่เกี่ยวข้องได้สำเร็จ ก็จะได้รับรางวัลที่สอดคล้องกัน.\n·「วิสัยทัศน์แห่งจุดเริ่มต้น」แต่ละประเภทมีเงาจำนวนมาก เมื่อผู้พิทักษ์ท่านใดก็ตามท้าทายและเอาชนะ「วิสัยทัศน์แห่งจุดเริ่มต้น」ชนิดหนึ่งได้ 「จำนวนเงาคงเหลือของโลก」ของประเภทนั้นจะลดลง 1 และเมื่อเงาทั้งหมดถูกกำจัด ด่านที่เกี่ยวข้องจะปิดและไม่สามารถท้าทายซ้ำได้.\n·ทุกด่านได้รับผลกระทบจาก「ภัยพิบัติคลื่นดำ·จุดจบ」แต่แต่ละด่านจะมอบ「แกนเงินบริสุทธิ์」สิ่งสร้างที่แตกต่างกัน ซึ่งจะมอบโบนัสที่ทรงพลังให้คุณ นอกจากนี้ แต่ละด่านยังมอบ「ดวงตาแห่งความรอบรู้」สิ่งสร้างที่จะทำให้ทาวีได้รับความคลั่ง 120 หน่วยเมื่อเริ่มต้นการต่อสู้ และเพิ่มความเสียหาย โล่ และผลการฟื้นฟูชีวิตของทาวีขึ้น 50%.\n·ทุกด่านจำเป็นต้องเลือกตัวช่วย ในระหว่างกิจกรรม ผู้พิทักษ์ที่ติดตามกันเองแต่ละคนสามารถช่วยเหลือคุณได้เพียงครั้งเดียว เนื่องจากการใช้ตัวช่วย อัตราการประสานที่แท้จริงจะเพิ่มขึ้นอีก 50% จากโบนัสพื้นฐาน.\n·ผู้พิทักษ์จำเป็นต้องทำ「การสอบสวนดำเนินการ」2-9 ให้เสร็จสิ้นอย่างน้อยก่อนจึงจะสามารถเข้าร่วมกิจกรรมนี้ได้.\n\n<Title: การสอบสวนดำเนินการ：บทสุดท้าย>\n·ตัวหลักของ「วิสัยทัศน์แห่งจุดเริ่มต้น」แต่ละประเภทยังคงต้องถูกคุณพิชิตด้วยตนเองใน「การสอบสวนดำเนินการ」9-5 ถึง 9-11 ด่านพิเศษเหล่านี้ไม่มีความสำเร็จ ไม่มีดาว ไม่มี「ดวงตาแห่งความรอบรู้」สิ่งสร้างช่วยเหลือ ไม่สามารถใช้ตัวช่วยได้ และยากกว่าปกติ.\n·หลังจากกิจกรรม「ร่วมต่อสู้กับจุดเริ่มต้น」สิ้นสุดลง ด่านถัดไปของ「การสอบสวนดำเนินการ：บทสุดท้าย」จะถูกปลดล็อก เมื่อผู้พิทักษ์ทุกคนช่วยกันกำจัดเงาทั้งหมดของ「วิสัยทัศน์แห่งจุดเริ่มต้น」แต่ละประเภท ด่านที่เกี่ยวข้องใน「การสอบสวนดำเนินการ」9-5 ถึง 9-11 จะถูกปลดล็อกล่วงหน้า."
  },
  Activity_66375_BannerText = {
    Text = "กิจกรรมพิเศษเปิดให้เข้าร่วมแบบจำกัดเวลา!"
  },
  Activity_66908_ActivityName = {
    Text = "ลมหายใจแห่งความอุดมสมบูรณ์"
  },
  Activity_66908_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n·ในช่วงที่กิจกรรม「ลมหายใจแห่งความอุดมสมบูรณ์」เปิดให้บริการ ผู้พิทักษ์สามารถใช้ทีมที่ระบบตั้งค่าไว้ล่วงหน้าซึ่งมีเทอิซเพื่อสัมผัสด่านที่กำหนดได้ไม่จำกัดจำนวนครั้ง\n·ขณะสัมผัสด่านกิจกรรม ไม่สามารถปรับเปลี่ยนร่างตื่นในทีมได้\n<Title:รางวัลกิจกรรม>\n·เมื่อผ่านความท้าทายของด่านเป็นครั้งแรก สามารถรับรางวัลทดลองเล่นได้ที่หน้ากิจกรรม"
  },
  Activity_67077_ActivityName = {
    Text = "ของขวัญรำลึกเส้นทาง Ⅸ"
  },
  Activity_67077_ActivityPlot = {
    Text = "ความทรงจำหนึ่งถูกปิดผนึกจัดเก็บ เส้นทางหนึ่งถูกบันทึกไว้ในอดีต เมื่อรำลึก อย่าลืมถวายเครื่องบูชาแห่งความเคารพ"
  },
  Activity_67718_ActivityName = {
    Text = "ในฤดูใบไม้ผลิ ก่อนจะร่วงโรย·กลับมาอีกครั้ง"
  },
  Activity_67718_ActivityPlot = {
    Text = "เสียงหัวเราะของสาวๆ ดังขึ้น สะท้อนไปทั่วสวนที่เพลิงยังไม่ได้ลุกโชน \nจงหยุดพักเพื่อชื่นชมความงดงามของอดีตอันแสนหวานนี้เถิด เพื่อนของฉัน \nฟังเสียงของฤดูใบไม้ผลิที่ยังไม่จางหาย เล่าเรื่องราวในอดีตอย่างแผ่วเบาและไพเราะ"
  },
  Activity_67718_ActivityStageEndContent = {
