  Activity_67721_ActivityName = {
    Text = "ในฤดูใบไม้ผลิ ก่อนจะร่วงโรย·กลับมาอีกครั้ง"
  },
  Activity_67721_ActivityPlot = {
    Text = "เสียงหัวเราะของสาวๆ ดังขึ้น สะท้อนไปทั่วสวนที่เพลิงยังไม่ได้ลุกโชน \nจงหยุดพักเพื่อชื่นชมความงดงามของอดีตอันแสนหวานนี้เถิด เพื่อนของฉัน \nฟังเสียงของฤดูใบไม้ผลิที่ยังไม่จางหาย เล่าเรื่องราวในอดีตอย่างแผ่วเบาและไพเราะ"
