  Activity_70438_ActivityPlot = {
    Text = "เทศกาลชิสุ่ยกำลังจะมาถึง ทุกคนต่างให้ความสนใจกับการเตรียมงานเฉลิมฉลอง และไม่มีใครสังเกตเห็นว่ามีกลุ่มสีดำในมุมหนึ่งกำลังขยับตัวอย่างเงียบเชียบ นักโทษตัวน้อยได้กลายเป็นของเหลวและหลบหนีออกจากกรงขัง \n เมื่อรอยแยกของมิติส่องประกาย ขนสีดำก้อนนั้นเริ่มแบ่งตัว... ทะเลแมวสีดำจำนวนมากกำลังกลืนกินทั้งโรงเรียน! \n เดิมทีคุณตั้งใจจะเมินเฉยเหตุการณ์ประหลาดนี้และปล่อยให้ฝ่ายบริหารโรงเรียนจัดการ \n แต่เมื่อเห็นว่าพวกมันปล่อยเงินใจและคูปองทอง คุณจึงเปลี่ยนใจ"
  },
  Activity_70438_ActivityTips = {
    Text = "<Title:ข้อมูลกิจกรรม>\nกิจกรรมการเล่น「อูซ่าเหมียวเหมียวเรต」เปิดให้เข้าร่วมแบบจำกัดเวลา! ในระยะเวลาของกิจกรรม ผู้พิทักษ์สามารถใช้「แมวหลายตัวกระโดดและเต้นอย่างอลหม่าน」เพื่อทำร้ายแมวโรงเรียน และยังสามารถรับเงินใจจำนวนมากและคูปองกุหลาบทองได้!\n\n<Title:เวลาของกิจกรรม>\n1 มกราคม 24 เวลา 9:00 - 2 กุมภาพันธ์ 5 เวลา 9:00 (GMT+8) ในระยะเวลาของกิจกรรมสามารถเข้าร่วม「แมวหลายตัวกระโดดและเต้นอย่างอลหม่าน」ในแต่ละวันที่ปลดล็อกได้ ส่วนเนื้อหาของด่านที่สิ้นสุดแล้วไม่สามารถเข้าร่วมได้อีก.\n\n<Title:แมวหลายตัวกระโดดและเต้นอย่างอลหม่าน>\n1,「แมวหลายตัวกระโดดและเต้นอย่างอลหม่าน」มีทั้งหมด 12 ด่าน โดยจะเปิดด่านที่แตกต่างกันในแต่ละวัน ส่วนเนื้อหาของด่านที่สิ้นสุดแล้วไม่สามารถเข้าร่วมได้อีก.\n2 ทุกครั้งที่ท้าทายจะไม่ใช้「เมโนฟิน」และเมื่อผ่านด่าน 1 ครั้งจะได้รับ「แกนบริสุทธิ์」,「เงินใจ」,「คูปองกุหลาบทอง」.\n3 ด่านในครั้งนี้ไม่สามารถใช้การช่วยเหลือจากสมาคมศิษย์เก่าได้.\n4 ในด่านของวันนั้นๆ ผู้ปลุกตื่นแต่ละคนสามารถเข้าร่วมได้เพียง 1 ครั้ง.\n5 ด่านในแต่ละวันจะต้องใช้ดินแดนที่กำหนดในการท้าทาย.\n·1 มกราคม 24: ดินแดนเคออส\n·1 มกราคม 25: ดินแดนทะเลลึก\n·1 มกราคม 26: ดินแดนเนื้อและเลือด\n·1 มกราคม 27: ดินแดนอัลตร้า\n·1 มกราคม 28: ไม่จำกัด\n·1 มกราคม 29: ไม่จำกัด\n·1 มกราคม 30: ดินแดนเคออสและดินแดนทะเลลึก\n·1 มกราคม 31: ดินแดนเนื้อและเลือดและดินแดนอัลตร้า\n·2 กุมภาพันธ์ 1: ดินแดนเคออสและดินแดนเนื้อและเลือด\n·2 กุมภาพันธ์ 2: ดินแดนทะเลลึกและดินแดนอัลตร้า\n·2 กุมภาพันธ์ 3: ดินแดนเคออสและดินแดนอัลตร้า\n·2 กุมภาพันธ์ 4: ดินแดนเนื้อและเลือดและดินแดนทะเลลึก"
  },
  Activity_70438_BannerText = {
    Text = "กิจกรรมพิเศษเปิดให้เข้าร่วมแบบจำกัดเวลา!"
  },
  Activity_71095_ActivityName = {
    Text = "ปลดล็อกด่านเนื้อเรื่องรองฟรี"
  },
  Activity_71095_ActivityTips = {
    Text = "<Title:เงื่อนไขการเข้าร่วม>\n·สามารถเข้าร่วมได้หลังจากเสร็จสิ้น「การสอบสวนดำเนินการ」2-9 ระดับปกติแล้วเท่านั้น \n<Title:เหตุการณ์การสอบสวน>\n·ในช่วงเวลาของกิจกรรม จะมีการเปิดเผย「เรื่องราวแห่งเวทมนตร์」ใหม่ของการสอบสวนทุกวัน ผู้พิทักษ์ไม่จำเป็นต้องใช้สิ่งของในการปลดล็อกเพื่อทำการสอบสวน เมื่อเสร็จสิ้นเหตุการณ์การสอบสวนแล้วจะได้รับรางวัล เช่น แกนบริสุทธิ์ เข็มกลัดสอบสวน และประสบการณ์ของผู้พิทักษ์ความลับ เป็นต้น \n·เมื่อกิจกรรมสิ้นสุดลง ความคืบหน้าของการสอบสวนใน「เรื่องราวแห่งเวทมนตร์」จะยังคงอยู่ ผู้พิทักษ์สามารถใช้ไข่มุกหลอมละลายในบันทึกภารกิจพิเศษเพื่อปลดล็อกการสอบสวนที่ยังไม่ได้ปลดล็อก และหลังจากเสร็จสิ้นเหตุการณ์การสอบสวนที่ยังไม่เสร็จสิ้นในช่วงกิจกรรม ก็จะได้รับรางวัลการสอบสวนที่เหมือนกับในช่วงกิจกรรม <Title:รางวัลจำกัดเวลา>\n·ในช่วงเวลาของกิจกรรมจะมีการเปิดตัวรางวัลจำกัดเวลา ผู้พิทักษ์ที่ผ่านด่าน「เรื่องราวแห่งเวทมนตร์」โหมดปกติและเสร็จสิ้นเหตุการณ์การสอบสวนของ「เรื่องราวแห่งเวทมนตร์」จะได้รับรางวัล เช่น แกนบริสุทธิ์ หินของนักปราชญ์ และเงินใจ! รางวัลจำกัดเวลาจะเปิดให้เฉพาะช่วงเวลาของกิจกรรมเท่านั้น เมื่อกิจกรรมสิ้นสุดลงจะไม่สามารถทำหรือรับได้อีก"
  },
