  Activity_71098_ActivityPlot = {
    Text = "เธอยืนหยัดนำหน้าผู้คนเสมอ \nทีละก้าว รอยเท้าของเธอเป็นแนวทางให้ผู้คนก้าวตาม \nแต่ผู้คนมักลืมว่า อัจฉริยะกับคนบ้าอาจห่างกันแค่เพียงก้าวเดียว"
