  Activity_71982_ActivityPlot = {
    Text = "คุณมาถึงห้องอาจารย์ใหญ่ แต่กลับพบว่าภายในห้องไม่มีใครอยู่เลย ดูเหมือนจดหมายฉบับนั้นจะเป็นแค่เรื่องหลอกลวง\nขณะที่คุณกำลังจะจากไป สายตาก็เหลือบไปเห็นกล่องของขวัญสวยงามกล่องหนึ่ง พร้อมข้อความที่แปะอยู่บนนั้น——ถึงเธอที่รัก"
