  Activity_71983_ActivityPlot = {
    Text = "เสียงกรอบแกรบดังขึ้นในห้องที่เงียบสงบ เมื่อคุณเข้าไปดู หน้าต่างที่เปิดอ้าบ่งบอกว่า “แขกไม่ได้รับเชิญ” ได้จากไปแล้ว\nแสงแดดอุ่นๆ ส่องลงบนกล่องของขวัญที่ปรากฏขึ้นบนโต๊ะ ตัวอักษรสวยงามเปล่งประกายสีเงิน——ขอให้โชคชะตาเมตตาเธอตลอดไป"
