  Activity_80312_ActivityTips = {
    Text = "กฎกิจกรรม：\n1,     หลังจากผู้พิทักษ์ความลับทำภารกิจบันทึกการเดินทางที่กำหนดสำเร็จ สามารถรับรางวัลได้ที่「บันทึกสถานพักฟื้น」\n2,     「บันทึกสถานพักฟื้น」เปิดถาวร\n3,     หลังปลดล็อก「บันทึกขั้นสูง」 จะสามารถรับรางวัลเพิ่มเติมหลังทำภารกิจสำเร็จ\n4,     โปรดทราบ：「บันทึกขั้นสูง」ที่ปลดล็อกในกิจกรรมนี้มีผลเฉพาะในกิจกรรมนี้เท่านั้น กรุณาใช้จ่ายอย่างมีสติ"
  },
  Activity_81019_ActivityName = {
    Text = "การเดินทางที่น่าพิศวงในการทำความสะอาด"
  },
  Activity_81019_ActivityPlot = {
    Text = "เป็นใครที่วิ่งเล่นอยู่ในคาดาธในฝัน ช่วยเจ้าของบ้านจัดการขยะ?\nคือคาเรน~คือคาเรน！\nการทำความสะอาดการย่อยสลาย~การระบายอากาศในฝัน~การฆ่าเชื้อในมิติ~ทำความสะอาดให้หมด！\nท้ายที่สุดแล้วในด้านการทำความสะอาด คาเรนเราก็เป็นมืออาชีพ！\nอาจารย์อยากลองหน่อยไหม！ คาเรนจะสอนวิธีทำความสะอาดให้เจ้าของอย่างไม่มีข้อมูลไหนเก็บไว้！"
  },
  Activity_81019_ActivityTips = {
    Text = "<Title:ภาพรวมกิจกรรม>\n1,     ในระหว่างกิจกรรม ผู้พิทักษ์สามารถเข้าร่วม「กำจัดความก้าวหน้า」และรับ「เครื่องมือทำความสะอาด」\n2,     「เครื่องมือทำความสะอาด」เมื่อสะสมถึงจำนวนที่กำหนดสามารถรับรางวัลมากมายใน「เบี้ยบำนาญกำจัดฝุ่น」 รวมถึงอวตารที่จำกัดในกิจกรรม「ปรมาจารย์ผู้ทำความสะอาด」 เงิน แกนบริสุทธิ์ และเศษหินสติปัญญา\n\n<Title: กำจัดความก้าวหน้า>\n1 ใน「กำจัดความก้าวหน้า」ประกอบไปด้วยหลายประเภทความท้าทายการทำความสะอาด ผู้พิทักษ์สามารถทำความสะอาดเพื่อรับ「เครื่องมือทำความสะอาด」 และเมื่อทำความสะอาดความท้าทายทั้งหมดในแต่ละวันยังมีรางวัลพิเศษ!\n2 ในช่วงเวลาของกิจกรรม ทุกครั้งที่ทำความสะอาดภารกิจ 1 ชนิดจะมีการเล่นเรื่องราวที่ซ่อนอยู่\n3 「กำจัดความก้าวหน้า」จะมีการรีเซ็ตทุกวันในเวลา 9:00 น.(GMT+8) ในช่วงกิจกรรม\n\n<Title: เบี้ยบำนาญกำจัดฝุ่น>\n1 ผู้พิทักษ์สะสม「เครื่องมือทำความสะอาด」สามารถรับรางวัลที่เกี่ยวข้องได้ โดยเมื่อถึง 1000「เครื่องมือทำความสะอาด」สามารถรับรางวัลการให้วัสดุที่มากมาย และเมื่อสะสมถึง 10000「เครื่องมือทำความสะอาด」จะได้รับอวตารพิเศษ「ปรมาจารย์ผู้ทำความสะอาด」\n\n<Title:ของขวัญจากการให้ของคาเรน>\nในระหว่างกิจกรรม สามารถเช็คอินที่「ของขวัญจากการให้ของคาเรน」เพื่อรับของขวัญที่คาเรนเตรียมไว้ให้ผู้พิทักษ์!\n\n<Title:ระยะเวลากิจกรรม>\nกิจกรรมนี้จะเปิดขึ้นเฉพาะในระหว่างวันที่ 28 เมษายน 9:00 - 12 พฤษภาคม 9:00(GMT+8) หลังจากวันที่ 12 พฤษภาคม 9:00(GMT+8) กิจกรรมจะสิ้นสุด กรุณาขอให้ผู้พิทักษ์อย่าลืมรับรางวัลใน「เบี้ยบำนาญกำจัดฝุ่น」ด้วยนะ!"
  },
  Activity_81019_BannerText = {
    Text = "กิจกรรมพิเศษเปิดให้เข้าร่วมแบบจำกัดเวลา!"
  },
  Activity_81178_ActivityName = {
    Text = "ในพายุฝนกระหน่ำ"
  },
  Activity_81178_ActivityPlot = {
    Text = "ฝนตกหนักจากฟ้าสีเทา ทำให้ผิวน้ำเกิดเสียงดังป๊อกๆ.\nฟ้าแลบที่โหดร้ายคำรามออกมาอย่างไร้ความปรานี ประกาศถึงความน่ากลัวที่ไม่มีที่สิ้นสุดใต้ผิวน้ำ.\nนอตดีลัสอันรุ่งโรจน์เหมือนทารกที่เดินโซซัดโซเซ สั่นไหวอย่างอ่อนแอในคลื่นมหึมา.\nไม่มีใครรู้ชะตากรรมของตนจะเป็นเช่นไร เมื่อมหาสมุทรที่ไม่แน่นอนแสดงความโกรธเกรี้ยว ผู้คนจึงเข้าใจว่าตนมีความเล็กน้อยเพียงใด."
  },
  Activity_81178_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลง ปัจจุบันสามารถเข้าร่วม「สมบัติของลูกเรือ」เท่านั้น"
  },
  Activity_81178_ActivityTips = {
    Text = "<Title:บทนำกิจกรรม>\nในระยะเวลากิจกรรม ผู้พิทักษ์สามารถรวบรวมเงินตรากิจกรรม「ธงสัญญาณ」ได้ผ่านการเล่นจำกัดเวลา「หลงทางในทะเลลึก」และ「รางวัลความสำเร็จ」「ธงสัญญาณ」สามารถแลกเป็นรางวัลได้ใน「สมบัติลับของลูกเรือ」ประกอบไปด้วยวงล้อมชีวิต SR ที่มีจำกัดในกิจกรรม「ผู้นำทางแห่งท้องทะเล」แกนกลางของลูเมน แกนบริสุทธิ์ เศษหินปัญญา คริสตัลเลียนแบบ และอื่นๆ \n\n<Title:หลงทางในทะเลลึก>\n1.「หลงทางในทะเลลึก」ประกอบไปด้วยด่านรวบรวมวัตถุดิบ 9 ด่านที่ไม่ต้องสำรวจแต่ต่อสู้เท่านั้น ซึ่งเปิดทุกวันทีละหนึ่งด่าน \n2.ในการท้าทายแต่ละครั้งจะใช้ 「เมโนฟิน」× 120 หากสำเร็จจะได้รับวัตถุดิบการพัฒนาและเงินตรากิจกรรม\n3.เมื่อผ่านด่านจะปลดล็อกฟังก์ชัน「ทำซ้ำ」ของด่านนั้น โปรดทราบว่าการใช้ฟังก์ชัน「ทำซ้ำ」จะไม่สามารถรับอัตราการประสานได้\n4.สามารถใช้ช่วยเหลือจากสมาคมเพื่อนได้เพื่อช่วยให้ผ่านด่านได้ง่ายขึ้น\n\n<Title:การเพิ่มธงสัญญาณ>\n1. ผู้พิทักษ์ที่ครอบครองผู้ปลุกตื่นหรือวงล้อมชีวิตเฉพาะ(ไม่จำเป็นต้องจัดลงสนาม) จะสามารถได้รับโบนัสการดรอปพิเศษในรางวัลภารกิจด่านของ「หลงทางในทะเลลึก」(รวมถึงทำซ้ำ) การเพิ่มจะเป็นดังนี้: \n· ผู้ปลุกตื่น 「คอร์โปซานต์」：การตื่นพลัง 0/1/2/3 หรือสูงกว่า การเพิ่ม 20%/30%/40%/50%\n· วงล้อมชีวิต SSR 「การชี้นำของไฟศักดิ์สิทธิ์」：ตำแหน่งซ้อน 0/1/2/3 หรือสูงกว่า การเพิ่ม 20%/30%/40%/50%\n· วงล้อมชีวิต SR 「ผู้นำทางแห่งท้องทะเล」：ตำแหน่งซ้อน 0/1/2/3 หรือสูงกว่า การเพิ่ม 20%/30%/40%/50%\n2. การเพิ่มธงสัญญาณจากผู้ปลุกตื่นหรือวงล้อมชีวิตต่าง ๆ จะคำนวณโดยการสะสมรวมกัน \n3. เป็นพิเศษ รางวัลความท้าทายสำเร็จครั้งแรกในระดับความยากบ้าคลั่งจะไม่ได้รับผลกระทบจากโบนัสที่กล่าวข้างต้น\n\n<Title: สมบัติลับของลูกเรือ>\n1. การ「ส่งมอบธง」แต่ละครั้งจะใช้ 「ธงสัญญาณ」750 อัน และจะสุ่มได้รับรางวัลสิ่งของใน「สมบัติลับของลูกเรือ」จำนวนห้าชิ้น\n2. รางวัลสิ่งของใน「สมบัติลับของลูกเรือ」แบ่งเป็นสองประเภท คือ 「วัสดุพิเศษ」และ「ของธรรมดา」 การรีเซ็ตจะสามารถรีเซ็ตจำนวนที่เหลือของรางวัลวัสดุพิเศษให้สูงสุดได้ กฎเฉพาะคือ: \n(1) 5 การรีเซ็ตแรก: เมื่ 「วัสดุพิเศษ」ไม่มีจำนวนที่เหลืออยู่แล้ว ผู้พิทักษ์สามารถเลือกที่จะรีเซ็ต ซึ่งหลังจากรีเซ็ตจำนวนที่เหลือของ「วัสดุพิเศษ」และ「ของธรรมดา」จะกลับไปที่ระดับสูงสุดได้ หรือสามารถเลือกที่จะแลกเปลี่ยนต่อไปได้ เมื่อ「ของธรรมดา」ไม่มีจำนวนเหลืออยู่แล้ว จำเป็นต้องดำเนินการรีเซ็ตเพื่อแลกเปลี่ยนต่อไป\n(2) การรีเซ็ตครั้งที่ 6 และหลังจากนั้น: เมื่ 「ของธรรมดา」ไม่มีจำนวนที่เหลืออยู่แล้วเท่านั้นจึงสามารถดำเนินการรีเซ็ตได้ ซึ่งการรีเซ็ตนี้จะรีเซ็ตจำนวนที่เหลือของ「ของธรรมดา」ให้สูงสุด โดย「วัสดุพิเศษ」จะไม่ได้รับการรีเซ็ตอีกต่อไป\n\n<Title: เวลากิจกรรม>\n1. 5 พฤษภาคม 9:00 - 19 พฤษภาคม 9:00(GMT+8) เนื้อหาทั้งหมดในบทนำกิจกรรมสามารถเข้าร่วมได้\n2. 19 พฤษภาคม 9:00 - 26 พฤษภาคม 9:00(GMT+8) จะคงเหลือเฉพาะ「สมบัติลับของลูกเรือ」และ「รางวัลความสำเร็จ」เนื้อหาอื่น ๆ ทั้งหมดสิ้นสุดแล้วไม่สามารถเข้าร่วมได้\n3. หลังจาก 26 พฤษภาคม 9:00(GMT+8) 「ธงสัญญาณ」ที่เหลือยังไม่ได้แลกเปลี่ยนจะถูกเก็บคืนตามอัตราแลกหนึ่ง「คูปองกุหลาบทอง」× 40 โปรดผู้พิทักษ์อย่าลืมตรวจสอบจดหมายของคุณด้วย."
  },
