  Activity_84175_ActivityName = {
    Text = "การเดินทางตามกฎฟื้นฟู"
  },
  Activity_84175_ActivityTips = {
    Text = "กฎกิจกรรม:\n1. ผู้พิทักษ์ทำภารกิจเดินทางที่กำหนด สามารถรับรางวัลใน 「กระดานแห่งการทบทวน」\n2. ภารกิจแบ่งออกเป็นหลายกลุ่ม และจะปลดล็อคทุกวันหลังจากเริ่มกิจกรรม\n3. หลังจากปลดล็อค 「กระดานแห่งการทบทวน」 แล้ว สามารถรับรางวัลเพิ่มเติมหลังจากทำภารกิจสำเร็จ\n4. โปรดระวัง: 「กระดานแห่งการทบทวน」 ที่ปลดล็อคในกิจกรรมนี้ จะมีผลเฉพาะในกิจกรรมนี้เท่านั้น โปรดบริโภคอย่างมีเหตุผล"
  },
  Activity_84176_ActivityName = {
    Text = "การเดินทางผ่านเวลา"
  },
  Activity_84176_ActivityTips = {
    Text = "กฎกิจกรรม:\n1. ผู้พิทักษ์ทำภารกิจเดินทางที่กำหนด สามารถรับรางวัลใน 「กระดานแห่งการผูกมัด」\n2. ภารกิจแบ่งออกเป็นหลายกลุ่ม และจะปลดล็อคทุกวันหลังจากเริ่มกิจกรรม\n3. หลังจากปลดล็อค 「กระดานแห่งการผูกมัด」 แล้ว สามารถรับรางวัลเพิ่มเติมหลังจากทำภารกิจสำเร็จ\n4. โปรดระวัง: 「กระดานแห่งการผูกมัด」 ที่ปลดล็อคในกิจกรรมนี้ จะมีผลเฉพาะในกิจกรรมนี้เท่านั้น โปรดบริโภคอย่างมีเหตุผล"
