  Activity_89008_ActivityName = {
    Text = "การติดตามข้ามมิติที่วนเวียน"
  },
  Activity_89008_ActivityPlot = {
    Text = "เธอเดินทางผ่านมิตินับไม่ถ้วน โลกนับไม่ถ้วน ผ่านความหวังและความสิ้นหวังนับไม่ถ้วน แต่เธอจะไม่หยุดก้าวเดิน เพราะเธอรู้ชัดถึงจุดหมายปลายทางของตน——ที่ที่มีเธออยู่"
  },
  Activity_89008_ActivityTips = {
    Text = "<Title:รายละเอียด>\n1,     ในช่วงกิจกรรม ผู้พิทักษ์ความลับสามารถรับรางวัลเช็กอินประจำวันได้ใน「การติดตามข้ามมิติที่วนเวียน」หลังเข้าสู่ระบบทุกวัน\n2,     รางวัลจะปลดล็อกตามลำดับจำนวนวันเข้าสู่ระบบสะสม รางวัลเช็กอินประจำวันจะรีเซ็ตเวลา 9:00 น.(GMT+8)\n\n<Title:ภารกิจจำกัดเวลา>\n·ในช่วงกิจกรรม เข้าสู่ระบบสะสมครบ 7 วันจะสำเร็จภารกิจจำกัดเวลา รับ「คูปองออกแบบชุดมายาแบบเรียบง่าย(เฟส 1)」×1！\n·ในช่วง 26 พฤษภาคม 9:00 – 9 มิถุนายน 9:00(GMT+8) สามารถใช้「คูปองออกแบบชุดมายาแบบเรียบง่าย(เฟส 1)」แลกชุดมายาแบบเรียบง่ายได้ที่「ร้านค้า：สั่งซื้อชุดมายา」\n·ช่องทางอื่นในการรับ「คูปองออกแบบชุดมายาแบบเรียบง่าย(เฟส 1)」สามารถดูได้ในชุมชนและประกาศ"
  },
  Activity_89008_BannerText = {
    Text = "เช็กอินรับแกนไร้มลทินมากมาย"
