  Activity_89576_ActivityName = {
    Text = "ขอให้ความหวังผลิบานอีกครั้ง"
  },
  Activity_89576_ActivityPlot = {
    Text = "เข้าสู่ระบบทุกวันรับวงล้อชะตาจำกัดที่ระลึก SSR「เกิดใหม่จากดินแดนสูญสลาย」รวมทั้งหมด 16 ชิ้น！"
  },
  Activity_89576_ActivityTips = {
    Text = "<Title:รายละเอียด>\nโลกกำลังพังทลาย ในโลกเช่นนี้ ความสิ้นหวังคือเรื่องปกติ ความเจ็บปวดคือเรื่องปกติ ฉันต้องชินกับมัน แต่...ยังมีความอบอุ่นซ่อนตัวอยู่ในหัวใจของฉัน รอคอยที่จะทะลุออกมา\n\n<Title:กฎกิจกรรม>\n·ในช่วงกิจกรรม ผู้พิทักษ์ความลับสามารถรับวงล้อชะตาจำกัดที่ระลึก SSR「เกิดใหม่จากดินแดนสูญสลาย」ได้ทุกวันหลังเข้าสู่ระบบใน「ขอให้ความหวังผลิบานอีกครั้ง」 รวมทั้งหมด 16 ครั้ง\n·รางวัลจะปลดล็อกตามลำดับจำนวนวันเข้าสู่ระบบสะสม รางวัลเข้าสู่ระบบประจำวันจะรีเซ็ตเวลา 9:00 น. (GMT+8)"
  },
  Activity_89576_BannerText = {
    Text = "รับวงล้อชะตา SSR จำกัดฟรี"
  },
  Activity_89729_ActivityName = {
    Text = "ปลดล็อกด่านเนื้อเรื่องรองฟรี"
  },
  Activity_89730_ActivityName = {
    Text = "นักโทษกระจก"
  },
  Activity_89730_ActivityPlot = {
    Text = "นกบินเอยนกบิน ทำไมถึงมีเครื่องจองจำที่ขาดบนเท้าของเธอ?\nนกบินเอยนกบิน ทำไมถึงส่งเสียงร้องอย่างโดดเดี่ยวอยู่บนฟ้าสูง?\nเมื่อรอดพ้นจากหนามหนา หลบพ้นจากหว่างขา เธอกางปีกบินผ่านทะเลทรายเหลืองยาวสุดลูกหูลูกตา แต่เสียงร้องเสียใจยังไม่เคยหยุด ใครกันแน่ จะเป็นคนที่เธอตามหาในการเดินทางอันซื่อสัตย์? ที่ไหนกัน ที่จะเป็นบ้านที่แท้จริงที่เธอตามหา?"
  },
  Activity_89730_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลง ขณะนี้สามารถเข้าร่วม「ความปรารถนาที่จะเรียนรู้」ได้เพียงอย่างเดียว"
  },
  Activity_89730_ActivityTips = {
    Text = "<Title:แนะนำกิจกรรม>\n1,     ในช่วงระยะเวลากิจกรรม ผู้พิทักษ์สามารถเก็บรวบรวมสกุลเงินกิจกรรม 「หนังสือความรู้ทั่วไป」,     「หนังสือคณิตศาสตร์」,     「หนังสือวรรณกรรม」 ผ่านกิจกรรมการเล่นเกมแบบจำกัดเวลา 「บินข้ามฟ้าใส」,     「การเดินทางในฝัน」 และ 「รางวัลความสำเร็จ」 โดยสามารถใช้ 「หนังสือความรู้ทั่วไป」,     「หนังสือคณิตศาสตร์」,     「หนังสือวรรณกรรม」 ใน 「ความปรารถนาในการแสวงหาความรู้」 เพื่อซื้อสินค้า รวมถึงวงล้อมชีวิต SR พิเศษช่วงกิจกรรม「ขนนกที่โดดเดี่ยว」,     แกนกลางของลูเมน,     แกนบริสุทธิ์ เป็นต้น.\n2,     ในช่วงระยะเวลากิจกรรม 「โลกแห่งความฝันประหลาด：เหนือขอบฟ้า·บน」 สามารถปลดล็อกได้ฟรีในเวลาจำกัด การทำความสำเร็จในกิจกรรมจะทำให้ได้รับรูปลักษณ์โปรไฟล์พิเศษช่วงกิจกรรม 「ชื่อของกุญแจเงิน：คาสเตอร์」！\n\n<Title:ระยะเวลากิจกรรม>\n1,     2 มิถุนายน เวลา 09:00 - 16 มิถุนายน เวลา 09:00(GMT+8): สามารถเข้าร่วมกิจกรรมการเล่นเกมทั้งหมด.\n2,     16 มิถุนายน เวลา 09:00 - 23 มิถุนายน เวลา 09:00(GMT+8): สามารถเข้าร่วม 「ความปรารถนาในการแสวงหาความรู้」 และรางวัลความสำเร็จได้เท่านั้น.\n\n<Title:บินข้ามฟ้าใส>\n1,     「บินข้ามฟ้าใส」 มีทั้งหมด 7 ด่าน โดยจะเปิดอัตโนมัติวันละ 1 ด่าน.\n2,     การท้าทายแต่ละครั้งจะใช้ 「เมโนฟิน」×120 โดยสำเร็จการท้าทายจะได้รับสกุลเงินกิจกรรม.\n3,     เมื่อผ่านด่าน จะปลดล็อกฟังก์ชั่น 「ทำซ้ำ」 สำหรับด่านนั้น โปรดทราบว่าเมื่อใช้ฟังก์ชั่น 「ทำซ้ำ」 จะไม่ได้รับอัตราการประสาน.\n4,     สามารถใช้การสนับสนุนจากสมาคมศิษย์เก่าเพื่อช่วยให้ผ่านด่านได้ง่ายขึ้น.\n\n<Title:ความปรารถนาในการแสวงหาความรู้>\n「ความปรารถนาในการแสวงหาความรู้」 มีร้านค้า 3 ร้าน โดยจะเปิดในเวลาตามนี้：\n·「วิชาเลือกทั่วไป」： เปิดวันที่ 2 มิถุนายน เวลา 09:00.\n·「วิชาเลือกเรียนวิทยาศาสตร์」： เปิดวันที่ 4 มิถุนายน เวลา 09:00.\n·「วิชาเลือกเรียนวรรณคดี」： เปิดวันที่ 6 มิถุนายน เวลา 09:00.\nในร้านค้า คุณสามารถเลือกซื้อสินค้าได้โดยตรง.\n\n<Title:โบนัสกิจกรรม>\n1,     ผู้พิทักษ์ที่มีผู้ปลุกตื่นหรือวงล้อมชีวิตที่เฉพาะเจาะจง(ไม่จำเป็นต้องอยู่ในทีม) สามารถเพิ่มโอกาสที่ 「หนังสือความรู้ทั่วไป」,     「หนังสือคณิตศาสตร์」,     「หนังสือวรรณกรรม」 ดรอปเพิ่มเติมในภารกิจด่านของ 「บินข้ามฟ้าใส」 โดยโบนัสเพิ่มเติมจะตามนี้：\n·ผู้ปลุกตื่น 「คาสเตอร์」： การตื่นพลัง 0/1/2/3 ขึ้นไป,      เพิ่ม 20%/30%/40%/50%.\n·วงล้อมชีวิต SSR 「อิสรภาพอันหนักอึ้ง」： ตำแหน่งซ้อน 0/1/2/3 ขึ้นไป,      เพิ่ม 20%/30%/40%/50%.\n·วงล้อมชีวิต SR 「ขนนกที่โดดเดี่ยว」： ตำแหน่งซ้อน 0/1/2/3 ขึ้นไป,      เพิ่ม 20%/30%/40%/50%.\n2,     โบนัสกิจกรรมจากผู้ปลุกตื่นหรือวงล้อมชีวิตต่าง ๆ จะคำนวณโดยการเพิ่มแบบทบต้น.\n3,     โดยเฉพาะอย่างยิ่ง รางวัลความสำเร็จจากครั้งแรกในระดับความยากบ้าคลั่งจะไม่ได้รับผลกระทบจากโบนัสกิจกรรม.\n\n<Title:การเดินทางในฝัน>\n1,     ได้รับ 「หนังสือความรู้ทั่วไป」 อัตโนมัติ 60 เล่มต่อชั่วโมง โดยสามารถเก็บสะสมได้สูงสุด 25 ชั่วโมง.\n\n<Title:โลกแห่งความฝันประหลาด>\n1,     ในช่วงระยะเวลากิจกรรม 「โลกแห่งความฝันประหลาด：เหนือขอบฟ้า·บน」 สามารถปลดล็อกได้ฟรี.\n2,     หลังจบกิจกรรม ความคืบหน้าการสืบสวนของ 「โลกแห่งความฝันประหลาด：เหนือขอบฟ้า·บน」 จะถูกเก็บรักษา คุณยังสามารถได้รับรางวัลการสืบสวนที่สอดคล้องกับช่วงกิจกรรมหากทำการสืบสวนเหตุการณ์ที่ยังไม่เสร็จสิ้นในช่วงกิจกรรมเสร็จสมบูรณ์ หากคุณไม่ได้ปลดล็อก 「โลกแห่งความฝันประหลาด：เหนือขอบฟ้า·บน」 ในช่วงกิจกรรม คุณยังคงสามารถใช้ 「จุดเริ่มต้นของความเป็นจริง」×7 ในการปลดล็อกหลังจบกิจกรรม.\n3,     ไม่ว่าคุณจะอยู่ในช่วงกิจกรรมหรือไม่ก็ตาม หากคุณผ่านด่าน 「โลกแห่งความฝันประหลาด：เหนือขอบฟ้า·บน」 คุณจะได้รับ 「คำสั่งกุญแจ：การเบี่ยงเบนของชะตากรรม」."
  },
