  Activity_90864_ActivityTips = {
    Text = "<Title: บทเพลงอาลัยแห่งกะโหลก·บันทึกการเดินทางจำกัดเวลา>\n·บันทึกการเดินทางจำกัดเวลาครั้งนี้ประกอบด้วยชุดของขวัญ 8 ชุด โดยชุดแรกสามารถรับได้ฟรีโดยตรง ส่วนชุดที่ 2–8 จะต้องซื้อ「บทเพลงอาลัยแห่งกะโหลก·บันทึกการเดินทางจำกัดเวลา」ก่อนจึงจะรับได้\n·หลังจากซื้อ「บทเพลงอาลัยแห่งกะโหลก·บันทึกการเดินทางจำกัดเวลา」แล้ว สามารถรับรางวัลชุดของขวัญที่ 2 ได้ทันที ส่วนชุดของขวัญถัดไปจะต้องรอเวลาที่กำหนดก่อนจึงจะรับได้\n·หากซื้อ「บทเพลงอาลัยแห่งกะโหลก·บันทึกการเดินทางจำกัดเวลา」ก่อนวันที่ 21 กรกฎาคม เวลา 9：00 จะได้รับรางวัลพิเศษเพิ่มเติม：อวาตาร์สุดพิเศษ「สายตาหิวโหยแห่งราตรีนิรันดร์」,     「บัตรเชิญของผู้ไร้รูป」×10！หากซื้อหลังวันที่ 21 กรกฎาคม เวลา 9：00 จะไม่ได้รับรางวัลพิเศษจำกัดเวลาอีกต่อไป\n·「บทเพลงอาลัยแห่งกะโหลก·บันทึกการเดินทางจำกัดเวลา」มีระยะเวลาจำกัดในการซื้อ หากเลยกำหนดจะไม่สามารถซื้อได้อีก กรุณาให้ผู้พิทักษ์พิจารณาซื้อก่อนวันที่ 18 สิงหาคม เวลา 9：00"
  },
  Activity_90865_ActivityName = {
    Text = "การเคลื่อนไหวแห่งห้วงลึก·บันทึกจำกัดเวลา"
