  Activity_90865_ActivityTips = {
    Text = "<Title: การเคลื่อนไหวของทารกในครรภ์แห่งทะเลลึก·การเดินทางจำกัดเวลา>\n·การเดินทางจำกัดเวลาครั้งนี้ประกอบด้วย 8 แพ็กเกจ ซึ่งแพ็กเกจแรกสามารถรับได้ฟรีโดยตรง แพ็กเกจที่ 2-8 ต้องซื้อ「การเคลื่อนไหวของทารกในครรภ์แห่งทะเลลึก·การเดินทางจำกัดเวลา」จึงจะสามารถรับได้.\n·หลังจากซื้อ「การเคลื่อนไหวของทารกในครรภ์แห่งทะเลลึก·การเดินทางจำกัดเวลา」สามารถรับรางวัลแพ็กเกจที่ 2 ได้ทันที แพ็กเกจถัดไปต้องรอเวลานานกว่าจึงจะสามารถรับได้.\n·หากซื้อ「การเคลื่อนไหวของทารกในครรภ์แห่งทะเลลึก·การเดินทางจำกัดเวลา」ก่อนเวลา 9:00 น. ของวันที่ 17 พฤศจิกายน จะได้รับรางวัลเพิ่มเติม: อวตารพิเศษ「บทเพลงโศกของทะเลลึก」,     「คำเชิญของวิญญาณไร้รูปร่าง」×10! หากซื้อหลังเวลา 9:00 น. ของวันที่ 17 พฤศจิกายน จะไม่ได้รับรางวัลพิเศษจำกัดเวลาอีกต่อไป.\n·การซื้อ「การเคลื่อนไหวของทารกในครรภ์แห่งทะเลลึก·การเดินทางจำกัดเวลา」มีข้อจำกัดด้านเวลา หากเลยกำหนดจะไม่สามารถซื้อได้อีก กรุณาผู้พิทักษ์พิจารณาซื้อก่อนเวลา 9:00 น. ของวันที่ 15 ธันวาคม.."
  },
  Activity_91026_ActivityName = {
    Text = "ปลดล็อกด่านเนื้อเรื่องรองฟรี"
  },
  Activity_91027_ActivityName = {
    Text = "การพิชิตอันยิ่งใหญ่"
  },
  Activity_91027_ActivityPlot = {
    Text = "ยุคที่ยิ่งใหญ่อาจสูญสิ้นในที่สุด แต่เจตจำนงของนักรบผู้ยิ่งใหญ่เหล่านั้นจะไม่มีวันสูญสิ้น.\nหลุมศพไม่สามารถกลบพวกเขาไว้ โซ่ไม่สามารถทำให้พวกเขาเชื่องได้.\nเมื่อมีเส้นทางใหม่เกิดขึ้น อาหารย่างอร่อยที่เรียกร้องอยู่ที่ปลายทางนั้น นักรบได้เริ่มการเปิดตัว เก็บเกี่ยวของที่มีเกียรติในกระเป๋าของพวกเขา.\nให้เราขับร้องเพื่อความกล้าหาญที่ไม่สิ้นสุดนี้ เพื่ออาณาจักรอันศักดิ์สิทธิ์นี้! \nโรม! โรม!"
  },
  Activity_91027_ActivityStageEndContent = {
    Text = "กิจกรรมได้สิ้นสุดลงแล้ว ขณะนี้สามารถเข้าร่วม「ถวายเครื่องบรรณาการ」ได้เพียงอย่างเดียว"
  },
  Activity_91027_ActivityTips = {
    Text = "<Title:บทนำกิจกรรม>\n1 ในระยะเวลาของกิจกรรม ผู้พิทักษ์สามารถเก็บรวบรวมสกุลเงินกิจกรรม「เนื้อย่างอร่อยของเรโอ」ผ่านการเล่นแบบจำกัดเวลา「การล่าที่ศักดิ์สิทธิ์」 โดย「เนื้อย่างอร่อยของเรโอ」สามารถใช้เพื่อซื้อสินค้าที่「ถวายของบรรณาการ」รวมถึงแกนกลางของลูเมน แกนบริสุทธิ์ ฯลฯ \n2 ในระยะเวลาของกิจกรรม「โลกแห่งความฝันประหลาด: การพิชิตห้องครัว」จะสามารถปลดล็อกได้ฟรีในระยะเวลาจำกัด \n\n<Title:เวลาในการจัดกิจกรรม>\n1 ตั้งแต่วันที่ 30 มิถุนายน 9:00 - 21 กรกฎาคม 9:00(GMT+8) สามารถเข้าร่วมกิจกรรมการเล่นทั้งหมดได้ \n2 ตั้งแต่วันที่ 21 กรกฎาคม 9:00 - 28 กรกฎาคม 9:00(GMT+8) สามารถเข้าร่วมได้เฉพาะ「ถวายของบรรณาการ」และรางวัลความสำเร็จเท่านั้น \n\n<Title:การล่าที่ศักดิ์สิทธิ์>\n1「การล่าที่ศักดิ์สิทธิ์」มี 5 ด่าน โดยจะเปิดให้เล่นโดยอัตโนมัติทุก 2 วัน \n2 ในแต่ละครั้งที่ท้าทายจะใช้「เมโนฟิน」× 120 และหากท้าทายสำเร็จจะได้รับสกุลเงินกิจกรรม \n3 เมื่อผ่านด่านแล้ว จะปลดล็อกฟังก์ชัน「ทำซ้ำ」ของด่านนั้น โปรดทราบ: เมื่อใช้ฟังก์ชัน「ทำซ้ำ」จะไม่สามารถรับอัตราการประสานได้ \n4 สามารถใช้การสนับสนุนจากสมาคมศิษย์เก่าเพื่อช่วยให้คุณผ่านด่านได้ง่ายขึ้น \n\n<Title:ถวายของบรรณาการ>\nในร้าน「ถวายของบรรณาการ」สามารถใช้สกุลเงินกิจกรรม「เนื้อย่างอร่อยของเรโอ」เลือกซื้อสินค้าได้โดยตรง \n\n<Title:โลกแห่งความฝันประหลาด>\n1 ในระยะเวลาของกิจกรรม「โลกแห่งความฝันประหลาด: การพิชิตห้องครัว」สามารถปลดล็อกได้ฟรี \n2 หลังจากกิจกรรมสิ้นสุดลง ความก้าวหน้าในการสืบสวนของ「โลกแห่งความฝันประหลาด: การพิชิตห้องครัว」จะถูกเก็บรักษาไว้ และเมื่อเสร็จสิ้นเหตุการณ์การสืบสวนที่ไม่สำเร็จในระยะเวลาของกิจกรรม คุณยังสามารถรับรางวัลการสืบสวนที่เหมือนกับในระยะเวลาของกิจกรรมได้ หากในระยะเวลาของกิจกรรมยังไม่ได้ปลดล็อก「โลกแห่งความฝันประหลาด: การพิชิตห้องครัว」 หลังจากกิจกรรมสิ้นสุดลงยังสามารถใช้「จุดเริ่มต้นของความเป็นจริง」×7 เพื่อปลดล็อกได้ \n3 ไม่ว่าจะอยู่ในระยะเวลาของกิจกรรมหรือไม่ เมื่อผ่าน「โลกแห่งความฝันประหลาด: การพิชิตห้องครัว」แล้วจะสามารถรับ「คำสั่งกุญแจ: ความมุ่งมั่นในการล่า」ได้."
  },
