  Activity_94860_ActivityTips = {
    Text = "<Title:บทนำกิจกรรม>\n1,     ในช่วงกิจกรรม「โลกแห่งความฝันประหลาด：ลาก่อน เนเวอร์แลนด์」สามารถปลดล็อคฟรีในช่วงเวลาจำกัด！\n2,     ในช่วงกิจกรรม หากเข้าสู่ระบบสะสม 7 วัน จะได้รับ「แกนกลางของลูเมน」×10 ใน「เทศกาลเชอเช่」และในวันที่ 7 จะได้รับภาพโปรไฟล์ต่อสู้ลิมิเต็ด「วอลเลย์บอล『นายพล』」เพิ่มเติม.\n\n<Title:เวลาในการจัดกิจกรรม>\n1,     ตั้งแต่วันที่ 1 กันยายน 9:00 - 6 ตุลาคม 9:00(GMT+8) สามารถเข้าร่วมกิจกรรมได้ทั้งหมด.\n\n<Title:โลกแห่งความฝันประหลาด>\n1,     ในช่วงกิจกรรม「โลกแห่งความฝันประหลาด：ลาก่อน เนเวอร์แลนด์」สามารถปลดล็อคฟรีได้.\n2,     เมื่อกิจกรรมสิ้นสุดลง ความก้าวหน้าการสืบสวนของ「โลกแห่งความฝันประหลาด：ลาก่อน เนเวอร์แลนด์」จะถูกเก็บรักษาไว้ หากทำเหตุการณ์การสืบสวนที่ยังไม่เสร็จในช่วงกิจกรรมก็สามารถได้รับรางวัลการสืบสวนที่ตรงกันกับช่วงกิจกรรมได้ หากในช่วงกิจกรรมไม่ได้ปลดล็อค「โลกแห่งความฝันประหลาด：ลาก่อน เนเวอร์แลนด์」 หลังจากกิจกรรมสิ้นสุดลงยังสามารถใช้「จุดเริ่มต้นของความเป็นจริง」×7 เพื่อปลดล็อคได้.\n3,     ไม่ว่าจะอยู่ในช่วงกิจกรรมหรือไม่ เมื่อผ่านด่าน「โลกแห่งความฝันประหลาด：ลาก่อน เนเวอร์แลนด์」แล้วจะได้รับ「คำสั่งกุญแจ：ความทรงจำกลางฤดูร้อนที่ถ่ายทอดไว้」.."
  },
  Activity_94860_BannerText = {
    Text = "กิจกรรมการเล่นเปิดให้เข้าร่วมแบบจำกัดเวลา!"
  },
  Activity_95190_ActivityName = {
    Text = "ปลดล็อกด่านเนื้อเรื่องรองฟรี"
  },
  Activity_95191_ActivityName = {
    Text = "แสงสว่างระยิบระยับที่ตกลงมา"
  },
  Activity_95191_ActivityPlot = {
    Text = "พวกมันขับร้องเพลงที่ไม่เคยลืม เพื่อต้อนรับพระผู้เป็นเจ้าที่ไม่ดับสูญ.\nพระองค์จะนำแสงสว่างนับพันแสงจากสวรรค์หล่นลงมา เล่าถึงความรุ่งเรืองที่ไม่สิ้นสุด.\nเมื่อพระองค์มาถึง แสงสีอำพันจะปกคลุมโลก.\nนี่คือพิธีฝังศพที่พระองค์มอบให้แก่โลก."
