  Activity_95492_ActivityTips = {
    Text = "<Title:บทนำ>\n1. ในระยะเวลากิจกรรม ผู้พิทักษ์สามารถเข้าร่วมเพื่อรับรางวัลลงทะเบียนใน 「รางวัลของพระราชา」 เมื่อเข้าสู่ระบบทุกวัน\n2. รางวัลจะได้รับการปลดล็อคตามจำนวนวันที่ผู้พิทักษ์เข้าสู่ระบบและรางวัลวันที่จะรีเฟรชในเวลา 09:00 น.(GMT+8)\n"
