  },
  Activity_95977_ActivityPlot = {
    Text = "ความตายไม่ได้เป็นเพียงจุดสิ้นสุดของชีวิต.\nอย่ากลัวความตาย แขกที่รัก.\nในงานเฉลิมฉลองที่บ้าคลั่นนี้ ท่านจะได้เห็นความสวยงามของความตายร่วมกับเจ้าของที่อ่อนโยน"
