  Activity_96617_ActivityName = {
    Text = "ใบเมเปิลแดงหลายครา"
  },
  Activity_96617_ActivityTips = {
    Text = "<Title:กฎกิจกรรม>\n1,     หลังจากผู้พิทักษ์ทำภารกิจบันทึกการเดินทางที่กำหนดเสร็จแล้ว สามารถรับรางวัลได้ใน「ใบเมเปิลแดงหลายครา」\n2,     「ใบเมเปิลแดงหลายครา」จะสิ้นสุดในวันที่ 23 มีนาคม เวลา 9:00(GMT+8)\n3,     หลังจากปลดล็อก「บันทึกการเดินทางขั้นสูง」แล้ว จะสามารถรับรางวัลเพิ่มเติมหลังทำภารกิจเสร็จ\n4,     โปรดทราบ：「บันทึกการเดินทางขั้นสูง」ที่ปลดล็อกในกิจกรรมนี้มีผลเฉพาะในกิจกรรมนี้เท่านั้น กรุณาให้ผู้พิทักษ์พิจารณาใช้จ่ายอย่างมีเหตุผล"
  },
  Activity_96617_BannerText = {
    Text = "กิจกรรมบันทึกการเดินทางพิเศษเปิดให้บริการจำกัดเวลา!"
  },
  Activity_96838_ActivityName = {
    Text = "ข้อความชั่วคราว"
  },
  Activity_96838_ActivityPlot = {
    Text = "การระเบิดของสีหนึ่งครั้ง ความบ้าคลั่งในรูปแบบหนึ่ง.\nภาพที่เกือบจะปกติถูกป้ายด้วยรอยเลือด,     \nภายใต้มีดโกน วิญญาณสั่นเทาและกระซิบอยู่บนผืนผ้าใบ.\nศิลปะที่แท้จริงและสมบูรณ์ที่สุดซ่อนอยู่ในความบ้าคลั่งและความไร้สาระ,     \nเฉพาะความบ้าคลั่งที่ฉีกขาดจากผิวเผินเท่านั้น ที่สามารถเปิดเผยด้านในของโลกได้."
  },
  Activity_96838_ActivityStageEndContent = {
    Text = "กิจกรรมสิ้นสุดลง ปัจจุบันสามารถเข้าร่วมได้เฉพาะ「เวิร์คช็อปของพิคแมน」"
  },
  Activity_96838_ActivityTips = {
    Text = "<Title:แนะนำกิจกรรม>\n1,     ในช่วงเวลากิจกรรม ผู้พิทักษ์สามารถเก็บรวบรวมสกุลเงินกิจกรรม 「ย้อมแห่งความจริง」,     「คราบแห่งความฝัน」,     「การครอบงำอันบ้าคลั่ง」 ผ่านการเล่นเกมจำกัดเวลา「ข้อความชั่วคราว」 และ 「รางวัลความสำเร็จ」,      「ย้อมแห่งความจริง」,      「คราบแห่งความฝัน」,      「การครอบงำอันบ้าคลั่ง」 สามารถซื้อสินค้าได้ใน 「ห้องทำงานของพิกแมน」 รวมถึงวงล้อมชีวิต SR รางวัลกิจกรรมพิเศษ 「แปรงแห่งความปรารถนา」,     แกนกลางของลูเมน และแกนบริสุทธิ์ ฯลฯ.\n2,     ในช่วงเวลากิจกรรม สามารถปลดล็อกฟรีสำหรับ 「การล่องเรือในจิตสำนึก：ภาพวาดแห่งโลกบิดเบี้ยว」,     และผู้เล่นจะได้รับหัวกิจกรรมพิเศษ 「ชื่อของกุญแจเงิน：พิคแมน」 ด้วยการทำสำเร็จกิจกรรมต่างๆ！\n\n<Title:เวลาของกิจกรรม>\n1,     8 กันยายน เวลา 9:00 น. - 22 กันยายน เวลา 9:00 น.(GMT+8),     สามารถเข้าร่วมกิจกรรมทั้งหมดได้.\n2,     22 กันยายน เวลา 9:00 น. - 29 กันยายน เวลา 9:00 น.(GMT+8),     สามารถเข้าร่วมได้เฉพาะ「ห้องทำงานของพิกแมน」 และรางวัลความสำเร็จ.\n\n<Title:ข้อความชั่วคราว>\n1,     「ข้อความชั่วคราว」มีทั้งหมด 7 ด่าน ซึ่งจะปลดล็อกทีละด่านโดยอัตโนมัติทุกวัน\n2,     ทุกครั้งที่ท้าทายจะใช้ 「เมโนฟิน」×120 เมื่อทำการท้าทายสำเร็จจะได้รับสกุลเงินกิจกรรม.\n3,     หลังผ่านด่านแล้ว จะปลดล็อกฟังก์ชั่น 「ทำซ้ำ」ของด่านนั้น โปรดทราบว่า：เมื่อใช้ฟังก์ชั่น 「ทำซ้ำ」 จะไม่ได้รับอัตราการประสาน.\n4,     สามารถใช้ความช่วยเหลือจากสมาคมศิษย์เก่าเพื่อให้ผ่านด่านได้ง่ายขึ้น.\n\n<Title:ห้องทำงานของพิกแมน>\n1,     「ห้องทำงานของพิกแมน」 มีสามร้านค้าที่จะเปิดตามเวลาต่อไปนี้：\n·「ห้องทำงานที่แท้จริง」：เปิดวันที่ 8 กันยายน เวลา 9:00 น.\n·「ห้องภาพความฝัน」：เปิดวันที่ 10 กันยายน เวลา 9:00 น.\n·「ห้องวาดภาพบ้าคลั่ง」：เปิดวันที่ 12 กันยายน เวลา 9:00 น.\n2,     ทุกครั้งที่แลกเปลี่ยนจะใช้ 750 「ย้อมแห่งความจริง」/「คราบแห่งความฝัน」/「การครอบงำอันบ้าคลั่ง」,     และจะได้รับของรางวัลในห้องทำงานสุ่ม 5 ชิ้น.\n3,     ของรางวัลในแต่ละห้องทำงานแบ่งเป็นสองประเภท： 「วัสดุพิเศษ」 และ 「ของธรรมดา」,     เมื่อรีเซ็ตจะสามารถกำหนดจำนวนวัสดุพิเศษกลับไปที่ขีดจำกัดได้,     โดยกฎที่ระบุว่า：\n(1)การรีเซ็ตครั้งที่ 1 และ 2：เมื่อไม่มี「วัสดุพิเศษ」ที่เหลืออยู่,     ผู้พิทักษ์สามารถเลือกรีเซ็ต ซึ่งจะทำการรีเซ็ตจำนวน 「วัสดุพิเศษ」 และ 「ของธรรมดา」 ให้กลับไปที่ขีดจำกัด；หรือเลือกแลกเปลี่ยนต่อไป เมื่อไม่มี「ของธรรมดา」ที่เหลืออยู่ จะต้องรีเซ็ตเพื่อลงมือดำเนินการต่อ.\n(2)เริ่มการรีเซ็ตครั้งที่ 3：สามารถรีเซ็ตได้เมื่อไม่มี「ของธรรมดา」เหลืออยู่แล้วเท่านั้น,     รีเซ็ตจะรีเซ็ตจำนวนที่เหลืออยู่ของ 「ของธรรมดา」 ให้ถึงขีดจำกัด,     「วัสดุพิเศษ」จะไม่รีเซ็ตอีกต่อไป.\n\n<Title:เสริมกิจกรรม>\n1,     ผู้พิทักษ์ที่มีผู้ปลุกตื่นหรือวงล้อมชีวิตเฉพาะ(ไม่จำเป็นต้องนำลงสนาม) จะสามารถเพิ่มอัตราการดรอปเพิ่มในรางวัลด่านของ 「ข้อความชั่วคราว」 ซึ่ง「ย้อมแห่งความจริง」,     「คราบแห่งความฝัน」,     「การครอบงำอันบ้าคลั่ง」 โดยมีการเสริมดังต่อไปนี้：\n·ผู้ปลุกตื่น 「พิคแมน」：การตื่นพลัง 0/1/2/3 หรือมากกว่า จะเพิ่ม 20%/30%/40%/50%.\n·วงล้อมชีวิต SSR 「ความขัดแย้งของลัทธิความจริง」：ตำแหน่งซ้อน 0/1/2/3 หรือมากกว่า จะเพิ่ม 20%/30%/40%/50%.\n·วงล้อมชีวิต SR 「แปรงแห่งความปรารถนา」：ตำแหน่งซ้อน 0/1/2/3 หรือมากกว่า จะเพิ่ม 20%/30%/40%/50%.\n2,     อัตราการเพิ่มของ「เสริมกิจกรรม」จากผู้ปลุกตื่นหรือวงล้อมชีวิตต่างๆ จะถูกคิดคำนวณแบบสะสม.\n3,     ข้อพิเศษ รางวัลความสำเร็จในการผ่านด่านระดับความยากบ้าคลั่ง ครั้งแรก จะไม่เสริมกิจกรรม.\n\n<Title:การล่องเรือในจิตสำนึก>\n1,     「การล่องเรือในจิตสำนึก：ภาพวาดแห่งโลกบิดเบี้ยว」สามารถปลดล็อกได้ในช่วงกิจกรรม.\n2,     หลังจากกิจกรรมสิ้นสุด การสืบสวนใน 「การล่องเรือในจิตสำนึก：ภาพวาดแห่งโลกบิดเบี้ยว」 จะถูกเก็บรักษาไว้ ผู้เล่นที่ไม่ได้ทำการสำรวจเหตุการณ์หรือด่านเสร็จในช่วงกิจกรรมยังสามารถรับรางวัลได้เมื่อดำเนินการสำรวจเสร็จสิ้น หากไม่ได้ปลดล็อก 「การล่องเรือในจิตสำนึก：ภาพวาดแห่งโลกบิดเบี้ยว」 ในช่วงกิจกรรมยังสามารถใช้「จุดเริ่มต้นของความเป็นจริง」x3 เพื่อปลดล็อกได้\n3,     ไม่ว่าจะในหรือหลังช่วงกิจกรรม การผ่านด่าน 「การล่องเรือในจิตสำนึก：ภาพวาดแห่งโลกบิดเบี้ยว」 จะได้รับ 「คำสั่งกุญแจ：สีสันแห่งโลกสุญญา」."
  },
